insert into chapter_content (chapter_id, content, updated_at)
values ('c10-hist-ch2', '{"chapter":{"id":"ch2","title":"Nationalism in India","subtitle":"India and the Contemporary World — Chapter 2","sections":[{"id":"s1","number":1,"title":"The First World War, Khilafat and Non-Cooperation","color":"hist-red","icon":"🔥","subsections":[{"id":"ch2-s1-backdrop","title":"The Backdrop — 300 Years in 5 Minutes","narrativeCards":[{"id":"ch2-s1-hook","title":"The Man Who Changed Everything","type":"text","text":"It''s **1919**. India is exhausted. The First World War has drained everything — taxes doubled, millions forcibly recruited into the army, crops failed, and an influenza epidemic has killed **12 to 13 million people**. The British promised that peace would bring relief. Instead, they pass a law that allows them to **jail anyone, without trial, for two years**.\n\nInto this anger walks a man who has just returned from South Africa with a dangerous idea: you can **defeat an empire** — not with guns, but by **refusing to cooperate** with it.\n\nHis name is **Mohandas Karamchand Gandhi**. And his idea will change India forever.","highlight":"**This chapter tells the story of how one man tried to unite 300 million people — and what happened when they discovered they all wanted different things from freedom.**"},{"id":"ch2-s1-backdrop-1","title":"Before Gandhi: 300 Years of Resistance","type":"text","text":"To understand WHY Gandhi mattered, you need to know what came before him.\n\n**1612**: The East India Company arrives in India — just to trade.\n**1757**: They''re ruling India.\n**1857**: The first major revolt — the Sepoy Mutiny. But it''s **regional** (Meerut, Delhi, Lucknow), **fragmented** (no single leader), and **crushed** within a year.\n\nFor the next **60 years**, there are scattered protests, petitions, and revolts. All defeated. All regional. All without a unifying leader or method.","highlight":"**Before Gandhi:** Every revolt was (1) regional — not national (2) fragmented — no single leader (3) quickly crushed. India resisted for 300 years. But never **together**."},{"id":"ch2-s1-backdrop-2","title":"What Was the Pattern?","type":"text","text":"Here''s the pattern across **every resistance before Gandhi**:\n\n**1.** All were about **economic exploitation** — taxes, land, wages\n**2.** All were **regional** — one district, one province at a time\n**3.** All had **no single unifying leader** — local heroes, not national ones\n**4.** All were **short-lived** — put down within months or years\n\nFor a movement to succeed against the British Empire, it needed to be **national**, **united**, **sustained**, and led by someone who could speak to **all of India**. That''s what Gandhi brought.","highlight":"**The pattern:** Every pre-Gandhi revolt was regional + fragmented + short-lived. Gandhi''s genius was making the movement **national, united, and non-violent**.","inlineQuiz":{"question":"What was common across all Indian revolts before Gandhi?","options":["They were regional, fragmented, and quickly crushed","They were all successful in driving out the British","They all used non-violent methods","They were all led by the Indian National Congress"],"correctIndex":0,"explanation":"Before Gandhi, every revolt was regional (limited to one area), fragmented (no single leader), and short-lived (quickly suppressed). Gandhi''s contribution was making the movement national, united, and sustained."}}]},{"id":"ch2-s1-wwi","title":"The First World War and Its Impact","narrativeCards":[{"id":"ch2-s1-wwi-intro","title":"A New Political and Economic Situation","type":"text","text":"Before we meet Gandhi, we must understand the **world he stepped into** — because, as the NCERT puts it, the **First World War (1914–1918) created a new economic and political situation** in India. The war was fought thousands of kilometres away in Europe, yet it **changed the lives of ordinary Indians** completely. The hardship it caused is the soil in which Indian nationalism grew. Let''s see exactly how the war broke India.","highlight":"**Start here (NCERT):** The First World War created a new economic and political situation in India. Understanding the war''s impact is the foundation of this whole chapter."},{"id":"ch2-s1-wwi-impact","title":"The War That Broke India","type":"text","text":"The First World War **devastated India** even though the fighting was in Europe:\n\n**1.** **Defence spending soared**, paid for by **war loans** and by **raising taxes** — customs duties were raised and **income tax was introduced** for the first time.\n**2.** **Prices doubled** — between 1913 and 1918, prices roughly doubled, hitting the common people hardest.\n**3.** **Forced recruitment** — villages were compelled to supply soldiers for a war they had nothing to do with, causing deep anger.\n**4.** **Crops failed** (1918–19 and 1920–21), leading to acute **food shortages**.\n**5.** An **influenza epidemic** struck — and according to the 1921 census, **12 to 13 million people** died of famine and disease.\n\nPeople hoped that when the war ended, their hardship would end too. **It didn''t.**","highlight":"**WWI''s impact on India (very frequently asked):** higher taxes + war loans • prices doubled • forced recruitment • crop failures & food shortages • influenza epidemic (12–13 million dead).","inlineQuiz":{"question":"Roughly how many people in India died due to famine and the influenza epidemic linked to the war years?","options":["1–2 million","12–13 million","5 million","20 million"],"correctIndex":1,"explanation":"According to the 1921 census, 12 to 13 million people perished as a result of famines and the influenza epidemic during 1918–1921."}},{"id":"ch2-s1-wwi-vocab","type":"vocabulary","text":"Forced Recruitment — A process by which the colonial state **forced people to join the army against their will**. During the First World War, the British compelled villages in many parts of India to supply young men as soldiers. It was **coercion, not voluntary service** — and the resentment it caused ran deep across the countryside."}]},{"id":"ch2-s1-satyagraha","title":"The Idea of Satyagraha","narrativeCards":[{"id":"ch2-s1-gandhi-returns","title":"Gandhi Returns — January 1915","type":"text","text":"**January 1915.** A 45-year-old lawyer returns to India after **21 years in South Africa**. There, he had fought against racist laws using a method he called **satyagraha** — and won. He is already famous. The Indian National Congress welcomes him. But Gandhi doesn''t rush into politics. He spends his first years **travelling India**, understanding the lives of ordinary people — peasants, workers, the poor."},{"id":"ch2-s1-satyagraha-define","type":"vocabulary","text":"Satyagraha — **Satya** (truth) + **Agraha** (insistence) = **insistence on / holding firmly to the truth**. It was the novel method of mass agitation that Gandhi had developed in South Africa and now brought to India."},{"id":"ch2-s1-satyagraha-idea","title":"The Idea of Satyagraha — In Simple Steps","type":"flowchart","text":"NCERT explains satyagraha as a chain of simple ideas. Tap each one to understand it:","steps":[{"label":"The power of truth","detail":"Satyagraha emphasised the **power of truth** and the **need to search for truth**. Gandhi believed truth itself was a force more powerful than any weapon."},{"label":"If the cause is true, no violence is needed","detail":"If the cause was **true** and the struggle was **against injustice**, then **physical force was not necessary** to fight the oppressor. A just cause does not need a sword."},{"label":"Win without vengeance — through non-violence","detail":"Without seeking **vengeance** or being **aggressive**, a satyagrahi could **win the battle through non-violence**. The satyagrahi is patient and self-suffering, never hateful."},{"label":"Appeal to the oppressor''s conscience","detail":"This was done by **appealing to the conscience of the oppressor**. People — including the oppressors — had to be **persuaded to see the truth**, not forced to accept it through violence."},{"label":"Truth must ultimately triumph","detail":"By this struggle, **truth was bound to ultimately triumph**. Gandhi believed this *dharma* of non-violence could **unite all Indians** in a single struggle."}],"highlight":"**Satyagraha (NCERT):** power of truth → a true cause needs no physical force → win through non-violence without vengeance → appeal to the oppressor''s conscience → truth must finally win. It is \"the weapon of the strong, not the weak.\""},{"id":"ch2-s1-source-a","type":"source","text":"Gandhi on Satyagraha: \"It is said of ''passive resistance'' that it is the weapon of the weak, but the power which is the subject of this article can be used only by the strong. This power is not passive resistance; indeed it calls for intense activity... Satyagraha is pure soul-force. Truth is the very substance of the soul... Non-violence is the supreme dharma.\""},{"id":"ch2-s1-satyagraha-why","title":"Why Non-Violence? Was Gandhi Just Being Idealistic?","type":"text","text":"Here''s the practical reality Gandhi understood: **India could never defeat Britain in a military war.** The British had the most powerful army in the world. India''s hundreds of millions could never match that firepower.\n\nBut there was something India had that Britain didn''t: **numbers**. If 300 million people simply **refused to cooperate** — refused to work in British offices, refused to buy British goods, refused to obey British laws — the entire system would **collapse**. You don''t need guns when you have 300 million people saying \"No.\"\n\nNon-violence wasn''t just moral. It was **strategic**.","highlight":"**WHY non-violence:** (1) India couldn''t match British military power (2) But 300 million people refusing to cooperate = the empire collapses (3) Non-violence was BOTH a moral principle AND a practical strategy."}]},{"id":"ch2-s1-early-satyagrahas","title":"Gandhi Proves the Method — Three Satyagrahas","narrativeCards":[{"id":"ch2-s1-champaran","title":"Champaran, 1917 — The First Test","type":"text","text":"**Bihar, 1917.** Indigo farmers in Champaran were forced to grow indigo on their land — a crop that **destroyed soil fertility** and was sold at prices fixed by European planters. Gandhi travelled there, listened to the farmers, and organised his **first satyagraha in India**.\n\nHe was **arrested**. But the movement didn''t die — it grew. Public pressure forced the British to appoint an inquiry. The result: **tax relief for farmers** and the right to grow crops of their own choice.","highlight":"**Champaran (1917):** Gandhi''s first Indian satyagraha. Against indigo planters. Gandhi arrested → movement grew → farmers won tax relief."},{"id":"ch2-s1-ahmedabad-kheda","title":"Ahmedabad & Kheda, 1918 — The Method Works","type":"text","text":"**Ahmedabad, 1918:** Cotton mill workers demanded fair wages. Gandhi supported them with a satyagraha. **Workers won.**\n\n**Kheda, Gujarat, 1918:** Crops failed. Peasants couldn''t pay revenue. Gandhi organised them to demand tax relief. **The British agreed.**\n\nThree satyagrahas in two years. All three won. Gandhi had proved the method worked.","highlight":"**Three satyagrahas, three wins:** Champaran (1917), Ahmedabad (1918), Kheda (1918). All about economic exploitation. All won through non-violent pressure."},{"id":"ch2-s1-three-satyagrahas","title":"Gandhi''s Three Early Satyagrahas (1916–1918)","type":"flowchart","text":"Three local satyagrahas in which Gandhi tested and proved his method. Tap each:","steps":[{"label":"Champaran, 1917 — Indigo farmers (Bihar)","detail":"Gandhi travelled to **Champaran in Bihar** to inspire the peasants to struggle against the **oppressive plantation system** that forced them to grow indigo. This was his **first satyagraha in India** — and it won the farmers relief."},{"label":"Kheda, 1917–18 — Peasants (Gujarat)","detail":"In the **Kheda district of Gujarat**, **crops failed** and a plague spread, yet the government demanded full **land revenue**. Gandhi organised a satyagraha to support the peasants'' demand for **relaxation of revenue collection**."},{"label":"Ahmedabad, 1918 — Cotton mill workers","detail":"In **1918, Gandhi went to Ahmedabad** to organise a satyagraha movement among **cotton mill workers**, helping them demand **fair wages**."}],"highlight":"**The three satyagrahas (commonly asked):** Champaran 1917 (indigo farmers, Bihar) • Kheda 1917–18 (peasants, Gujarat) • Ahmedabad 1918 (cotton mill workers). All local, all about economic injustice, all successful."},{"id":"ch2-s1-pattern","title":"But Notice the Pattern...","type":"text","text":"These three victories were impressive. But look carefully — they had the **same limitations** as every revolt before Gandhi:\n\n**1.** All three were about **economic exploitation** — indigo, wages, taxes\n**2.** All three were **regional** — one district at a time\n**3.** All three were **short-lived** — resolved in weeks or months\n\nGandhi had proved satyagraha **works**. But he hadn''t yet built a **national movement**. For that, he needed something bigger — something that could unite ALL of India. That something was about to arrive.","highlight":"**Pattern:** Early satyagrahas were successful BUT still regional + short-lived. Gandhi needed a trigger for a NATIONAL movement.","inlineQuiz":{"question":"In which place did Gandhi organise his first satyagraha in India?","options":["Ahmedabad","Dandi","Kheda","Champaran"],"correctIndex":3,"explanation":"Gandhi''s first satyagraha in India was at Champaran in Bihar (1917), where indigo farmers were being exploited by European planters."}}]},{"id":"ch2-s1-tipping-point","title":"The Tipping Point — Rowlatt Act & Jallianwala Bagh","narrativeCards":[{"id":"ch2-s1-rowlatt","title":"The Rowlatt Act — The Spark","type":"text","text":"Gandhi''s three victories had a deeper effect than just helping farmers and workers. Across India, ordinary people now saw that the British **could be challenged** — and **anti-British feeling was rising fast**. The government grew alarmed at this growing political activity.\n\nSo, in **February 1919**, the British struck back with a harsh new law to **crush political activity** — the **Rowlatt Act**. It gave the government enormous powers:\n\n- **Arrest anyone** suspected of anti-government activity\n- **Detain them without trial** for up to **two years**\n- **No evidence needed** — just suspicion\n\nThe Act was rushed through despite the **unanimous opposition** of the Indian members of the Imperial Legislative Council. Indians realised they had **no real voice** in their own government. Gandhi saw the Act as an insult to every Indian and called for a **nationwide hartal** on **6 April 1919**.","highlight":"**Why the Rowlatt Act? (NCERT framing):** Gandhi''s satyagrahas had stirred rising nationalist feeling → the alarmed government passed the Rowlatt Act to crush political activity → arrest without evidence, detention without trial for 2 years → Gandhi called a nationwide hartal (6 April 1919).","inlineQuiz":{"question":"Why were Indians outraged by the Rowlatt Act?","options":["It increased taxes on Indian goods","It banned the Indian National Congress","It allowed detention without trial and was passed despite Indian opposition","It forced Indians to fight in World War I"],"correctIndex":2,"explanation":"The Rowlatt Act gave the government power to detain political prisoners without trial for two years. It was passed despite unanimous opposition from Indian members of the Legislative Council — showing Indians had no real voice."}},{"id":"ch2-s1-hartal","title":"6 April 1919 — India Stops","type":"figure","text":"On **6 April**, the hartal began. Rallies were organised across the country. Workers went on strike in railway workshops. Shops closed down. The British were alarmed — they had never seen protest on this scale. Scared that communications would be disrupted, they decided to **clamp down**. Local leaders were arrested in Amritsar. Gandhi was barred from entering Delhi. On **10 April**, police in Amritsar fired on a peaceful procession.","imageId":"ch2-fig-1"},{"id":"ch2-s1-martial-law","type":"vocabulary","text":"Martial Law — **Rule by the army instead of the normal government.** Ordinary laws and courts are suspended, and a military commander takes charge with the power to ban gatherings, arrest people and use force. As the Rowlatt protests spread in Amritsar, the British **imposed martial law** there as an extension of their crackdown, and handed command to **General Dyer**. It was under this martial law that the Jallianwala Bagh massacre took place."},{"id":"ch2-s1-jallianwala-buildup","title":"13 April 1919 — The Day That Changed India","type":"figure","text":"With **martial law in force and General Dyer in command**, the city of Amritsar was tense. Then, on **13 April 1919**, a large crowd gathered in the enclosed ground of **Jallianwala Bagh** (shown here in a photograph taken in 1919, months after the massacre).\n\nSome had come to protest the Rowlatt Act. But many were **villagers from outside the city** who had come for the annual **Baisakhi fair**. Crucially, **they did not even know that martial law had been imposed** — so they had no idea they were breaking any order by gathering.\n\nAs you can see, the ground was surrounded by **high walls and houses on all sides**, with only a few **narrow exits**.","imageId":"ch2-fig-15"},{"id":"ch2-s1-jallianwala","title":"Jallianwala Bagh","type":"figure","text":"**General Dyer** (pictured here) entered the ground with his troops. He didn''t warn the crowd. He didn''t ask them to leave. He **blocked the exits**.\n\nThen he **ordered his troops to open fire**.\n\nFor **ten minutes**, they fired on an unarmed crowd — men, women, children, elderly people who had only come for a fair.\n\n**Hundreds were killed.** Many jumped into a well inside the compound trying to escape the bullets.\n\nWhen asked later why he did it, Dyer said his object was **\"to produce a moral effect\"** — to create a feeling of **terror and awe** in the minds of satyagrahis.","imageId":"ch2-fig-16","highlight":"**Jallianwala Bagh (13 April 1919):** General Dyer blocked exits and ordered firing on unarmed crowd for 10 minutes. Hundreds killed. His goal: \"to produce a moral effect.\" This became the tipping point of Indian nationalism."},{"id":"ch2-s1-jallianwala-figure","type":"figure","text":"The aftermath was horrifying. As news of the massacre spread, crowds took to the streets in many North Indian towns. There were strikes, clashes with police, and attacks on government buildings. The government responded with **brutal repression**: satyagrahis were forced to rub their noses on the ground, crawl on the streets, and do *salaam* to British officers. Villages around Gujranwala were bombed from the air.","imageId":"ch2-fig-3"},{"id":"ch2-s1-jallianwala-aftermath","title":"After the Massacre","type":"text","text":"Seeing the violence spread, Gandhi called off the Rowlatt satyagraha. He realised something crucial: the movement had been limited mostly to **cities and towns**. If he wanted to truly challenge the British, he needed a movement that went **deeper** — into the villages, into the countryside, across religious lines.\n\nHe needed to unite **Hindus and Muslims**. And he found a way to do it — through an issue that had nothing to do with India."}]},{"id":"ch2-s1-khilafat","title":"The Khilafat Connection — Uniting Hindus and Muslims","narrativeCards":[{"id":"ch2-s1-khilafat-issue","title":"An Unexpected Bridge","type":"text","text":"Here''s how it happened: the First World War ended with the **defeat of the Ottoman Empire** (Turkey). There were rumours that a harsh peace treaty would be imposed, stripping the **Ottoman emperor** — known as the **Khalifa** — of his powers.\n\nThe Khalifa wasn''t just a political leader. He was the **spiritual head of the Islamic world**. Muslims across the globe were outraged. In India, a **Khilafat Committee** was formed in Bombay in **March 1919**. Young Muslim leaders — brothers **Muhammad Ali and Shaukat Ali** — began discussing possible action.","highlight":"**Khilafat issue:** Ottoman Empire defeated in WWI → Khalifa (spiritual head of Islam) threatened → Muslims worldwide outraged → Khilafat Committee formed in Bombay (March 1919)."},{"id":"ch2-s1-khilafat-gandhi","title":"Gandhi''s Strategic Calculation","type":"text","text":"Gandhi saw an **opportunity**. He wanted to launch a broad national movement, but India was deeply divided between Hindus and Muslims. The Khilafat issue gave him a bridge.\n\nHis calculation: **if Congress supports the Khilafat cause, Muslims will support Congress**. For the first time in Indian history, **Hindus and Muslims would fight together** against the British.\n\nAt the **Calcutta Congress session** (September 1920), Gandhi convinced other leaders to launch a **Non-Cooperation movement** in support of **both Khilafat and Swaraj**.","highlight":"**Gandhi''s strategy:** Support Khilafat → win Muslim support → unite Hindus and Muslims → launch a truly NATIONAL movement. This was the first Hindu-Muslim alliance in the freedom struggle.","inlineQuiz":{"question":"Why did Gandhi support the Khilafat Movement?","options":["Because he was personally devoted to the Ottoman Khalifa","Because he saw it as an opportunity to unite Hindus and Muslims in a national movement","Because the British asked him to support it","Because the Khilafat Committee promised to fund the Congress"],"correctIndex":1,"explanation":"Gandhi supported the Khilafat cause because he saw it as an opportunity to bring Hindus and Muslims together under one movement. By linking Khilafat with Swaraj, he created the first Hindu-Muslim alliance in the freedom struggle."}}]},{"id":"ch2-s1-noncooperation","title":"Non-Cooperation Launched","narrativeCards":[{"id":"ch2-s1-hind-swaraj","title":"Gandhi''s Promise — The Theory","type":"text","text":"In his famous book **Hind Swaraj** (1909), Gandhi had made a bold claim: **British rule in India survived only because Indians cooperated with it.** Indian clerks ran their offices. Indian soldiers fought their wars. Indian consumers bought their goods.\n\nIf Indians simply **refused to cooperate** — refused to work in British offices, fight in British wars, buy British goods — the entire system would **collapse within a year**, and **swaraj would come**.\n\nThat was the theory. Now it would be tested.","highlight":"**Gandhi''s promise (Hind Swaraj, 1909):** British rule survives through Indian cooperation. If Indians refuse to cooperate → the empire collapses within a year → swaraj comes. This promise would be tested — and would fail."},{"id":"ch2-s1-swaraj-vocab","type":"vocabulary","text":"Swaraj — **Swa** (self) + **Raj** (rule) = **self-rule**. This is the most important word in the chapter. But here''s the thing CBSE always asks about: **swaraj meant different things to different people**. For the middle class, it meant constitutions and parliaments. For peasants, it meant land and no rent. For plantation workers, it meant freedom to move. The word united people — but the meaning divided them."},{"id":"ch2-s1-programme","title":"The Non-Cooperation Programme","type":"text","text":"Gandhi proposed that the movement should unfold in **stages**:\n\n**Stage 1:** Surrender government-awarded **titles**\n**Stage 2:** **Boycott** civil services, army, police, courts, legislative councils, schools\n**Stage 3:** **Boycott** foreign goods — wear khadi instead\n**Stage 4:** If the government uses repression → launch full **civil disobedience**\n\nThrough the summer of 1920, **Gandhi and Shaukat Ali** toured India extensively, building support. The response was electric.","highlight":"**Non-Cooperation programme (stages):** Surrender titles → Boycott institutions (courts, schools, councils) → Boycott foreign goods → If repressed, launch civil disobedience."},{"id":"ch2-s1-nagpur","title":"December 1920 — The Movement Begins","type":"text","text":"At the **Nagpur Congress session** in December 1920, after intense debate, the Congress formally adopted the Non-Cooperation programme. The movement would begin in **January 1921**.\n\nGandhi made his promise: **refuse to cooperate, and the British would leave within a year.**\n\nThe whole nation believed him. Hindus and Muslims were united. Peasants and workers and students and lawyers — all were ready.\n\nBut what happened next would show that **unity is much harder to build than anger**.","highlight":"**Nagpur Congress (December 1920):** Non-Cooperation programme formally adopted. Gandhi promises swaraj within one year. The movement launches January 1921."},{"id":"ch2-s1-closer","title":"What Comes Next...","type":"text","text":"Gandhi made a promise: refuse to cooperate, and the British would leave within a year. The whole nation believed him. Hindus and Muslims marched together for the first time.\n\nBut here''s what nobody expected: **everyone joined for different reasons**. The middle class wanted constitutions. Peasants wanted land. Tribals wanted forests. Workers wanted wages. And each group interpreted Gandhi''s message in their own way — sometimes going far beyond what he intended.\n\nIn the next section, we''ll see how this movement — which was supposed to be ONE struggle — turned into **five different struggles** wearing the same name.","highlight":"**The story so far:** WWI + Jallianwala Bagh + Khilafat → Gandhi launches Non-Cooperation (1921). The whole nation is united. But unity is about to fracture — because swaraj means different things to different people."},{"id":"ch2-s1-timeline","title":"Section 1 Timeline","type":"timeline-ref","text":"1915 — **Gandhi returns** to India from South Africa\n1917 — **Champaran Satyagraha** — first satyagraha in India (Bihar, indigo farmers)\n1918 — **Ahmedabad** (mill workers) and **Kheda** (peasants) satyagrahas — both successful\n1919 — **Rowlatt Act** passed — detention without trial; Gandhi calls hartal (6 April)\n1919 — **Jallianwala Bagh massacre** (13 April) — General Dyer fires on unarmed crowd\n1919 — **Khilafat Committee** formed in Bombay (March)\n1920 — **Calcutta Congress** (September) — Gandhi links Khilafat with Non-Cooperation\n1920 — **Nagpur Congress** (December) — Non-Cooperation programme formally adopted","highlight":"**Key exam dates:** 1919 (Rowlatt Act + Jallianwala Bagh), 1920 (Nagpur Congress — Non-Cooperation launched). These appear in every CBSE paper."},{"id":"ch2-s1-significance","title":"Why This Section Matters","type":"exam-prep","text":"Q: How did the First World War help in the growth of the National Movement in India?\nMarks: 3 Marks\nA: The war created massive economic hardship — taxes doubled, prices rose, forced recruitment caused anger, crop failures and influenza killed 12-13 million people.\nA: People expected relief after the war but instead got the Rowlatt Act (detention without trial), which showed Indians had no real voice in governance.\nA: The Jallianwala Bagh massacre (1919) became the tipping point — turning widespread anger into a demand for swaraj.\nA: Gandhi linked the Khilafat issue with the independence struggle, creating the first Hindu-Muslim alliance — making the movement truly national.\nTip: This is a frequently asked 3-mark question. Cover: WWI hardship → Rowlatt Act → Jallianwala Bagh → Khilafat unity. Each point = 1 mark.\nTip: For 5-mark version: add Gandhi''s early satyagrahas (Champaran, Ahmedabad, Kheda) and the Non-Cooperation programme details."}]}],"keyPoints":["First World War created economic hardship — taxes doubled, forced recruitment, famine, influenza (12-13 million died)","Gandhi returned from South Africa (1915) with the idea of satyagraha — truth-force, not passive resistance","Early satyagrahas: Champaran (1917), Ahmedabad (1918), Kheda (1918) — proved the method worked","Rowlatt Act (1919) allowed detention without trial — Gandhi called a nationwide hartal (6 April)","Jallianwala Bagh massacre (13 April 1919) — General Dyer fired on unarmed crowd; hundreds killed","Khilafat issue united Hindus and Muslims — Gandhi linked Khilafat with Non-Cooperation","Non-Cooperation Movement launched at Nagpur Congress (December 1920) — boycott British institutions, titles, courts, goods"],"figureIds":["ch2-fig-1","ch2-fig-2","ch2-fig-3","ch2-fig-4"],"sourceIds":["ch2-source-a"],"vocabularyIds":["ch2-vocab-satyagraha","ch2-vocab-forced-recruitment","ch2-vocab-hartal"]},{"id":"s2","number":2,"title":"Differing Strands Within the Movement","color":"hist-blue","icon":"🤝","subsections":[{"id":"ch2-s2-towns","title":"The Movement in the Towns","narrativeCards":[{"id":"ch2-s2-opener","title":"One Movement, Five Different Dreams","type":"text","text":"At the end of Section 1, we said Gandhi made a promise: refuse to cooperate, and swaraj would come within a year. The whole nation believed him. Hindus and Muslims marched together for the first time.\n\nBut here''s what the textbook wants you to understand: **everyone joined for DIFFERENT reasons**. The middle class wanted constitutions and parliaments. Peasants wanted land and no rent. Tribals wanted forests. Workers wanted the freedom to go home. And each group interpreted Gandhi''s message in their own way — sometimes going far beyond what he intended.\n\nThis section is the **most tested section in CBSE board exams**. The 5-mark question \"Why did different social groups join the Non-Cooperation Movement?\" appears almost every year. You must know each group separately.","highlight":"**The core tension:** Everyone wanted swaraj. But swaraj meant different things to different people. This section breaks down WHAT each group did, WHY they joined, and what went wrong."},{"id":"ch2-s2-towns-action","title":"January 1921 — The Cities Erupt","type":"text","text":"The Non-Cooperation-Khilafat Movement began in **January 1921**. In the cities and towns, the response was electric:\n\n**Students** — Thousands left government-controlled schools and colleges\n**Teachers** — Many resigned from government positions\n**Lawyers** — Gave up their lucrative legal practices (including leaders like Motilal Nehru and C.R. Das)\n**Council elections** — Boycotted in most provinces\n**Foreign goods** — Boycotted and burnt in public bonfires\n\nThe economic impact was real: **import of foreign cloth halved** — from **Rs 102 crore to Rs 57 crore** between 1921 and 1922.","highlight":"**Impact in towns:** Students left schools, lawyers quit courts, councils boycotted, foreign cloth imports halved (Rs 102 crore → Rs 57 crore). The boycott was hitting the British where it hurt — their wallets."},{"id":"ch2-s2-boycott-vocab","type":"vocabulary","text":"Boycott — The refusal to deal with, participate in, or buy something as a form of protest. The word comes from **Captain Charles Boycott**, an Irish land agent who was completely ostracised by his community in **1880** when he tried to evict tenants. In India, boycott meant refusing to buy British goods, attend British schools, or serve in British courts. It was the **main weapon** of Non-Cooperation."},{"id":"ch2-s2-towns-slowed","title":"Why Did It Slow Down?","type":"text","text":"But the movement in the towns gradually **lost steam**. WHY? Three reasons:\n\n**1. Khadi was expensive.** Indian cloth made on handlooms cost more than mass-produced British mill cloth. Poor people simply couldn''t afford it. Burning foreign cloth felt noble — but you still needed something to wear.\n\n**2. Alternative institutions were slow to set up.** Students who left British schools had nowhere to go. Indian national schools and colleges came up — but they were too few, too slow. Without replacements, the boycott couldn''t sustain.\n\n**3. People drifted back.** Teachers, lawyers, and students who had sacrificed their careers began returning — because there were no Indian alternatives ready.\n\nThe lesson: **you can''t just tear down a system — you need to build a replacement**. The towns showed that boycott alone isn''t enough.","highlight":"**WHY it slowed in towns:** (1) Khadi was expensive — poor couldn''t afford it (2) Indian schools/courts were slow to set up — no alternatives (3) Students and lawyers drifted back. Boycott without replacement = unsustainable.","inlineQuiz":{"question":"Why did the Non-Cooperation Movement slow down in the cities?","options":["Khadi was expensive, alternative institutions were slow, and people drifted back","The British arrested all the leaders immediately","Muslims refused to participate in the towns","Gandhi asked people to stop the boycott in cities"],"correctIndex":0,"explanation":"The urban movement slowed because khadi was more expensive than British cloth, Indian schools and courts were slow to replace British ones, and without alternatives, students and lawyers gradually returned to British institutions."}}]},{"id":"ch2-s2-countryside","title":"Rebellion in the Countryside","narrativeCards":[{"id":"ch2-s2-countryside-intro","title":"From Cities to Villages — A Different Fight","type":"text","text":"From the cities, the movement spread to the countryside. But here''s the crucial thing: **peasants and tribals didn''t join because of constitutions or councils**. They had never been inside a court or a college. They joined because of **land, rent, and survival**.\n\nAnd this is where the movement gets complicated — because the countryside had its own grievances, its own leaders, and its own methods. Not all of them matched what Gandhi had in mind."},{"id":"ch2-s2-awadh","title":"Awadh Peasants — What Swaraj Meant to Them","type":"text","text":"**Awadh (present-day Uttar Pradesh)** was one of the most oppressed regions in India. Peasants here suffered under **talukdars** (large landowners) and landlords:\n\n**Exorbitant rents** — sometimes 50% or more of the harvest\n**Begar** — forced unpaid labour on landlords'' lands\n**No security of tenure** — a peasant could be thrown off land at any time\n\nTheir leader was an extraordinary man: **Baba Ramchandra** — a sanyasi who had earlier been to **Fiji as an indentured labourer**. He knew exploitation firsthand. He began organising peasants, moving from village to village, talking about overthrowing the oppressive system.\n\nFor these peasants, **swaraj didn''t mean parliaments or constitutions**. It meant: **no more rent. No more begar. No more landlords.**","highlight":"**Awadh peasants:** Led by Baba Ramchandra (a sanyasi, former indentured labourer in Fiji). Grievances: exorbitant rents + begar + no security of tenure. Their swaraj = no more landlords."},{"id":"ch2-s2-begar-vocab","type":"vocabulary","text":"Begar — Labour that villagers were **forced to contribute without any payment**. Landlords would compel peasants to work on their fields, build roads, or carry goods — for free. It was a form of **bonded exploitation**. The demand to abolish begar was one of the strongest grievances of the Awadh peasant movement."},{"id":"ch2-s2-oudh-kisan-sabha","title":"The Peasant Movement Organises","type":"text","text":"In **June 1920**, **Jawaharlal Nehru** visited the villages of Awadh. What he saw shocked him — the depth of poverty, the cruelty of landlords, the desperation of peasants.\n\nBy **October 1920**, the **Oudh Kisan Sabha** was set up — by Nehru, Baba Ramchandra, and a few others. Within a month, it had over **300 branches**. The peasant movement was organised and ready — even BEFORE Non-Cooperation formally began in January 1921.\n\nBut when Non-Cooperation started, something dangerous happened..."},{"id":"ch2-s2-peasants-exceed","title":"When the Movement Went Beyond Gandhi","type":"text","text":"When the movement began, the peasants went **far beyond** what Congress or Gandhi had intended:\n\n**Houses of talukdars and merchants were attacked**\n**Bazaars were looted**\n**Grain hoards were taken over**\n\nLocal leaders told peasants that **Gandhi had declared**: no more taxes, land will be redistributed to the poor. The name of the **Mahatma** was being used to justify actions **Gandhi never authorised**.\n\nThis is a pattern you''ll see again and again: Gandhi says one thing, but by the time his message reaches a village 500 miles away, it has been **reinterpreted** to match local grievances. The peasants weren''t disobeying Gandhi — they genuinely believed this was what he wanted.","highlight":"**The fracture:** Peasants used Gandhi''s name to justify looting, attacking landlords, and seizing grain — things Gandhi never authorised. His message was reinterpreted to match local grievances."},{"id":"ch2-s2-source-b","type":"source","text":"**Source B — Jawaharlal Nehru on the peasant uprising at Rae Bareli:**\n\n\"They behaved as brave men, calm and unruffled in the face of danger... Many received lathi blows, which drew blood. Many were seriously hurt, but no one ran away... For a moment my blood was up, non-violence was almost forgotten — but for a moment only.\"\n\n**What this source tells us:** Even Nehru — one of Gandhi''s closest allies — admits that watching police brutality against unarmed peasants almost made HIM forget non-violence. If a committed Gandhian nearly lost control, imagine what ordinary peasants felt. This source is CBSE gold — it shows the tension between non-violence as a principle and human anger as a reality."},{"id":"ch2-s2-gudem","title":"Gudem Hills Tribals — A Different Kind of Swaraj","type":"text","text":"**Gudem Hills, Andhra Pradesh.** The colonial government had done two things that destroyed tribal life:\n\n**1. Closed the forests** — no grazing, no firewood, no collecting forest produce. For tribals, the forest wasn''t just land — it was **livelihood, culture, home**.\n**2. Demanded begar** — forced tribals to build roads through their own hills for free.\n\nTheir leader was **Alluri Sitaram Raju** — a charismatic figure who claimed he had **special powers**: the ability to make correct astrological predictions, the ability to heal people, and — his followers believed — he could **survive bullets**.\n\nThe hill people proclaimed him an **incarnation of God**.","highlight":"**Gudem Hills tribals:** Colonial government closed forests + demanded begar. Leader: Alluri Sitaram Raju (claimed special powers, followers believed he could survive bullets). Tribal swaraj = forest rights."},{"id":"ch2-s2-raju-paradox","title":"Raju''s Paradox — Gandhi''s Name, Not Gandhi''s Method","type":"text","text":"Here''s what makes Alluri Sitaram Raju fascinating — and what CBSE loves to test:\n\nHe **wore khadi**. He **invoked Gandhi''s name**. He said he supported **Non-Cooperation**.\n\nBut he used **guerrilla warfare**. He **attacked police stations**. He **seized weapons**. He **killed British officials**.\n\nRaju believed that India could only be freed through **force**, not non-violence. He was Gandhi''s follower in spirit but his **opposite** in method.\n\nHe was **captured and executed in 1924**. He became a **folk hero**.\n\nThis is the contradiction at the heart of the movement: people across India adopted Gandhi''s NAME and CAUSE — but not always his METHOD.","highlight":"**Raju''s paradox:** Wore khadi + invoked Gandhi + supported Non-Cooperation — BUT used guerrilla warfare and violence. Captured and executed 1924. Shows how Gandhi''s message was reinterpreted across India.","inlineQuiz":{"question":"What was contradictory about Alluri Sitaram Raju''s role in the movement?","options":["He supported the British but claimed to be a nationalist","He was a tribal leader who opposed forest rights","He invoked Gandhi and wore khadi but used violent guerrilla methods","He supported Non-Cooperation but refused to boycott foreign goods"],"correctIndex":2,"explanation":"Raju claimed to be inspired by Gandhi, wore khadi, and supported Non-Cooperation — but he used violent guerrilla methods, attacking police stations and killing British officials. This shows how the movement was reinterpreted differently across India."}},{"id":"ch2-s2-picket-vocab","type":"vocabulary","text":"Picket — A form of demonstration or protest in which people **stand or march outside a shop, factory, or office** to discourage others from entering. During the Non-Cooperation Movement, volunteers picketed shops selling foreign cloth and liquor — standing at the entrance and persuading (sometimes pressuring) customers not to go in. Picketing was a key tactic of the boycott."}]},{"id":"ch2-s2-plantations","title":"Swaraj in the Plantations","narrativeCards":[{"id":"ch2-s2-plantation-intro","title":"Assam Plantation Workers — The Simplest Dream","type":"text","text":"Of all the groups who joined the movement, **plantation workers in Assam** had the simplest definition of swaraj.\n\nFor them, freedom meant one thing: **the right to move**.\n\nUnder the **Inland Emigration Act of 1859**, plantation workers were **not allowed to leave the tea gardens** without permission. Read that again. They couldn''t leave. They were not slaves in name — but they were **trapped** in practice. They couldn''t visit their villages, couldn''t seek better work, couldn''t go home.\n\nFor 62 years, this law had kept them prisoner. Then they heard about Gandhi and Non-Cooperation.","highlight":"**Assam plantation workers:** Trapped by the Inland Emigration Act of 1859 — couldn''t leave tea gardens without permission. Their swaraj = the simple freedom to go home."},{"id":"ch2-s2-plantation-action","title":"What They Did — And What Happened","type":"text","text":"When news of Non-Cooperation reached the plantations, **thousands of workers defied the authorities**. They left the tea gardens and headed home. They believed **\"Gandhi Raj\"** was coming — a time when everyone would have land, when all suffering would end, when they would be free.\n\nBut they **never reached their destinations**.\n\nStranded on the way by a **railway and steamer strike** (part of the very movement they were joining), they were **caught by the police and brutally beaten**.\n\nTheir vision of swaraj was the simplest of all — just the **freedom to go home**. And even that was denied.","highlight":"**What happened:** Workers left plantations believing \"Gandhi Raj\" was coming. Stranded by railway strike. Caught by police. Beaten. Their swaraj — just the freedom to go home — was denied."},{"id":"ch2-s2-pattern","title":"Recap — Who Joined, and Why","type":"table","text":"Step back and see the whole movement at a glance. Each social group joined the Non-Cooperation Movement for its **own reasons** and gave swaraj its **own meaning**:","table":{"headers":["Group","What they did","What swaraj meant","What went wrong"],"rows":[["**Middle class (towns)**","Boycotted schools, courts and foreign goods","Constitutions and parliaments","Khadi was costly; no Indian alternatives ready"],["**Awadh peasants**","Attacked landlords, seized grain","No rent, no begar, land","Went beyond Gandhi''s non-violent programme"],["**Gudem tribals**","Guerrilla warfare against the British","Forest rights, end of begar","Used violence, not non-violence"],["**Assam plantation workers**","Left the tea gardens, headed home","Freedom to move","Stranded by a strike, beaten by police"]]},"highlight":"**The pattern:** Every group joined for its own reasons and read Gandhi in its own way. The movement was ONE struggle in name — but several different struggles in practice. (Frequently asked 5-marker: \"Why did different social groups join the Non-Cooperation Movement?\")","inlineQuiz":{"question":"What did \"swaraj\" mean to plantation workers in Assam?","options":["The right to vote in elections","Higher wages and better working conditions","The right to own tea gardens","The freedom to leave the plantations and go home"],"correctIndex":3,"explanation":"For Assam plantation workers, swaraj meant the most basic freedom — the right to move freely and go home. They were trapped under the Inland Emigration Act of 1859, which prevented them from leaving tea gardens without permission."}}]},{"id":"ch2-s2-chauri-chaura","title":"Chauri Chaura — The Movement Dies","narrativeCards":[{"id":"ch2-s2-escalation","title":"A Movement Growing Out of Control","type":"text","text":"Look at what has happened across India by early 1922:\n\n**In the towns** — people exceeded the boycott, burning cloth and picketing aggressively\n**In Awadh** — peasants attacked landlords and looted grain in Gandhi''s name\n**In Gudem Hills** — tribals launched guerrilla warfare\n**In Assam** — workers abandoned plantations en masse\n\nThe movement was **growing** — but it was growing **out of control**. Violence was creeping in from every direction. Each group was pushing further than Congress intended. Gandhi''s non-violent national movement was fracturing into a dozen local revolts, each with its own logic, its own anger.\n\nAnd then came **Chauri Chaura**."},{"id":"ch2-s2-chauri-chaura-event","title":"4 February 1922 — The Day That Ended Everything","type":"text","text":"**4 February 1922. Chauri Chaura, a small town in Gorakhpur district, Uttar Pradesh.**\n\nA peaceful demonstration was marching through the town. Some accounts say the police provoked the crowd. Whatever the trigger, the situation escalated rapidly.\n\nThe crowd turned on the police. They set fire to the **police station**.\n\n**22 policemen were killed.**\n\nIn one afternoon, in one small town, the entire moral foundation of Gandhi''s movement was shattered.","highlight":"**Chauri Chaura (4 Feb 1922):** Peaceful demonstration turns violent. Crowd sets fire to police station. 22 policemen killed. This single incident ends the entire Non-Cooperation Movement."},{"id":"ch2-s2-gandhi-decision","title":"Gandhi''s Devastating Decision","type":"text","text":"When Gandhi heard the news, he was **devastated**. He didn''t hesitate. He called off the **ENTIRE Non-Cooperation Movement**.\n\nThe whole country was **stunned**. Other Congress leaders were **furious**:\n\n\"The movement is at its **peak**!\"\n\"The British are **rattled** for the first time!\"\n\"We''re **winning** — and you''re pulling the plug?\"\n\nJawaharlal Nehru later wrote that he felt **anguish and bewilderment** — how could one incident in one town justify ending a movement that had mobilised millions?\n\nBut Gandhi was firm. Absolutely, completely firm."},{"id":"ch2-s2-why-called-off","title":"WHY Did Gandhi Call Off the Movement?","type":"text","text":"This is the **most important WHY** in the chapter — and CBSE tests it repeatedly.\n\nGandhi''s reasoning was simple and unshakeable:\n\n**\"A movement that kills is no different from the empire it fights.\"**\n\nFor Gandhi, non-violence was **not a tactic**. It was not a strategy you use when it''s convenient and drop when it''s not. Non-violence was the **soul** of the struggle. If the movement became violent, it would **corrupt** the people fighting it — and the freedom they won would be built on blood, not truth.\n\nHe believed that **the means shape the ends**. If you win through violence, you create a violent nation. If you win through truth, you create a truthful one.\n\n**One incident. 22 deaths. The entire movement — cancelled.**\n\nThat''s how seriously Gandhi took non-violence.","highlight":"**WHY Gandhi called off the movement:** Non-violence was not a tactic — it was the SOUL of the struggle. A movement that kills is no different from the empire it fights. The means shape the ends. This is the most tested explanation in CBSE exams on this chapter."},{"id":"ch2-s2-closer","title":"The Promise vs. The Reality","type":"text","text":"Remember Gandhi''s promise from *Hind Swaraj*? **\"Refuse to cooperate, and the British will leave within a year.\"**\n\nLet''s measure reality against that promise:\n\n**The promise:** Swaraj in one year.\n**The reality:** In February 1922, **Gandhi himself** called off the movement — because his own people couldn''t stay non-violent.\n\nThe British were still here. The movement was in pieces. The unity between Hindus and Muslims — so carefully built — would begin to crack. Gandhi was arrested in March 1922 and sentenced to **six years in prison**.\n\nBut was it all for nothing? The answer is no — and the significance card tells you why.","highlight":"**Promise vs. Reality:** Gandhi promised swaraj in one year. Instead, HE ended the movement in February 1922 because Indians couldn''t stay non-violent. The British stayed. Gandhi went to prison. But the movement wasn''t wasted."},{"id":"ch2-s2-significance","title":"The Significance of Non-Cooperation (Despite Its Failure)","type":"exam-prep","text":"Q: What was the significance of the Non-Cooperation Movement even though it was withdrawn?\nMarks: 5 Marks\nA: It was the **first truly national movement** — not limited to one region or one city, but spread across all of India, from cities to villages to plantations.\nA: The British economy was directly hit — **foreign cloth imports halved** from Rs 102 crore to Rs 57 crore.\nA: The **working class was awakened** — peasants, tribals, and plantation workers participated in a national movement for the first time in Indian history.\nA: **Hindu-Muslim unity** was achieved, even if briefly — the Khilafat-Non-Cooperation alliance was unprecedented.\nA: It **inspired the next generation** — leaders like Bhagat Singh, Subhas Chandra Bose, and Jawaharlal Nehru would build on the political consciousness it created. The movement died. But the idea of swaraj survived.\nTip: For 3-mark version: pick any 3 points. For 5-mark: cover all 5. Each point = 1 mark. Always end with \"The movement failed but its legacy endured.\""},{"id":"ch2-s2-timeline","title":"Section 2 Timeline","type":"timeline-ref","text":"January 1921 — **Non-Cooperation-Khilafat Movement begins** — boycotts in cities, students leave schools\n1921 — **Awadh peasant movement** — Baba Ramchandra, Oudh Kisan Sabha, attacks on talukdars\n1921-22 — **Gudem Hills rebellion** — Alluri Sitaram Raju leads guerrilla warfare against British\n1921 — **Assam plantation workers** leave tea gardens, believe \"Gandhi Raj\" is coming\n4 February 1922 — **Chauri Chaura incident** — crowd burns police station, 22 policemen killed\nFebruary 1922 — **Gandhi calls off Non-Cooperation Movement**\nMarch 1922 — **Gandhi arrested**, sentenced to 6 years in prison","highlight":"**Key exam dates:** January 1921 (movement begins), 4 February 1922 (Chauri Chaura), February 1922 (movement called off). The Chauri Chaura date appears in almost every CBSE paper."},{"id":"ch2-s2-final-quiz","title":"Section Check","type":"text","text":"You''ve now covered the most exam-heavy section of Chapter 2. The key things to remember:\n\n**1.** Different groups joined for different reasons — know each group''s grievance and their definition of swaraj\n**2.** The movement grew out of control — peasants, tribals, and workers all went beyond what Gandhi intended\n**3.** Chauri Chaura (4 Feb 1922) — 22 policemen killed — Gandhi calls off the entire movement\n**4.** WHY he called it off — non-violence was not a tactic but the soul of the struggle\n**5.** Despite failure, the movement''s significance was enormous — first national movement, economy hit, working class awakened, Hindu-Muslim unity","inlineQuiz":{"question":"Gandhi called off the Non-Cooperation Movement after Chauri Chaura because:","options":["The British promised to grant swaraj if Gandhi stopped","Muslim leaders withdrew their support from the movement","The movement had already achieved all its goals","He believed a violent movement would corrupt the freedom it won"],"correctIndex":3,"explanation":"Gandhi called off the movement because non-violence was the SOUL of the struggle, not just a tactic. He believed that if the movement became violent, it would corrupt the people and the freedom they eventually won. The means shape the ends."}}]}],"keyPoints":["Non-Cooperation was NOT one movement — five different groups joined for five different reasons","Middle class in towns: boycotted schools, courts, titles, foreign cloth — but khadi was expensive, alternatives slow","Awadh peasants (led by Baba Ramchandra): fought talukdars, demanded end of begar and high rents","Gudem Hills tribals (led by Alluri Sitaram Raju): used guerrilla warfare for forest rights — executed 1924","Assam plantation workers: left plantations believing \"Gandhi Raj\" was coming — stranded, beaten by police","Chauri Chaura (February 1922): police station burnt, 22 policemen killed — Gandhi called off entire movement","Gandhi withdrew because non-violence was a moral principle, not just a strategy"],"figureIds":["ch2-fig-5"],"sourceIds":["ch2-source-b"],"vocabularyIds":["ch2-vocab-boycott","ch2-vocab-begar","ch2-vocab-picket","ch2-vocab-swaraj"]},{"id":"s3","number":3,"title":"Towards Civil Disobedience","color":"hist-orange","icon":"🧂","subsections":[{"id":"ch2-s3-years-between","title":"The Years Between — 1922-1929","narrativeCards":[{"id":"ch2-s3-opener","title":"Eight Lost Years?","type":"text","text":"Non-Cooperation is over. Gandhi has withdrawn. The Congress is **divided**. Some leaders want to enter councils and fight from within. Others want another mass movement. And a new generation — **Bhagat Singh, Subhas Chandra Bose** — wants revolution, not satyagraha.\n\nWhat happens in the **eight years between 1922 and 1930**? On the surface, not much. But underneath, the pressure is building — economic collapse, political humiliation, and a new generation''s impatience would combine to create the most iconic moment in India''s freedom struggle."},{"id":"ch2-s3-swaraj-party","title":"The Congress Splits — Council Entry vs. Mass Movement","type":"text","text":"With Non-Cooperation called off, Congress leaders disagreed on what to do next.\n\n**One side:** **C.R. Das** and **Motilal Nehru** (Jawaharlal''s father) formed the **Swaraj Party** in 1923. Their argument: enter the British-created provincial councils, win elections, and **obstruct the government from within**. Don''t boycott — infiltrate.\n\n**Other side:** Some Congressmen — called **\"No-Changers\"** — wanted to stay out of the councils entirely and continue building grassroots movements in villages (spinning khadi, promoting communal harmony).\n\nMeanwhile, younger leaders like **Jawaharlal Nehru** and **Subhas Chandra Bose** were frustrated with both sides. They wanted **full independence** — not dominion status, not council debates. They wanted mass agitation.","highlight":"**Congress after NCM:** Split into (1) Swaraj Party (C.R. Das, Motilal Nehru) — enter councils, obstruct from within (2) No-Changers — stay out, build grassroots (3) Young radicals (Nehru, Bose) — demand full independence."},{"id":"ch2-s3-bhagat-singh","title":"The Revolutionaries — Bhagat Singh and HSRA","type":"infobox","text":"**Hindustan Socialist Republican Army (HSRA)**, founded 1928. Leaders: **Bhagat Singh**, **Jatin Das**, **Ajoy Ghosh**, **Chandrashekhar Azad**. They targeted symbols of British power — not random violence.\n\nIn **April 1929**, Bhagat Singh and **Batukeshwar Dutta** threw a bomb in the **Central Legislative Assembly** in Delhi. The bomb was designed NOT to kill — it was meant to **\"make the deaf hear.\"** They could have escaped. Instead, they stayed and **shouted \"Inquilab Zindabad!\"** (Long Live Revolution) and let themselves be arrested.\n\nDuring his trial, Bhagat Singh said he did not wish to glorify **\"the cult of the bomb and pistol\"** — he wanted a **revolution in society**. He read voraciously in prison — Marx, Lenin, Trotsky.\n\n**Jatin Das** died after a **63-day hunger strike** in prison, demanding political prisoners be treated with dignity.\n\nBhagat Singh was **23 years old** when he was executed on **23 March 1931**. He became the most beloved martyr of the freedom struggle.","highlight":"**Bhagat Singh (HSRA):** Threw bomb in Assembly to \"make the deaf hear\" — not to kill. Said he wanted revolution in society, not glorification of violence. Executed at 23. \"Inquilab Zindabad!\""},{"id":"ch2-s3-economic-crisis","title":"The Great Depression Hits India","type":"text","text":"While politicians debated, the economy was **collapsing**.\n\nThe **worldwide Great Depression** began in 1929, but agricultural prices in India had been falling since **1926**. After 1930, they crashed completely. The impact was devastating:\n\n**1.** Peasants couldn''t sell their crops at decent prices\n**2.** But they still had to pay the **same revenue** to the government — fixed rates, no reduction\n**3.** Many fell into crushing **debt**\n**4.** Rural India was desperate — again\n\nThis was the **same pattern** as before Non-Cooperation: economic suffering creating mass anger. The countryside was ready for a new movement. All it needed was a spark.","highlight":"**Great Depression in India:** Agricultural prices crash (from 1926, collapse after 1930). Peasants can''t sell crops but must pay fixed revenue. Rural India desperate — ready for a new movement."},{"id":"ch2-s3-simon","title":"Simon Commission — \"Go Back Simon!\"","type":"text","text":"In **1928**, the British government sent the **Simon Commission** to India — to review the country''s constitutional future and recommend reforms.\n\nThe problem? **Not a single Indian member.** All seven members were British. Indians were being told: \"We''ll decide YOUR future — without asking you.\"\n\nThe response was **immediate and united**. For once, even the **Congress and the Muslim League** agreed — they both boycotted the Commission. Across India, the Commission was met with black flags and the slogan **\"Go Back Simon!\"**\n\nDuring a protest in Lahore, **Lala Lajpat Rai** — the veteran leader known as the \"Lion of Punjab\" — was **brutally beaten** by police. He died shortly after from his injuries. His death inflamed the nation.","imageId":"ch2-fig-6","highlight":"**Simon Commission (1928):** All-British, no Indian members. Boycotted by Congress AND Muslim League. \"Go Back Simon!\" Lala Lajpat Rai beaten at Lahore protest, later dies.","inlineQuiz":{"question":"Why was the Simon Commission opposed by Indians across political lines?","options":["It had no Indian members — Indians had no say in their own future","It recommended the partition of India","It proposed abolishing the Indian National Congress","It increased taxes on Indian goods"],"correctIndex":0,"explanation":"The Simon Commission was an all-British body with no Indian representation. Indians across the political spectrum — Congress, Muslim League, and others — united in opposing it because it denied Indians any voice in deciding their own constitutional future."}},{"id":"ch2-s3-lahore-congress","title":"Lahore Congress — Purna Swaraj","type":"text","text":"**December 1929.** The Indian National Congress meets in Lahore under the presidency of a young, 40-year-old **Jawaharlal Nehru**.\n\nThe Congress makes a **historic declaration**: it formally demands **Purna Swaraj** — **complete independence**. Not dominion status (self-rule within the British Empire). Not reforms. Not negotiations. **Full, unconditional independence.**\n\n**26 January 1930** is declared **Independence Day**. Across India, people take the Independence Day Pledge — affirming their right to freedom. But the celebrations attract surprisingly little attention from the British.\n\nGandhi knows: a declaration is just words. He needs something **dramatic** — an act of defiance so powerful that the whole world will notice. He needs the perfect symbol...","highlight":"**Lahore Congress (December 1929):** Under Nehru''s presidency, Congress demands Purna Swaraj (complete independence). 26 January 1930 = Independence Day. But Gandhi knows he needs something dramatic to make it real."},{"id":"ch2-s3-purna-swaraj-vocab","type":"vocabulary","text":"Purna Swaraj — **Purna** (complete/full) + **Swaraj** (self-rule) = **complete independence**. This was a critical escalation. Until 1929, many Congress leaders were willing to accept \"dominion status\" — self-government within the British Empire (like Canada or Australia). At the Lahore Congress (December 1929), this was rejected. India would accept nothing less than FULL independence. This is why 26 January was chosen as Republic Day in 1950 — it was already Independence Day since 1930."}]},{"id":"ch2-s3-salt-march","title":"The Salt March and Civil Disobedience","narrativeCards":[{"id":"ch2-s3-why-salt","title":"Why Salt? The Perfect Symbol","type":"text","text":"Gandhi found in salt the **perfect symbol**. Think about it:\n\n**1.** What do the rich AND the poor both need every single day? **Salt.**\n**2.** Hindu and Muslim, Brahmin and Dalit, man and woman — **everyone eats salt.**\n**3.** The British had a **monopoly** on salt production — it was illegal for Indians to make their own.\n**4.** And they **taxed** it — making a basic necessity more expensive for the poorest.\n\nBy choosing salt, Gandhi turned **every kitchen in India into a site of resistance**. The salt tax affected everyone. It was simple enough for any villager to understand. And defying it was easy — just pick up natural salt from the shore.\n\nNo other issue could have united India like salt did.","highlight":"**WHY salt:** (1) Everyone needs it — rich and poor, Hindu and Muslim (2) British monopoly made it illegal to produce (3) Salt tax hit the poorest hardest (4) Simple to defy — just pick up natural salt. Salt turned every kitchen into a site of resistance."},{"id":"ch2-s3-gandhi-letter","title":"Gandhi''s Letter to Irwin — The Ultimatum","type":"text","text":"On **31 January 1930**, Gandhi wrote a remarkable letter to **Viceroy Lord Irwin**. It contained **11 demands** — some specific (abolish salt tax, reduce military spending, release political prisoners), some general (protect Indian textile industry, reform the exchange rate).\n\nThe letter was carefully crafted. Some demands were for the industrialists, some for the peasants, some for everyone. Gandhi was trying to build the **widest possible alliance**.\n\nBut the letter also carried an **ultimatum**: if the demands were not met by **11 March**, the Congress would launch **civil disobedience**.\n\nIrwin **ignored the letter**. Gandhi had his answer.","highlight":"**Gandhi''s letter to Irwin (31 Jan 1930):** 11 demands (salt tax abolition, reduced military spending, release prisoners). Ultimatum: meet demands by 11 March or face civil disobedience. Irwin ignores it."},{"id":"ch2-s3-the-march","title":"The March — Sabarmati to Dandi","type":"figure","text":"On **12 March 1930**, the most famous march in India''s history began. The key facts to remember:\n\n**1. Start:** Gandhi set out from his **Sabarmati Ashram** in Ahmedabad.\n**2. Volunteers:** He began with just **78 trusted volunteers**.\n**3. Destination:** **Dandi**, a small coastal town in Gujarat.\n**4. Distance:** about **240 miles** (roughly 390 km), walking around **10 miles a day**.\n**5. Duration:** the march took **24 days**.\n\nAt every village along the way, Gandhi stopped — explaining what swaraj meant, urging people to defy the British peacefully, and asking them to give up alcohol and untouchability. **Thousands joined** as the march went on, and journalists from around the world followed it. The whole world was watching.","imageId":"ch2-fig-7","highlight":"**The Dandi March:** 12 March 1930, Sabarmati to Dandi. 78 volunteers, 240 miles, 24 days. Gandhi stopped at every village. Thousands joined. The world watched."},{"id":"ch2-s3-salt-breaking","title":"6 April 1930 — The Law is Broken","type":"text","text":"**6 April 1930.** Gandhi reaches Dandi. He walks to the shore. He bends down. He picks up a **handful of natural salt**.\n\nWith that simple act, he has **broken the law**.\n\nThe **Civil Disobedience Movement** has begun.\n\nAcross the country, people follow Gandhi''s example. In **Tamil Nadu**, **C. Rajagopalachari** leads a march from Tiruchirappalli to Vedaranyam. In **Malabar**, **K. Kelappan** marches to Payyanur. Thousands of Indians begin **manufacturing salt**, **picking up natural salt**, and publicly defying the British monopoly.","highlight":"**6 April 1930:** Gandhi picks up salt at Dandi — breaks the law. CDM begins. Salt marches across India: Rajagopalachari in Tamil Nadu, Kelappan in Malabar."},{"id":"ch2-s3-cdm-vs-ncm","title":"How Was CDM Different from Non-Cooperation?","type":"text","text":"This is a crucial distinction for exams:\n\n**Non-Cooperation (1920-22):** People **refused to cooperate** — they boycotted schools, courts, councils, and foreign goods. They withdrew participation. It was **passive** — a refusal.\n\n**Civil Disobedience (1930):** People **actively broke the law** — manufacturing salt illegally, refusing to pay revenue and taxes, violating forest laws by entering reserved forests, boycotting foreign cloth (not just refusing to buy — burning it publicly). It was **active** — a defiance.\n\nThe shift was from saying **\"We won''t participate\"** to saying **\"We will disobey.\"** This was far more threatening to British authority.","highlight":"**NCM vs CDM:** Non-Cooperation = passive refusal (boycott). Civil Disobedience = active law-breaking (manufacturing salt, refusing revenue, violating forest laws). CDM was a direct CHALLENGE to British authority.","inlineQuiz":{"question":"What was the key difference between Non-Cooperation and Civil Disobedience?","options":["NCM was led by Gandhi but CDM was led by Nehru","NCM involved boycotting institutions while CDM involved actively breaking laws","NCM was non-violent but CDM allowed violence","NCM included Muslims but CDM did not"],"correctIndex":1,"explanation":"Non-Cooperation meant withdrawing participation (boycotting courts, schools, councils). Civil Disobedience meant actively defying and breaking laws (manufacturing salt, refusing to pay taxes, violating forest laws). CDM was a much more direct challenge to British authority."}},{"id":"ch2-s3-spread-repression","title":"The Movement Spreads — And the Crackdown Begins","type":"figure","text":"The movement spread rapidly:\n\n- **Peasants** refused to pay revenue and violated forest laws\n- **Tribal people** entered reserved forests to collect wood and graze cattle\n- **In towns**, foreign cloth was boycotted and liquor shops were picketed\n- **Factory workers** went on strike in some regions\n\nThe British responded with **brutal repression**. **Abdul Ghaffar Khan** — the \"Frontier Gandhi\" who had organised the **Khudai Khidmatgars** (Servants of God) among Pathans in the North-West Frontier — was arrested in Peshawar. Angry crowds faced **armoured cars**.\n\n**Gandhi himself was arrested** in May 1930. In Sholapur, workers responded by attacking police posts, municipal buildings, courts, and railway stations. About **100,000 people** were arrested across India. Peaceful satyagrahis were beaten, women and children attacked.","imageId":"ch2-fig-8","highlight":"**CDM repression:** Abdul Ghaffar Khan arrested (Peshawar). Gandhi arrested (May 1930). ~100,000 people arrested. Brutal force against peaceful satyagrahis."},{"id":"ch2-s3-gandhi-irwin","title":"Gandhi-Irwin Pact and the Round Table Conference","type":"text","text":"**March 1931:** After months of repression, Gandhi and Viceroy Irwin negotiate the **Gandhi-Irwin Pact**. Gandhi agrees to:\n- Call off Civil Disobedience\n- Attend the **Round Table Conference** in London to discuss India''s political future\n\nIn return, the British agree to:\n- Release political prisoners (those not convicted of violence)\n- Allow Indians to make salt for personal use along the coast\n\n**December 1931:** Gandhi goes to London for the **Second Round Table Conference**. The negotiations go nowhere. The British play divide-and-rule — giving separate platforms to Muslims, Dalits, and princely states. Congress is treated as just one voice among many.\n\nBack in India, **Ghaffar Khan and Nehru are in jail**. The Congress is declared **illegal**. Gandhi returns and **relaunches CDM** — but it''s **weaker** this time. Without fresh energy, the movement gradually **fizzles out by 1934**.","highlight":"**Gandhi-Irwin Pact (March 1931):** CDM called off, Gandhi attends Round Table Conference. Negotiations fail. CDM relaunched but weaker. Fizzles out by 1934."},{"id":"ch2-s3-source-c","title":"The Independence Day Pledge","type":"source","text":"The Independence Day Pledge (26 January 1930): \"We believe that it is the **inalienable right of the Indian people**, as of any other people, to have freedom and to enjoy the fruits of their toil and have the necessities of life, so that they may have full opportunities of growth. We believe also that if any government deprives a people of these rights and oppresses them, the people have a further right to alter it or abolish it. The British government in India has not only deprived the Indian people of their freedom but has based itself on the exploitation of the masses... **India must sever the British connection and attain Purna Swaraj or Complete Independence.**\""}]},{"id":"ch2-s3-participants","title":"How Participants Saw the Movement","narrativeCards":[{"id":"ch2-s3-participants-intro","title":"Same Movement, Different Dreams — Again","type":"text","text":"Just like Non-Cooperation, Civil Disobedience drew **different groups for different reasons**. And just like before, the \"unity\" was **conditional** — each group supported the movement only as long as it served their interests.\n\nCBSE **loves** this topic. The question \"How did different social groups participate in the Civil Disobedience Movement?\" appears regularly in board exams. You need to know each group separately: what they wanted, what they did, and why some were disappointed."},{"id":"ch2-s3-rich-peasants","title":"Rich Peasants — The Patidars and Jats","type":"text","text":"**Who:** The **Patidars of Gujarat** and **Jats of Uttar Pradesh** — prosperous landholding farmers who grew commercial crops.\n\n**Why they joined:** The Depression had destroyed them. Commercial crops like cotton and tobacco were **worthless** — prices had crashed. But the government demanded the **same revenue**. They couldn''t pay.\n\n**What they did:** Enthusiastically joined CDM. Refused to pay revenue. Participated in marches and boycotts.\n\n**What went wrong:** When Gandhi called off the movement in 1931 (Gandhi-Irwin Pact) **WITHOUT winning any reduction in revenue**, the Patidars were **deeply disappointed**. They felt betrayed. Many **refused to rejoin** when CDM was relaunched in 1932.","highlight":"**Rich peasants (Patidars/Jats):** Joined because Depression crashed crop prices but revenue stayed the same. Disappointed when CDM called off WITHOUT revenue reduction. Many refused to rejoin in 1932."},{"id":"ch2-s3-poor-peasants","title":"Poor Peasants — A Deeper Problem","type":"text","text":"**Who:** Small tenants and sharecroppers — the poorest of the rural poor.\n\n**What they wanted:** They didn''t just want lower **government revenue** — they wanted relief from **landlord rent**. For them, the oppressor wasn''t just the British; it was also the **Indian landlord** who squeezed them dry.\n\n**The problem:** Congress **would not support \"no rent\" campaigns**. Why? Because Congress needed the support of **rich peasants and zamindars** too. Supporting the poor against landlords would alienate the rich.\n\n**What happened:** Frustrated, many poor peasants turned to **Socialist and Communist movements** instead. The Congress lost their trust.\n\nThis was a fundamental contradiction: how do you unite landlords and tenants in the same movement?","highlight":"**Poor peasants:** Wanted rent relief from LANDLORDS, not just lower government revenue. Congress refused \"no rent\" campaigns (feared alienating rich peasants). Poor peasants turned to Socialists/Communists."},{"id":"ch2-s3-business","title":"The Business Class — Conditional Support","type":"text","text":"**Who:** Indian industrialists like **G.D. Birla**, **Purushottamdas Thakurdas**, and business organisations like **FICCI** (Federation of Indian Chambers of Commerce and Industry).\n\n**Why they joined:** They wanted **protection from foreign imports** (which undercut their products) and a **favourable rupee-sterling exchange rate**. They saw the movement as a way to pressure the British into pro-Indian economic policies.\n\n**What they did:** Funded the Congress. Refused to buy or sell imported goods. Publicly supported the boycott.\n\n**What changed:** After the Round Table Conference **failed**, businessmen got nervous. Prolonged disruption was **bad for business**. They began pressing Gandhi to **negotiate** rather than agitate. Their support became increasingly **cautious**.","highlight":"**Business class (Birla/FICCI):** Wanted protection from foreign imports + favourable exchange rates. Funded CDM. But after Round Table failure, feared prolonged disruption. Support turned cautious."},{"id":"ch2-s3-workers","title":"Workers — The Uneasy Relationship","type":"text","text":"**Who:** Railway workers, dock workers, mine workers, factory workers.\n\n**What they wanted:** Fair wages, better working conditions, job security — basic labour rights.\n\n**What they did:** Some workers participated — boycotting foreign goods, joining rallies, going on strike in Nagpur and Bombay.\n\n**The problem:** Congress was **reluctant to include worker demands** (higher wages, shorter hours, union recognition) in its programme. Why? Because that would alienate **industrialists like Birla** who were funding the movement.\n\nSo workers faced the same dilemma as poor peasants: the Congress movement claimed to represent everyone, but its leadership was unwilling to challenge the economic interests of its wealthy supporters.","highlight":"**Workers:** Wanted fair wages and better conditions. Some joined CDM. But Congress wouldn''t include worker demands — feared alienating industrialist funders. Relationship remained uneasy."},{"id":"ch2-s3-women","title":"Women — Massive Participation, Limited Power","type":"figure","text":"**Thousands of women** participated in the Civil Disobedience Movement — a **revolutionary change** in Indian public life. Women:\n\n- Joined **salt marches** and picketing of liquor and foreign cloth shops\n- **Manufactured salt** in defiance of the law\n- **Went to jail** — for many, the first time they had ever left their homes for a public cause\n\nBut here''s the limitation: **Gandhi saw women''s role as largely symbolic** — representing the moral strength of the nation. He called on women to be \"good mothers and good wives\" who sacrificed for the cause. Congress was **reluctant to give women real positions of authority** in the organisation.\n\nWomen''s participation was **unprecedented and transformative** — but their power within the movement remained limited.","imageId":"ch2-fig-9","highlight":"**Women:** Massive participation — salt marches, picketing, manufacturing salt, going to jail. BUT Gandhi saw their role as symbolic. Congress reluctant to give women leadership positions. Participation was revolutionary; power was not.","inlineQuiz":{"question":"What was the limitation of women''s participation in the Civil Disobedience Movement?","options":["Very few women actually participated in the movement","Women were only allowed to participate in cities, not villages","Women participated massively but were denied real positions of authority","Women were banned from participating by the Congress"],"correctIndex":2,"explanation":"Thousands of women participated in CDM — joining marches, manufacturing salt, going to jail. But Gandhi saw their role as primarily symbolic, and Congress was reluctant to give women real leadership positions. Their participation was revolutionary, but their power within the movement was limited."}}]},{"id":"ch2-s3-limits","title":"The Limits of Civil Disobedience","narrativeCards":[{"id":"ch2-s3-limits-intro","title":"Whose Swaraj?","type":"text","text":"Not all social groups were moved by the abstract concept of swaraj. Two communities, in particular, asked a devastating question: **whose swaraj?**\n\nIf the British left, who would rule India? Would it be a nation where **Dalits** had dignity and opportunity? Would **Muslims** be safe in a Hindu-majority country?\n\nThese weren''t abstract questions. They were life-and-death concerns. And the answers — or the lack of answers — would shape India''s future all the way to **1947 and Partition**."},{"id":"ch2-s3-dalits","title":"Dalits — \"We Want Our Own Voice\"","type":"text","text":"**Dalits** — who had begun calling themselves the **\"Depressed Classes\"** — faced a unique situation. Their oppressor wasn''t just the British. It was **upper-caste Hindu society** that enforced untouchability, denied them access to temples, wells, schools, and any dignity.\n\nFor decades, Congress had **ignored Dalit concerns** — afraid of offending its upper-caste Hindu base. Swaraj under Congress, Dalits feared, would simply replace British rule with **upper-caste Hindu rule**.\n\nDalits had specific demands:\n- **Reserved seats** in educational institutions\n- **Separate electorates** — the right to elect their own representatives (not candidates chosen by upper-caste voters)\n- An end to **untouchability** in practice, not just in speeches","highlight":"**Dalits and CDM:** Their oppressor was upper-caste Hindu society, not just the British. Congress had long ignored Dalit concerns. Dalits feared swaraj = upper-caste Hindu rule. Demanded reserved seats + separate electorates."},{"id":"ch2-s3-ambedkar","title":"Ambedkar vs. Gandhi — The Great Debate","type":"text","text":"**Dr. B.R. Ambedkar** — himself a Dalit who had overcome extraordinary discrimination to earn doctorates from Columbia and the London School of Economics — emerged as the most powerful Dalit voice.\n\nIn **1930**, he organised Dalits into the **Depressed Classes Association** and began demanding political rights.\n\nAt the **Second Round Table Conference** (1931), Ambedkar demanded **separate electorates** for Dalits — just as Muslims had. His argument: Dalits are a distinct community with distinct interests. They need their OWN representatives, not representatives chosen by the same upper-caste majority that oppresses them.\n\n**Gandhi fiercely opposed** separate electorates. His argument: separate electorates would **permanently divide Hindu society** and slow down the integration of Dalits. Dalits, he believed, needed to be brought INTO the Hindu fold, not separated from it.","highlight":"**Ambedkar vs Gandhi:** Ambedkar demanded separate electorates for Dalits at Round Table Conference. Gandhi opposed — said it would permanently divide Hindu society. Two visions: Ambedkar wanted independent Dalit political power; Gandhi wanted Dalits integrated within Hinduism."},{"id":"ch2-s3-poona-pact","title":"The Poona Pact — A Painful Compromise","type":"text","text":"When the British government accepted Ambedkar''s demand and announced **separate electorates** for Dalits (the \"Communal Award,\" 1932), Gandhi began a **fast unto death** in Yeravda jail.\n\nThe pressure was enormous. If Gandhi died, Dalits would be blamed. Under this immense pressure, Ambedkar agreed to negotiate.\n\nThe result was the **Poona Pact (September 1932)**:\n- **Separate electorates** were abandoned\n- Instead, Dalits got **reserved seats** within **joint electorates** — more seats than the British had originally offered\n- The seats were reserved, but ALL voters (including upper castes) would vote\n\nAmbedkar accepted, but he was **deeply bitter**. He felt Gandhi had used the threat of his own death to **deny Dalits their political independence**. This bitterness would shape Ambedkar''s lifelong distrust of Congress.\n\nThe debate remains relevant today: India''s reservation system traces directly back to the Poona Pact.","highlight":"**Poona Pact (September 1932):** Separate electorates dropped. Dalits got reserved seats in joint electorates. Ambedkar agreed under pressure of Gandhi''s fast — but remained deeply bitter. India''s reservation system traces back to this pact.","inlineQuiz":{"question":"What was the outcome of the Poona Pact of 1932?","options":["Dalits were given separate electorates as demanded by Ambedkar","Dalits got reserved seats within joint electorates — a compromise","The British agreed to grant Purna Swaraj immediately","Gandhi and Ambedkar agreed to abolish the caste system"],"correctIndex":1,"explanation":"The Poona Pact was a compromise: separate electorates (Ambedkar''s demand) were abandoned, but Dalits received reserved seats within joint electorates — more seats than originally offered. Ambedkar agreed under the pressure of Gandhi''s fast unto death, but remained bitter about it."}},{"id":"ch2-s3-muslims","title":"Muslims — The Growing Distance","type":"text","text":"Many Muslim political organisations remained **lukewarm or hostile** to the Civil Disobedience Movement. The reasons had been building for years:\n\n**1. Khilafat collapse:** After the Khilafat movement ended (the Turkish ruler himself abolished the Caliphate in 1924), the Hindu-Muslim alliance fell apart. The shared cause was gone.\n\n**2. Communal riots:** Through the mid-1920s, Hindu-Muslim riots became more frequent. Trust eroded rapidly.\n\n**3. Congress = Hindu?** Congress became increasingly associated with **Hindu religious nationalists** and groups like the **Hindu Mahasabha**. Muslim leaders felt Congress was a Hindu party wearing secular clothes.\n\n**4. Jinnah''s frustration:** At the **1928 All Parties Conference**, **Muhammad Ali Jinnah** proposed reserved Muslim seats in a future legislature. The proposal was **rejected**. Jinnah, once a champion of Hindu-Muslim unity, began to distance himself from Congress permanently.","highlight":"**Muslims and CDM:** Alienated after Khilafat collapse, communal riots, Congress''s association with Hindu Mahasabha. Jinnah''s demand for reserved Muslim seats rejected (1928). Distance grows — foreshadowing Partition."},{"id":"ch2-s3-source-d","title":"Iqbal on Muslim Identity","type":"source","text":"Muhammad Iqbal, speaking at the Muslim League session in **1930**: \"I have no hesitation in declaring that if the principle that the **Indian Muslim is entitled to full and free development** on the lines of his own culture and tradition in his own Indian homelands is recognised as the basis of a permanent communal settlement, he will be ready to **stake his all for the freedom of India**.\"\n\nNotice what Iqbal is saying: Muslims WANT freedom — but only if they are guaranteed the right to develop their own identity. Without that guarantee, they cannot trust a Hindu-majority swaraj."},{"id":"ch2-s3-gandhi-thread","title":"Gandhi''s Impossible Task","type":"text","text":"Step back and see what Gandhi was trying to do:\n\n- **Rich peasants** wanted lower revenue → Congress called off CDM without getting it\n- **Poor peasants** wanted rent relief → Congress wouldn''t challenge landlords\n- **Workers** wanted fair wages → Congress wouldn''t challenge industrialists\n- **Women** wanted leadership → Congress offered them symbolism\n- **Dalits** wanted political independence → Gandhi opposed separate electorates\n- **Muslims** wanted guaranteed rights → Congress couldn''t (or wouldn''t) deliver\n\nGandhi was trying to hold together an alliance of people with **contradictory interests**. Every time he satisfied one group, he alienated another. The \"unity\" of the freedom movement was always fragile — held together more by opposition to the British than by a shared vision of the future.","highlight":"**The fundamental tension:** Every group wanted something different from swaraj. Satisfying one meant alienating another. Unity was held together by opposition to the British — not by a shared vision of India''s future."},{"id":"ch2-s3-closer","title":"The Promise, Revisited","type":"text","text":"Remember Gandhi''s promise? **Refuse to cooperate, and swaraj would come.**\n\nIt didn''t come in 1921 (Non-Cooperation). It didn''t come in 1930 (Civil Disobedience). And now the movement was not just failing to defeat the British — it was revealing deep **fractures within Indian society** itself.\n\nDalits asked: **whose swaraj?** Muslims asked: **will we be safe in it?** Women asked: **will we have a voice?** Workers asked: **will we have dignity?**\n\nThe Civil Disobedience Movement achieved something extraordinary — **millions of ordinary Indians defying an empire**, the Salt March becoming **global news**, women entering public life in **unprecedented numbers**. But the cracks were real. And those cracks would widen, all the way to **1947**.","highlight":"**The story so far:** CDM achieved extraordinary things (global attention, mass participation, women''s mobilisation). But Dalits, Muslims, workers, and women all found the movement''s promises incomplete. The cracks would widen to 1947."},{"id":"ch2-s3-significance","title":"Why This Section Matters","type":"exam-prep","text":"Q: Why is the Salt March considered an effective symbol of resistance against colonialism?\nMarks: 3 Marks\nA: Salt was consumed by every Indian regardless of class, caste, religion, or gender — making it a universal symbol that united the entire nation.\nA: The British salt monopoly and salt tax directly affected the poorest Indians — giving the movement moral power.\nA: Breaking the salt law was a simple, non-violent act that anyone could perform — turning every Indian into a potential satyagrahi.\nA: The 240-mile march attracted global media attention, making India''s freedom struggle international news.\nTip: This is one of the most frequently asked questions across all CBSE papers. Cover: universal symbol + affects poorest + easy to defy + global attention. Each point = 1 mark.\nTip: For 5-mark version: add how CDM was different from NCM (active law-breaking vs passive boycott) + how it spread (peasants refusing revenue, tribals violating forest laws, workers striking)."},{"id":"ch2-s3-significance-2","title":"Significance of Civil Disobedience","type":"text","text":"**What did the Civil Disobedience Movement achieve?**\n\n**1.** The **Salt March made India''s freedom struggle global news** — for the first time, the world was watching\n**2.** British authority was **directly challenged** — not just boycotted but actively defied\n**3.** **Women entered the public sphere** in unprecedented numbers — a permanent social transformation\n**4.** The **business class** publicly aligned with the national movement for the first time\n**5.** Even in \"failure,\" it showed the British that governing India without Indian consent was becoming **impossible**\n\n**But the limits were real:**\n- Dalits and Muslims remained **wary of Congress**\n- The movement could not resolve the **fundamental tension** between different groups\n- The fractures visible in CDM foreshadowed **Partition** in 1947","highlight":"**CDM significance:** (1) Global attention (Salt March) (2) Direct challenge to British authority (3) Women''s unprecedented participation (4) Business class alignment (5) Showed British rule was unsustainable. But: Dalit and Muslim wariness foreshadowed Partition."},{"id":"ch2-s3-timeline","title":"Section 3 Timeline","type":"timeline-ref","text":"1923 — **Swaraj Party** formed by C.R. Das and Motilal Nehru\n1928 — **HSRA founded**; Bhagat Singh emerges as revolutionary leader\n1928 — **Simon Commission** arrives — \"Go Back Simon!\" — Lala Lajpat Rai beaten, later dies\n1929 — **April** — Bhagat Singh throws bomb in Central Legislative Assembly\n1929 — **December** — **Lahore Congress** under Nehru demands **Purna Swaraj**\n1930 — **26 January** — **Independence Day** celebrated; Independence Day Pledge taken\n1930 — **31 January** — Gandhi writes to Viceroy Irwin with 11 demands\n1930 — **12 March to 6 April** — **Dandi March** (Sabarmati → Dandi, 240 miles, 78 volunteers)\n1930 — **6 April** — Gandhi breaks salt law at Dandi — **CDM begins**\n1930 — **May** — Gandhi arrested; ~100,000 arrested across India\n1930 — **Ambedkar** forms Depressed Classes Association; demands separate electorates\n1931 — **March** — **Gandhi-Irwin Pact** — CDM called off; Gandhi to attend Round Table Conference\n1931 — **23 March** — **Bhagat Singh executed** (age 23)\n1931 — **December** — Second Round Table Conference in London — negotiations fail\n1932 — **September** — **Poona Pact** — reserved seats for Dalits in joint electorates\n1934 — CDM fizzles out","highlight":"**Key exam dates:** 1929 (Lahore Congress — Purna Swaraj), 1930 (26 Jan Independence Day, 12 Mar-6 Apr Dandi March, 6 Apr salt law broken), 1931 (Gandhi-Irwin Pact), 1932 (Poona Pact). These are tested EVERY year."},{"id":"ch2-s3-fig10","title":"The Movement in Pictures","type":"figure","text":"The Civil Disobedience Movement produced some of the most iconic images of India''s freedom struggle. From Gandhi walking to the sea with his bamboo staff, to thousands of women joining processions for the first time, to peaceful satyagrahis being beaten by British police — these images travelled the world and changed how people saw India''s struggle. The British could no longer claim they were \"civilising\" India when newspapers showed them beating unarmed men and women.","imageId":"ch2-fig-10"},{"id":"ch2-s3-limits-quiz","title":"Test Yourself","type":"text","text":"The limits of CDM are a **favourite CBSE exam topic**. Remember this framework:\n\n**Dalits:** Feared swaraj = upper-caste Hindu rule. Ambedkar demanded separate electorates. Poona Pact (1932) = compromise (reserved seats in joint electorates).\n\n**Muslims:** Alienated after Khilafat collapsed. Congress associated with Hindu Mahasabha. Jinnah''s demands rejected. Growing distance.\n\n**Rich peasants:** Disappointed when CDM called off without revenue reduction.\n\n**Poor peasants:** Wanted rent relief from landlords — Congress wouldn''t support.\n\n**Workers:** Wanted fair wages — Congress wouldn''t challenge industrialists.\n\n**Women:** Participated massively but denied leadership positions.","inlineQuiz":{"question":"Why did many Dalits remain distant from the Congress-led Civil Disobedience Movement?","options":["They feared swaraj would mean upper-caste Hindu rule, and Congress had long ignored Dalit concerns","They supported the British government against Congress","They were not allowed to participate in any political movements","They wanted to join the Muslim League instead"],"correctIndex":0,"explanation":"Dalits feared that swaraj under Congress would simply replace British rule with upper-caste Hindu rule. Congress had long ignored Dalit demands to avoid offending its upper-caste base. Under Ambedkar, Dalits demanded their own political representation — separate electorates — to protect their interests."}}]}],"keyPoints":["After 1922: Congress split — Swaraj Party (council politics) vs mass agitation (Nehru, Bose)","Bhagat Singh and HSRA (1928): revolutionary violence as alternative — \"Inquilab Zindabad!\"","Simon Commission (1928): all-British, no Indian member — \"Go Back Simon!\" united parties in protest","Lahore Congress (December 1929): formal demand for Purna Swaraj — 26 January 1930 = Independence Day","Salt March (12 March - 6 April 1930): 78 volunteers, 240 miles, Sabarmati to Dandi — launched Civil Disobedience","CDM different from NCM: not just boycott but active law-breaking — manufacturing salt, refusing revenue","Limits of CDM: Dalits (Ambedkar demanded separate electorates), Muslims felt alienated from Congress","Poona Pact (1932): reserved seats for Dalits but within joint electorates"],"figureIds":["ch2-fig-6","ch2-fig-7","ch2-fig-8","ch2-fig-9","ch2-fig-10"],"sourceIds":["ch2-source-c","ch2-source-d"],"vocabularyIds":["ch2-vocab-purna-swaraj"]},{"id":"s4","number":4,"title":"The Sense of Collective Belonging","color":"hist-purple","icon":"🎨","subsections":[{"id":"ch2-s4-bharat-mata","title":"The Image of Bharat Mata","narrativeCards":[{"id":"ch2-s4-opener","title":"From Germania to Bharat Mata","type":"text","text":"In Chapter 1, we saw how Europeans created **female allegories** to represent their nations — **Marianne** for France, **Germania** for Germany. These weren''t real women. They were **symbols** — images that made the abstract idea of a \"nation\" feel real, visible, emotional.\n\nIndia did exactly the same thing. The nation became a **mother** — **Bharat Mata**.\n\nBut here''s the question that CBSE loves to ask: **did this image unite everyone, or did it leave some people out?**","highlight":"**Cross-chapter connection:** Germania/Marianne (Ch1) = Bharat Mata (Ch2). Same technique — female allegory personifying the nation. But India''s version had a problem Europe''s didn''t."},{"id":"ch2-s4-bankim","title":"Vande Mataram — The Hymn That Started It All","type":"text","text":"The idea of India as a mother-goddess first took literary form in the **1870s**, when **Bankim Chandra Chattopadhyay** wrote the hymn **Vande Mataram** (\"I bow to thee, Mother\"). He included it in his Bengali novel **Anandamath** (1882).\n\nThe song imagined India as a divine mother — powerful, nurturing, worthy of devotion. During the **Swadeshi movement** in Bengal (1905), *Vande Mataram* became the **anthem of resistance**. It was sung at rallies, printed on pamphlets, and chanted during protests against the partition of Bengal.\n\nFor millions, singing *Vande Mataram* was how you **declared** you were Indian.","highlight":"**Vande Mataram (1870s):** Written by Bankim Chandra Chattopadhyay in *Anandamath*. Became the anthem of the Swadeshi movement (1905). The song imagined India as a mother-goddess."},{"id":"ch2-s4-tagore-painting","title":"Abanindranath Tagore''s Bharat Mata (1905)","type":"figure","text":"In **1905**, the artist **Abanindranath Tagore** painted the most famous image of Bharat Mata. Look carefully at what he chose to show:\n\nShe is **calm, composed, and ascetic** — like a Hindu goddess but dressed simply. She has **four hands**, each holding something symbolic: **sheaves of paddy** (food), a piece of **white cloth** (clothing), a **book** (learning), and a **mala** (prayer beads — spirituality).\n\nThis is NOT a powerful warrior queen. She is a **spiritual, nurturing mother** — giving her children what they need: food, clothing, knowledge, and spiritual guidance. The image was **deeply devotional** in tone.","imageId":"ch2-fig-12","highlight":"**Fig 12 — Bharat Mata by Abanindranath Tagore (1905):** Calm, ascetic, spiritual figure. Holds paddy (food), cloth (clothing), book (learning), mala (spirituality). A nurturing mother, not a warrior."},{"id":"ch2-s4-later-bharat-mata","title":"A Different Bharat Mata — Power and Authority","type":"figure","text":"Now compare Tagore''s image with **later versions** of Bharat Mata. In these paintings, she is **completely different**:\n\nShe holds a **trishul** (trident) — a weapon associated with the Hindu god Shiva. She stands beside a **lion** (symbol of power and royalty) and an **elephant** (symbol of authority and strength). She wears a **crown** and looks commanding, not gentle.\n\nTagore''s Bharat Mata said: \"I am your **spiritual mother**.\" This Bharat Mata says: \"I am a **powerful nation** — fear me.\"\n\nThis shift — from spiritual to powerful — mirrors what happened in European nationalism too. But it also deepened a problem.","imageId":"ch2-fig-14a","highlight":"**Fig 14a — Later Bharat Mata:** Trishul (trident), lion, elephant — symbols of POWER. Very different from Tagore''s calm, spiritual figure. The nation-as-mother became the nation-as-warrior.","inlineQuiz":{"question":"How does the later image of Bharat Mata differ from Abanindranath Tagore''s 1905 painting?","options":["The later image shows her as calm and spiritual with prayer beads","The later image removes all religious symbolism","The later image shows her with power symbols — trishul, lion, and elephant","The later image portrays her as a British queen"],"correctIndex":2,"explanation":"Tagore''s 1905 Bharat Mata was calm, ascetic, and spiritual (with paddy, cloth, book, mala). Later versions showed her with power symbols — trishul (trident), lion, elephant — representing national strength and authority. This is a favourite CBSE comparison question."}},{"id":"ch2-s4-bharat-mata-problem","title":"The Problem: Whose Mother?","type":"text","text":"Here''s the exam-critical question that CBSE asks almost every year:\n\n**Would these images appeal to ALL Indians?**\n\nThink about it. Bharat Mata is drawn from **Hindu iconography** — the four arms, the trishul, the mala. *Vande Mataram* comes from a **Hindu novel**. The lion and trident are **Hindu religious symbols**.\n\nIf your idea of the nation is wrapped in **one religion''s imagery**, what happens to Muslims, Christians, Sikhs, and others who don''t see themselves in that image?\n\nThis was the fundamental tension: the **very symbols meant to unite** the nation were, inadvertently, **excluding** large sections of it. It''s the same tension we saw with the Salt March — Gandhi tried to include everyone, but the cultural language of nationalism kept defaulting to **Hindu imagery**.","highlight":"**The limit of Bharat Mata:** Hindu iconography (trishul, mala, four arms) meant Muslims and other communities didn''t see themselves in the national image. Symbols meant to unite were inadvertently dividing."}]},{"id":"ch2-s4-folklore-symbols","title":"Folklore, Songs, Symbols and Identity","narrativeCards":[{"id":"ch2-s4-folk-revival","title":"Collecting the Nation''s Soul","type":"text","text":"Remember the **Grimm Brothers** from Chapter 1? They collected German folk tales to prove that a German nation existed in the hearts of ordinary people — long before it existed on any map.\n\n**Indian nationalists did exactly the same thing.**\n\nIn Bengal, **Rabindranath Tagore** went from village to village collecting **ballads, nursery rhymes, and myths**. He argued that these folk songs revealed the true spirit of India — not the Westernised culture of the elite, but the living traditions of the common people.\n\nIn Madras, **Natesa Sastri** published a massive **four-volume collection of Tamil folk tales**. He called folklore **\"the most trustworthy manifestation of people''s real thoughts and characteristics.\"**","highlight":"**Cross-chapter connection:** Grimm Brothers (Germany, Ch1) = Tagore & Natesa Sastri (India, Ch2). Same method — collect folk tales to build national identity from the ground up."},{"id":"ch2-s4-flag-evolution","title":"The Flag — From Symbol to Weapon","type":"text","text":"Symbols of unity evolved over time. The **national flag** went through several versions:\n\n**Swadeshi era (1905):** A tricolour flag — **red, green, and yellow** — with **eight lotuses** representing the eight provinces of British India, and a **crescent moon** to symbolise **Hindu-Muslim unity**.\n\n**1921:** Gandhiji designed the **Swaraj flag** — **red, green, and white** — with a **spinning wheel (charkha)** at the centre. The charkha represented **self-reliance** — the idea that Indians could weave their own cloth, build their own economy, and govern themselves.\n\nCarrying the flag during marches and protests became an **act of defiance** in itself. The flag wasn''t just a symbol — it was a **weapon of resistance**.","highlight":"**Flag evolution:** Swadeshi tricolour (8 lotuses + crescent moon) → Gandhian Swaraj flag (1921, with charkha/spinning wheel = self-reliance). Carrying it = act of defiance."},{"id":"ch2-s4-tilak-print","title":"Icons of the Nation — Popular Prints","type":"figure","text":"Shared symbols were not only flags and goddesses — they were also **the faces of leaders**, mass-produced as cheap prints for ordinary homes. This early-twentieth-century print shows **Bal Gangadhar Tilak**, the fiery nationalist who declared **\"Swaraj is my birthright, and I shall have it.\"** Hung on a wall or carried in a procession, such images turned distant political leaders into **shared household icons** — another quiet way in which millions of Indians came to feel part of **one nation**.","imageId":"ch2-fig-11","highlight":"**Popular prints (e.g. Tilak — \"Swaraj is my birthright\"):** mass-produced images of leaders gave Indians a shared visual vocabulary and deepened the sense of collective belonging."},{"id":"ch2-s4-rewriting-history","title":"Rewriting History — India''s \"Golden Age\"","type":"text","text":"Nationalists had another powerful tool: **reinterpreting India''s past**.\n\nThe British claimed they were \"civilising\" India — that Indians were backward, primitive, incapable of self-rule. Indian nationalists fought back by writing about India''s **\"golden age\"** — great achievements in **art, architecture, science, mathematics, law, and philosophy** — long before the British arrived.\n\nWriters like **Tarinicharan Chattopadhyay** wrote nationalist histories showing that India had been a great civilisation. The message was clear: **Indians were never inferior.** The British hadn''t \"civilised\" India — they had **exploited** a civilisation that was already great.","highlight":"**Rewriting history:** Nationalists countered the British \"civilising mission\" narrative by celebrating India''s golden age — great achievements in science, art, philosophy BEFORE colonisation."},{"id":"ch2-s4-nationalist-imagery","title":"Printing and Nationalism","type":"figure","text":"Nationalist imagery spread through **printed material** — calendars, posters, newspapers, pamphlets. Images of Bharat Mata, leaders like Gandhi, symbols like the charkha and the national flag — all were mass-produced and distributed across India. The **printing press** became a tool of nationalism, just as it had been in Europe (Chapter 1). These images gave people a shared visual vocabulary — a way to **see** themselves as part of one nation.","imageId":"ch2-fig-13"},{"id":"ch2-s4-source-e","type":"source","text":"Source E — Tarinicharan Chattopadhyay (1858):\n\n\"In earlier times, foreign travellers in India marvelled at the courage, truthfulness and modesty of the people of this land... But alas! the character of the people of this land has undergone a total transformation... now a few soldiers from a tiny island far away are lording it over the land of India.\"","highlight":"**Source E analysis:** Chattopadhyay contrasts India''s glorious past (courage, truthfulness) with the present (ruled by \"a tiny island\"). Purpose: counter British claims of Indian inferiority. Technique: nationalist history-writing."},{"id":"ch2-s4-hindu-limit","title":"The Same Problem Again","type":"text","text":"But once again, there was a **fundamental problem**.\n\nThe \"glorious past\" that nationalists celebrated was largely a **Hindu past**. The great achievements were linked to **temples, Sanskrit texts, Vedic science, ancient Hindu kingdoms**. The \"golden age\" was placed before the arrival of Muslim rulers — implying that the Muslim period was a period of **decline**.\n\nWhat about Muslims? What about Dalits, who had been **oppressed** during that very \"golden age\"? What about tribal communities whose cultures were completely ignored?\n\nThe tools meant to unite were, once again, **inadvertently dividing**. This is the recurring tension of Indian nationalism: **every attempt to create a shared identity kept defaulting to the culture of the dominant group**.","highlight":"**The recurring tension:** The \"golden age\" was Hindu past (temples, Sanskrit, Vedic science). Muslims, Dalits, and tribals didn''t see themselves in this story. Cultural nationalism kept defaulting to dominant-group imagery.","inlineQuiz":{"question":"What was the major limitation of using folk tales, nationalist histories, and images like Bharat Mata to build national identity?","options":["The British banned all these activities completely","The printing press was not available in India","Nobody was interested in folk tales or history","These cultural symbols drew mainly from Hindu traditions, excluding Muslims and other communities"],"correctIndex":3,"explanation":"While folk revival, history-writing, and images like Bharat Mata helped build a sense of national identity, they drew mainly from Hindu cultural traditions. This meant Muslims, Dalits, and other communities felt excluded from the national story — the very symbols meant to unite were inadvertently dividing."}}]},{"id":"ch2-s4-conclusion","title":"Conclusion — Many Voices, One Struggle","narrativeCards":[{"id":"ch2-s4-quit-india","title":"Quit India Movement (1942)","type":"infobox","text":"**Quit India Movement (1942)**\n\nBy 1942, the Second World War had reached India''s doorstep. Japan had captured Burma and was advancing towards India. The British sent **Sir Stafford Cripps** to negotiate with Indian leaders — but the **Cripps Mission failed**. Congress rejected the offer as too little, too late.\n\nOn **8 August 1942**, the **Congress Working Committee** passed the **Quit India resolution** at Bombay (Wardha resolution). Gandhi gave the call: **\"Do or Die\"** — either free India or die trying.\n\n**What happened next:**\n- All major Congress leaders were **immediately arrested** — Gandhi, Nehru, Patel, Azad\n- But the movement didn''t die — it **spread like wildfire** without central leadership\n- **Students** left colleges, **workers** went on strike, **peasants** rose in revolt\n- Underground leaders emerged: **Jayaprakash Narayan**, **Aruna Asaf Ali**\n- Women played a crucial role: **Matangini Hazra** (shot dead carrying the flag), **Kanaklata Barua** (killed leading a procession)\n- The British took **over a year** to fully suppress the movement\n\nQuit India was the **largest mass movement** in Indian history. It proved that the desire for freedom had become **unstoppable**.","highlight":"**Quit India (1942):** \"Do or Die\" — Gandhi''s call. Wardha/Bombay resolution (8 Aug 1942). Leaders arrested but movement spread without leadership. Key figures: Jayaprakash Narayan, Aruna Asaf Ali, Matangini Hazra. Largest mass movement in Indian history."},{"id":"ch2-s4-quit-india-figure","title":"Women in the Quit India Movement","type":"figure","text":"Women were at the forefront of the Quit India Movement. Across India, they led processions, organised underground resistance, and defied British authority. This image shows a **women''s procession in Bombay** during the movement — a powerful reminder that Indian nationalism was not just a story of great men. It was a story of **millions of ordinary people** — men and women — who chose to fight for freedom.","imageId":"ch2-fig-14b"},{"id":"ch2-s4-chapter-closer","title":"The Promise — Resolved","type":"text","text":"Remember Gandhi''s promise from *Hind Swaraj*?\n\n> \"If Indians refuse to cooperate, British rule would collapse within a year, and swaraj would come.\"\n\nIt didn''t come in **1921** — Non-Cooperation was called off after Chauri Chaura.\nIt didn''t come in **1930** — the Salt March shook the empire but didn''t break it.\nIt didn''t come in **1942** — Quit India was brutally suppressed.\n\n**It took 27 more years — until 1947.** And when swaraj finally came, it came with **Partition** — the Hindu-Muslim unity that Gandhi had fought for his entire life was, tragically, broken.\n\nBut here''s what **DID** survive: the idea that **India is a nation**.\n\nThat idea was born in these movements. In the salt marches and the bonfires of foreign cloth. In the chanting of *Vande Mataram* and the spinning of khadi. In the peasants invoking Gandhi''s name to demand their rights and the workers walking out of plantations.\n\n**India became a nation not because everyone agreed — but because millions of people, with different dreams, chose to struggle together.**","highlight":"**Gandhi''s promise resolved:** Swaraj didn''t come in 1 year. It took 27 years (1920-1947). And it came with Partition. But the idea of India as a nation — born in these movements — survived."},{"id":"ch2-s4-cross-chapter","title":"Two Dreams — Sorrieu and Gandhi","type":"text","text":"In **Chapter 1**, the French artist **Sorrieu** dreamed of all nations marching together in peace — a world of democratic republics, united in brotherhood. In **Chapter 2**, **Gandhi** dreamed of all Indians marching together for freedom — 300 million people, united across religion, caste, and class.\n\n**Both dreams were imperfect.** Sorrieu''s vision of peaceful nationalism turned into wars, imperialism, and two World Wars. Gandhi''s vision of Hindu-Muslim unity ended in Partition.\n\n**Both dreams were partially betrayed.** But both changed history forever.\n\nThe European dream created **nation-states**. The Indian dream created the **world''s largest democracy**.\n\nAnd the fundamental difference? European nationalism was about **building new states** — often through blood and iron. Indian nationalism was about **liberating an existing nation** — through the radical insistence that non-violence was stronger than any army.","highlight":"**Ch1 vs Ch2 synthesis:** Sorrieu dreamed of nations in peace → got wars and imperialism. Gandhi dreamed of Indians united → got Partition. But Europe created nation-states, India created the world''s largest democracy. Key difference: Europe used force, India chose non-violence.","inlineQuiz":{"question":"What is the KEY difference between European nationalism (Chapter 1) and Indian nationalism (Chapter 2)?","options":["European nationalism was peaceful while Indian nationalism was violent","There was no significant difference between the two","European nationalism involved only the elite while Indian nationalism involved only peasants","European nationalism was about building new states (often through force), while Indian nationalism was about liberating from colonial rule (through non-violence)"],"correctIndex":3,"explanation":"European nationalism was about CREATING new nation-states — often through \"blood and iron\" (Bismarck). Indian nationalism was about LIBERATING an existing nation from colonial rule — through non-violent resistance (Gandhi). This contrast between force and non-violence is the key difference CBSE expects you to discuss."}},{"id":"ch2-s4-timeline","title":"Section 4 Timeline","type":"timeline-ref","text":"1870s — **Bankim Chandra Chattopadhyay** writes *Vande Mataram* (included in *Anandamath*, 1882)\n1905 — **Abanindranath Tagore** paints Bharat Mata; *Vande Mataram* becomes anthem of Swadeshi movement\n1905 — Swadeshi tricolour flag designed (red, green, yellow with 8 lotuses + crescent moon)\n1921 — Gandhiji designs the **Swaraj flag** (red, green, white with spinning wheel)\n1942 — **Quit India Movement** — \"Do or Die\" (8 August, Bombay/Wardha resolution)\n1947 — **Independence** — but with **Partition**","highlight":"**Key exam dates:** 1905 (Abanindranath Tagore''s Bharat Mata + Swadeshi flag), 1921 (Swaraj flag), 1942 (Quit India — \"Do or Die\")."},{"id":"ch2-s4-significance","title":"Why This Section Matters","type":"exam-prep","text":"Q: How did a variety of cultural processes play an important role in the making of nationalism in India?\nMarks: 5 Marks\nA: Image of Bharat Mata — Bankim Chandra''s Vande Mataram (1870s) and Abanindranath Tagore''s painting (1905) created a visual symbol of the nation as mother, inspiring devotion and patriotism.\nA: Folk revival — Rabindranath Tagore collected Bengali ballads, Natesa Sastri published Tamil folk tales. Like the Grimm Brothers in Europe, folk culture was used to build national identity from the ground up.\nA: The national flag evolved from the Swadeshi tricolour to Gandhi''s Swaraj flag (1921) with the spinning wheel — carrying it became an act of defiance against British rule.\nA: Rewriting history — Nationalist historians like Tarinicharan Chattopadhyay celebrated India''s \"golden age\" to counter the British claim of \"civilising\" India.\nA: However, these cultural symbols drew mainly from Hindu traditions — Bharat Mata''s iconography, Vande Mataram from a Hindu novel, the \"golden age\" linked to Hindu past — which alienated Muslims and other communities.\nTip: This is a very frequently asked 5-mark question. Structure: Bharat Mata + folk revival + flag + history-writing + the limitation (Hindu bias). Each point = 1 mark.\nTip: For comparison questions: connect to Chapter 1 — Bharat Mata = Germania/Marianne, folk revival = Grimm Brothers. The technique is identical; the context is different."}]}],"keyPoints":["Bharat Mata: Bankim Chandra''s Vande Mataram (1870s) → Abanindranath Tagore''s painting (1905) → later versions with trishul","Folk revival: Tagore collected ballads in Bengal, Natesa Sastri collected Tamil folk tales — like Grimm Brothers in Europe","The flag evolved: Swadeshi tricolour → Gandhian Swaraj flag (1921) with spinning wheel → symbol of defiance","Rewriting history: nationalist historians celebrated India''s \"golden age\" — but it was largely Hindu history","The limit: when symbols draw from one religion''s imagery, other communities feel excluded","Compare with Chapter 1: Bharat Mata = Indian version of Germania/Marianne (female allegory of nation)"],"figureIds":["ch2-fig-11","ch2-fig-12","ch2-fig-13","ch2-fig-14a","ch2-fig-14b"],"sourceIds":["ch2-source-e"],"vocabularyIds":[]}]},"keyDates":[{"id":"ch2-date-1915","year":1915,"event":"Gandhi returns to India from South Africa","detail":"Mahatma Gandhi returned to India in January 1915 after successfully fighting racist laws in South Africa using satyagraha. He would spend the next few years travelling India, understanding the conditions of the people before launching his first Indian satyagraha.","sectionId":"s1","importance":"major"},{"id":"ch2-date-1917","year":1917,"event":"Champaran Satyagraha — Gandhi''s first satyagraha in India","detail":"Gandhi travelled to Champaran in Bihar to support indigo farmers forced to grow indigo under oppressive conditions. This was his first successful use of satyagraha in India, establishing his method and reputation.","sectionId":"s1","importance":"major"},{"id":"ch2-date-1918","year":1918,"event":"Ahmedabad and Kheda satyagrahas","detail":"In Ahmedabad, Gandhi supported cotton mill workers demanding fair wages. In Kheda (Gujarat), he organised peasants demanding tax relief after crop failure. Both succeeded, proving satyagraha worked at different scales.","sectionId":"s1","importance":"minor"},{"id":"ch2-date-1919-rowlatt","year":1919,"event":"Rowlatt Act passed — nationwide hartal on 6 April","detail":"The Rowlatt Act gave the British government power to repress political activities and detain political prisoners without trial for two years. Passed despite unanimous Indian opposition. Gandhi called a nationwide hartal on 6 April 1919.","sectionId":"s1","importance":"major"},{"id":"ch2-date-1919-jallianwala","year":1919,"event":"Jallianwala Bagh massacre — 13 April 1919","detail":"General Dyer ordered troops to fire on a peaceful crowd gathered at Jallianwala Bagh in Amritsar. The enclosed ground had blocked exits. Hundreds were killed, including many who had come for the annual Baisakhi fair and were unaware of martial law. Dyer said his aim was \"to produce a moral effect.\"","sectionId":"s1","importance":"major"},{"id":"ch2-date-1919-khilafat","year":1919,"event":"Khilafat Committee formed in Bombay (March 1919)","detail":"To defend the Khalifa''s temporal powers against the harsh treaty being imposed after Ottoman Turkey''s defeat in WWI. Muhammad Ali and Shaukat Ali began discussing joint action with Gandhi, leading to the Hindu-Muslim alliance.","sectionId":"s1","importance":"minor"},{"id":"ch2-date-1918-19","year":1918,"yearEnd":1919,"event":"Crop failures and influenza epidemic — 12-13 million perish","detail":"Crops failed in 1918-19 and 1920-21, causing acute food shortages. This was accompanied by the devastating influenza epidemic. According to the 1921 census, 12 to 13 million people died from famines and the epidemic.","sectionId":"s1","importance":"minor"},{"id":"ch2-date-1920-calcutta","year":1920,"event":"Calcutta Congress session — September 1920","detail":"Gandhi convinced other Congress leaders of the need to start a non-cooperation movement in support of Khilafat as well as for swaraj. This session formally linked the two causes.","sectionId":"s1","importance":"minor"},{"id":"ch2-date-1921","year":1921,"event":"Non-Cooperation-Khilafat Movement launched (January 1921)","detail":"The movement began with boycott of British institutions, titles, courts, schools, and foreign goods. Various social groups — middle class, peasants, tribals, workers — joined with their own specific demands and interpretations of swaraj.","sectionId":"s2","importance":"major"},{"id":"ch2-date-1922-chauri","year":1922,"event":"Chauri Chaura incident — Gandhi withdraws Non-Cooperation (February 1922)","detail":"At Chauri Chaura in Gorakhpur, a peaceful demonstration turned violent. The crowd set fire to a police station, killing 22 policemen. Gandhi, devastated by the violence, called off the entire Non-Cooperation Movement. Other leaders were furious, but Gandhi insisted: a violent movement betrays its own soul.","sectionId":"s2","importance":"major"},{"id":"ch2-date-1924","year":1924,"event":"Alluri Sitaram Raju captured and executed","detail":"Raju led a guerrilla movement in the Gudem Hills of Andhra Pradesh against the British. He wore khadi and invoked Gandhi but used violent methods. He was captured and executed, becoming a folk hero.","sectionId":"s2","importance":"minor"},{"id":"ch2-date-1927","year":1927,"event":"FICCI formed — Indian industrialists organise","detail":"The Federation of Indian Chambers of Commerce and Industries (FICCI), led by industrialists like Purshottamdas Thakurdas and G.D. Birla, was formally established to protect Indian business interests against colonial economic policies.","sectionId":"s3","importance":"minor"},{"id":"ch2-date-1928-simon","year":1928,"event":"Simon Commission arrives — \"Go Back Simon!\"","detail":"The British sent the Simon Commission to review India''s constitutional system. It had no Indian members — all British. United protests from Congress and Muslim League greeted it with \"Go Back Simon!\" slogans. Lala Lajpat Rai was beaten by police during the protest and later died from injuries.","sectionId":"s3","importance":"major"},{"id":"ch2-date-1928-hsra","year":1928,"event":"Hindustan Socialist Republican Army (HSRA) founded","detail":"Founded by Bhagat Singh, Jatin Das, and Ajoy Ghosh at Ferozeshah Kotla ground, Delhi. In April 1929, Bhagat Singh and Batukeswar Dutta threw a bomb in the Legislative Assembly — not to kill but to \"make the deaf hear.\" Bhagat Singh was executed at age 23.","sectionId":"s3","importance":"minor"},{"id":"ch2-date-1929-lahore","year":1929,"event":"Lahore Congress — demand for Purna Swaraj (December 1929)","detail":"Under Jawaharlal Nehru''s presidency, the Congress formally demanded Purna Swaraj (complete independence) — no more dominion status. 26 January 1930 was declared Independence Day. The celebrations attracted little attention — Gandhi needed a dramatic gesture.","sectionId":"s3","importance":"major"},{"id":"ch2-date-1930-dandi","year":1930,"event":"Salt March: Sabarmati to Dandi (12 March - 6 April 1930)","detail":"Gandhi marched 240 miles from Sabarmati Ashram to the coastal town of Dandi with 78 volunteers, walking about 10 miles a day for 24 days. Thousands joined along the way. On 6 April, he picked up salt at Dandi, breaking the salt law and launching the Civil Disobedience Movement.","sectionId":"s3","importance":"major"},{"id":"ch2-date-1930-ambedkar","year":1930,"event":"Ambedkar establishes Depressed Classes Association","detail":"Dr. B.R. Ambedkar organised the dalits into the Depressed Classes Association in 1930, demanding reserved seats and separate electorates for the community. This brought the issue of dalit rights into the national spotlight.","sectionId":"s3","importance":"minor"},{"id":"ch2-date-1931-pact","year":1931,"event":"Gandhi-Irwin Pact — Gandhi ends Civil Disobedience (March 1931)","detail":"Gandhi agreed to call off the movement and attend the Round Table Conference in London. The government agreed to release political prisoners. Gandhi went to London in December 1931 but negotiations failed.","sectionId":"s3","importance":"major"},{"id":"ch2-date-1932-poona","year":1932,"event":"Poona Pact — Ambedkar and Gandhi resolve separate electorates dispute","detail":"When the British accepted Ambedkar''s demand for separate electorates for dalits, Gandhi began a fast unto death. Ambedkar ultimately agreed to the Poona Pact: the Depressed Classes (later Scheduled Castes) got reserved seats in provincial and central councils, but they would be voted in by the general electorate, not a separate one.","sectionId":"s3","importance":"major"},{"id":"ch2-date-1942","year":1942,"event":"Quit India Movement launched (8 August 1942)","detail":"After the failure of the Cripps Mission and the effects of WWII, Gandhi launched the Quit India Movement with the famous call: \"Do or Die.\" The Congress Working Committee passed the Quit India resolution on 14 July 1942 at Wardha. On 8 August in Bombay, it was endorsed. Mass participation across the country — the British took over a year to suppress it.","sectionId":"s4","importance":"major"}],"vocabulary":[{"id":"ch2-vocab-satyagraha","term":"Satyagraha","definition":"Satya (truth) + Agraha (insistence) = insistence on truth. A method of mass agitation developed by Gandhi — not passive resistance but active, non-violent protest. The power of the strong, not the weak. A satyagrahi does not seek to destroy the enemy but to convert them through truth and suffering.","sectionId":"s1","example":"Gandhi used satyagraha first in South Africa against racist laws, then in India at Champaran (1917), Ahmedabad (1918), and Kheda (1918)","examRelevance":"high"},{"id":"ch2-vocab-forced-recruitment","term":"Forced Recruitment","definition":"A process by which the colonial state forced people to join the army. During World War I, villagers were compelled to serve as soldiers against their will, causing widespread anger in rural India.","sectionId":"s1","example":"Villages were called upon to supply soldiers during WWI, creating deep resentment against the British","examRelevance":"medium"},{"id":"ch2-vocab-hartal","term":"Hartal","definition":"A work stoppage or general strike as a form of protest. Shops, offices, and factories close down. It is a distinctly Indian form of civil resistance — shutting down economic activity to show collective anger.","sectionId":"s1","example":"Gandhi called for a nationwide hartal on 6 April 1919 to protest the Rowlatt Act","examRelevance":"medium"},{"id":"ch2-vocab-boycott","term":"Boycott","definition":"The refusal to deal and associate with people, or participate in activities, or buy and use things — usually as a form of protest. Named after Captain Charles Boycott, an Irish land agent who was ostracised by his community in 1880.","sectionId":"s2","example":"During Non-Cooperation, Indians boycotted foreign cloth, British schools, courts, and government titles. Import of foreign cloth halved from Rs 102 crore to Rs 57 crore.","examRelevance":"high"},{"id":"ch2-vocab-begar","term":"Begar","definition":"Labour that villagers were forced to contribute without any payment. A form of exploitation by landlords (talukdars) and the colonial government, particularly common in Awadh and tribal regions.","sectionId":"s2","example":"Peasants in Awadh were forced to do begar on landlords'' farms. In the Gudem Hills, tribals were forced to contribute begar for road building.","examRelevance":"high"},{"id":"ch2-vocab-picket","term":"Picket","definition":"A form of demonstration or protest by which people block the entrance to a shop, factory, or office. Used extensively during the boycott of foreign goods and liquor shops.","sectionId":"s2","example":"During the Civil Disobedience Movement, women picketed foreign cloth and liquor shops across India","examRelevance":"medium"},{"id":"ch2-vocab-swaraj","term":"Swaraj","definition":"Swa (self) + Raj (rule) = self-rule. The central demand of the Indian national movement. But it meant different things to different people: constitutional self-governance to the middle class, land and rent relief to peasants, freedom of movement to plantation workers, dignity to Dalits.","sectionId":"s2","example":"Gandhi declared in Hind Swaraj (1909) that if Indians refused to cooperate, British rule would collapse and swaraj would come within a year","examRelevance":"high"},{"id":"ch2-vocab-purna-swaraj","term":"Purna Swaraj","definition":"Purna (complete) + Swaraj (self-rule) = complete independence. Formally demanded at the Lahore Congress session in December 1929, under Jawaharlal Nehru''s presidency. 26 January 1930 was declared Independence Day.","sectionId":"s3","example":"The demand for Purna Swaraj replaced the earlier demand for \"dominion status\" — Indians now wanted complete separation from Britain, not just self-governance within the empire","examRelevance":"high"}],"sources":[{"id":"ch2-source-a","label":"Source A","author":"Mahatma Gandhi","title":"On Satyagraha","sectionId":"s1","text":"''It is said of \"passive resistance\" that it is the weapon of the weak, but the power which is the subject of this article can be used only by the strong. This power is not passive resistance; indeed it calls for intense activity. The movement in South Africa was not passive but active ...\n\nSatyagraha is not physical force. A satyagrahi does not inflict pain on the adversary; he does not seek his destruction ... In the use of satyagraha, there is no ill-will whatever.\n\nSatyagraha is pure soul-force. Truth is the very substance of the soul. That is why this force is called satyagraha. The soul is informed with knowledge. In it burns the flame of love. ... Non-violence is the supreme dharma ...\n\nIt is certain that India cannot rival Britain or Europe in force of arms. The British worship the war-god and they can all of them become, as they are becoming, bearers of arms. The hundreds of millions in India can never carry arms. They have made the religion of non-violence their own ...''","analysis":["Gandhi explicitly rejects the term \"passive resistance\" — satyagraha is ACTIVE, not passive","A satyagrahi does not destroy the enemy but seeks to convert them through truth and suffering","Satyagraha is \"soul-force\" — rooted in truth (satya) and love, not in physical power","Gandhi acknowledges India cannot match British military power — non-violence is both a moral choice and a practical necessity","Non-violence is not weakness but requires MORE strength than violence — \"the weapon of the strong\"","Exam tip: CBSE frequently asks \"What did Gandhi mean by satyagraha?\" — use this source to explain the concept"]},{"id":"ch2-source-b","label":"Source B","author":"Jawaharlal Nehru","title":"On the Peasant Meeting at Rae Bareli","year":"1921","sectionId":"s2","text":"On 6 January 1921, the police in United Provinces fired at peasants near Rae Bareli. Jawaharlal Nehru wanted to go to the place of firing, but was stopped by the police. Agitated and angry, Nehru addressed the peasants who gathered around him. This is how he later described the meeting:\n\n''They behaved as brave men, calm and unruffled in the face of danger. I do not know how they felt but I know what my feelings were. For a moment my blood was up, non-violence was almost forgotten — but for a moment only. The thought of the great leader, who by God''s goodness has been sent to lead us to victory, came to me, and I saw the kisans seated and standing near me, less excited, more peaceful than I was — and the moment of weakness passed, I spoke to them in all humility on non-violence — I needed the lesson more than they — and they heeded me and peacefully dispersed.''","analysis":["Nehru admits his own moment of weakness — \"my blood was up, non-violence was almost forgotten\"","The peasants (kisans) were calmer and more disciplined than the educated Nehru himself","Gandhi''s influence is clear — the thought of \"the great leader\" restored Nehru''s commitment to non-violence","Shows the tension between anger at British violence and the commitment to non-violence","The peasants'' discipline under fire demonstrates the deep impact of satyagraha on ordinary people","Exam tip: This source is used in source-based questions about the discipline of non-violence and the peasant movement"]},{"id":"ch2-source-c","label":"Source C","author":"Indian National Congress","title":"The Independence Day Pledge, 26 January 1930","year":"1930","sectionId":"s3","text":"''We believe that it is the inalienable right of the Indian people, as of any other people, to have freedom and to enjoy the fruits of their toil and have the necessities of life, so that they may have full opportunities of growth. We believe also that if any government deprives a people of these rights and oppresses them, the people have a further right to alter it or to abolish it. The British Government in India has not only deprived the Indian people of their freedom but has based itself on the exploitation of the masses, and has ruined India economically, politically, culturally, and spiritually. We believe, therefore, that India must sever the British connection and attain Purna Swaraj or Complete Independence.''","analysis":["The Pledge declares freedom as an \"inalienable right\" — echoing the language of the American and French Revolutions","It asserts the right of people to overthrow oppressive government — a radical claim against British sovereignty","Lists four dimensions of British damage: economic, political, cultural, and spiritual","The demand is clear and uncompromising: \"sever the British connection\" — complete independence, not dominion status","This was drafted after the Lahore Congress (December 1929) under Jawaharlal Nehru''s presidency","Exam tip: This is the most important source for understanding the demand for Purna Swaraj. CBSE asks about the content and significance of this pledge."]},{"id":"ch2-source-d","label":"Source D","author":"Muhammad Iqbal","title":"Presidential Address to the Muslim League","year":"1930","sectionId":"s3","text":"''I have no hesitation in declaring that if the principle that the Indian Muslim is entitled to full and free development on the lines of his own culture and tradition in his own Indian home-lands is recognised as the basis of a permanent communal settlement, he will be ready to stake his all for the freedom of India. The principle that each group is entitled to free development on its own lines is not inspired by any feeling of narrow communalism ...\n\nCommunalism in its higher aspect, then, is indispensable to the formation of a harmonious whole in a country like India ... The principle of European democracy cannot be applied to India without recognising the fact of communal groups. The Muslim demand for the creation of a Muslim India within India is, therefore, perfectly justified ...\n\nThe Hindu thinks that separate electorates are contrary to the spirit of true nationalism, because he understands the word \"nation\" to mean a kind of universal amalgamation in which no communal entity ought to retain its private individuality. Such a state of things, however, does not exist. India is a land of racial and religious variety ...''","analysis":["Iqbal argues that Indian democracy must RECOGNISE communal groups, not pretend they don''t exist","He demands that Muslims have \"full and free development\" within their own cultural framework","He rejects the idea of universal amalgamation — says India is a land of \"racial and religious variety\"","The demand for \"a Muslim India within India\" is significant — it foreshadowed the later Pakistan demand","He argues communalism in its \"higher aspect\" is not narrow but essential for harmony in a diverse country","He challenges the Hindu definition of \"nation\" as one undifferentiated whole — says this ignores reality","Exam tip: CBSE asks \"What was Iqbal''s idea of communalism?\" — this source is essential for understanding Muslim political concerns in the 1930s"]},{"id":"ch2-source-e","label":"Source E","author":"Tarinicharan Chattopadhyay","title":"Bharatbarsher Itihas (The History of Bharatbarsh)","year":"1858","sectionId":"s4","text":"''In earlier times, foreign travellers in India marvelled at the courage, truthfulness and modesty of the people of the Arya vamsa; now they remark mainly on the absence of those qualities. In those days Hindus would set out on conquest and hoist their flags in Tartar, China and other countries; now a few soldiers from a tiny island far away are lording it over the land of India.''","analysis":["This is an example of nationalist history-writing — reinterpreting India''s past to inspire pride","Chattopadhyay contrasts India''s \"glorious past\" (courage, conquest) with its colonised present","The message: Indians were once great — colonialism is an aberration that must be overthrown","But notice: the \"past\" being glorified is specifically Hindu — \"Arya vamsa\", \"Hindus would set out on conquest\"","This kind of history-writing inspired pride but could also EXCLUDE non-Hindu communities","Exam tip: This source illustrates both the power and the limitation of cultural nationalism — it builds pride but can be exclusionary"]}],"keyPeople":[{"id":"ch2-person-gandhi","name":"Mahatma Gandhi","years":"1869–1948","nationality":"Indian","role":"Leader of the Indian national movement; developed satyagraha as a method of non-violent resistance","sectionId":"s1","keyFacts":["Returned to India from South Africa in January 1915","Developed satyagraha — truth-force, not passive resistance — as a weapon against injustice","Led early satyagrahas: Champaran (1917), Ahmedabad (1918), Kheda (1918)","Linked Khilafat and Non-Cooperation movements to unite Hindus and Muslims","Called off Non-Cooperation after Chauri Chaura violence (1922) — non-violence was a moral principle","Led the Salt March from Sabarmati to Dandi (1930) — launched Civil Disobedience Movement","Wrote Hind Swaraj (1909) arguing British rule survived only through Indian cooperation"],"examRelevance":"high"},{"id":"ch2-person-nehru","name":"Jawaharlal Nehru","years":"1889–1964","nationality":"Indian","role":"Congress leader; presided over the Lahore Congress (1929) which demanded Purna Swaraj","sectionId":"s3","keyFacts":["Visited Awadh villages in June 1920 — helped set up Oudh Kisan Sabha","Represented the younger, more radical wing of Congress demanding full independence","Presided over Lahore Congress (December 1929) which formally demanded Purna Swaraj","26 January 1930 declared Independence Day under his leadership","Along with Subhas Chandra Bose, pushed for mass agitation over council politics"],"examRelevance":"high"},{"id":"ch2-person-ambedkar","name":"Dr. B.R. Ambedkar","years":"1891–1956","nationality":"Indian","role":"Leader of the Dalit movement; organised Depressed Classes Association; clashed with Gandhi over separate electorates","sectionId":"s3","keyFacts":["Organised dalits into the Depressed Classes Association (1930)","Demanded separate electorates for dalits at the Second Round Table Conference","When Britain accepted his demand, Gandhi began a fast unto death","Agreed to the Poona Pact (1932): reserved seats but within joint electorates","Believed political empowerment was the path to solving social disabilities","Was critical of the Congress — felt it ignored dalit concerns to avoid offending upper castes"],"examRelevance":"high"},{"id":"ch2-person-ali-brothers","name":"Muhammad Ali and Shaukat Ali","nationality":"Indian","role":"Muslim leaders who led the Khilafat movement and allied with Gandhi for Non-Cooperation","sectionId":"s1","keyFacts":["Young Muslim leaders outraged by the treatment of Ottoman Turkey after WWI","Formed the Khilafat Committee in Bombay (March 1919)","Approached Gandhi for united mass action — linking Khilafat with Indian nationalism","Toured India with Gandhi in summer 1920 to build support for Non-Cooperation"],"examRelevance":"medium"},{"id":"ch2-person-baba-ramchandra","name":"Baba Ramchandra","nationality":"Indian","role":"Led the peasant movement in Awadh against talukdars and landlords","sectionId":"s2","keyFacts":["A sanyasi who had earlier been an indentured labourer in Fiji","Led the peasant movement in Awadh (UP) against talukdars demanding exorbitant rents","Demanded reduction of revenue, abolition of begar, and social boycott of oppressive landlords","Movement spread beyond Congress control — houses of talukdars attacked, grain hoards seized"],"examRelevance":"medium"},{"id":"ch2-person-raju","name":"Alluri Sitaram Raju","nationality":"Indian","role":"Led militant guerrilla movement in the Gudem Hills of Andhra Pradesh","sectionId":"s2","keyFacts":["Led tribal revolt in the Gudem Hills against British restrictions on forest access","Claimed special powers — healing, surviving bullets — rebels proclaimed him an incarnation of God","Wore khadi and invoked Gandhi, but used guerrilla warfare — attacked police stations, killed officials","Inspired by Non-Cooperation but used violent methods Congress could not approve","Captured and executed in 1924 — became a folk hero over time"],"examRelevance":"medium"},{"id":"ch2-person-bhagat-singh","name":"Bhagat Singh","years":"1907–1931","nationality":"Indian","role":"Revolutionary; co-founder of HSRA; symbol of armed resistance to British rule","sectionId":"s3","keyFacts":["Co-founded the Hindustan Socialist Republican Army (HSRA) in 1928","With Batukeswar Dutta, threw a bomb in the Legislative Assembly (April 1929)","Said he did not wish to glorify \"the cult of the bomb and pistol\" but wanted a revolution in society","His slogan \"Inquilab Zindabad!\" (Long Live Revolution) became iconic","Tried and executed by the British at age 23","Represented the revolutionary alternative to Gandhi''s non-violence"],"examRelevance":"medium"},{"id":"ch2-person-jinnah","name":"Muhammad Ali Jinnah","nationality":"Indian (later Pakistani)","role":"Leader of the Muslim League; demanded safeguards for Muslim minority","sectionId":"s3","keyFacts":["Was willing to give up separate electorates if Muslims got reserved seats in Central Assembly and proportional representation in Muslim-majority provinces","Negotiations failed at the 1928 All Parties Conference when Hindu Mahasabha opposed compromise","Growing alienation of Muslims from Congress — feared domination by Hindu majority","His demands foreshadowed the later demand for a separate Muslim state (Pakistan)"],"examRelevance":"medium"},{"id":"ch2-person-dyer","name":"General Dyer","nationality":"British","role":"Ordered the Jallianwala Bagh massacre on 13 April 1919","sectionId":"s1","keyFacts":["Imposed martial law in Amritsar after violence on 10 April 1919","On 13 April 1919, entered Jallianwala Bagh, blocked the exits, and ordered troops to fire","Firing continued for approximately ten minutes on the unarmed crowd","His stated aim: \"to produce a moral effect\" — to create terror and awe among satyagrahis","Ordered \"crawling orders\" — forcing Indians to crawl on the streets"],"examRelevance":"high"},{"id":"ch2-person-tagore-abanindranath","name":"Abanindranath Tagore","years":"1871–1951","nationality":"Indian","role":"Painted the famous image of Bharat Mata (1905) as an ascetic, spiritual figure","sectionId":"s4","keyFacts":["Nephew of Rabindranath Tagore","Painted Bharat Mata in 1905 during the Swadeshi movement","Portrayed the motherland as a calm, composed, divine, ascetic figure — dispensing learning, food, and clothing","Tried to develop a style of painting that could be seen as truly Indian","His image of Bharat Mata is contrasted with later more aggressive versions showing power symbols"],"examRelevance":"high"},{"id":"ch2-person-bankim","name":"Bankim Chandra Chattopadhyay","years":"1838–1894","nationality":"Indian","role":"Created the hymn Vande Mataram and the image of Bharat Mata through his novel Anandamath","sectionId":"s4","keyFacts":["Wrote Vande Mataram (\"I bow to thee, Mother\") in the 1870s as a hymn to the motherland","Included it in his novel Anandamath — it became widely sung during the Swadeshi movement in Bengal","First to create the literary image of India as a mother figure (Bharat Mata)","His work inspired later visual representations by Abanindranath Tagore and others"],"examRelevance":"medium"},{"id":"ch2-person-ghaffar-khan","name":"Abdul Ghaffar Khan","nationality":"Indian (Pashtun)","role":"Known as \"Frontier Gandhi\"; led non-violent resistance in the North-West Frontier Province","sectionId":"s3","keyFacts":["A devout disciple of Mahatma Gandhi","When arrested in Peshawar (April 1930), angry crowds demonstrated in the streets facing armoured cars and police firing","His arrest and the Peshawar events showed the spread of Civil Disobedience to the frontier regions"],"examRelevance":"low"},{"id":"ch2-person-lajpat-rai","name":"Lala Lajpat Rai","years":"1865–1928","nationality":"Indian","role":"Prominent Congress leader; died from injuries sustained during protest against Simon Commission","sectionId":"s3","keyFacts":["Assaulted by British police during a peaceful demonstration against the Simon Commission","Succumbed to injuries inflicted during the demonstration","His death intensified Indian anger against the British and the Simon Commission"],"examRelevance":"medium"},{"id":"ch2-person-vallabhbhai-patel","name":"Vallabhbhai Patel","nationality":"Indian","role":"Led the Bardoli Satyagraha (1928) against revenue enhancement; became known as \"Sardar\"","sectionId":"s2","keyFacts":["Led the peasant movement in Bardoli, Gujarat (1928) against enhancement of land revenue","Known as the Bardoli Satyagraha — it was a major success","Earned the title \"Sardar\" (leader) from the people of Bardoli","The struggle was widely publicised and generated immense sympathy across India"],"examRelevance":"low"}],"flashcards":[{"id":"ch2-fc-001","front":"When did Gandhi return to India from South Africa?","back":"January 1915","sectionId":"s1","tags":["key-date","key-person","exam-critical"]},{"id":"ch2-fc-002","front":"What is Satyagraha?","back":"Satya (truth) + Agraha (insistence) = insistence on truth. A method of non-violent mass agitation. Gandhi was clear it was NOT passive resistance: \"This power can be used only by the strong.\"","sectionId":"s1","tags":["vocabulary","key-concept","exam-critical"]},{"id":"ch2-fc-003","front":"What was Gandhi''s first satyagraha in India, and when?","back":"Champaran Satyagraha, 1917 (Bihar). Indigo farmers were forced to grow indigo, which destroyed soil fertility. Gandhi organised resistance and won tax redemption.","sectionId":"s1","tags":["key-date","key-concept","exam-critical"]},{"id":"ch2-fc-004","front":"What was the Ahmedabad Mill Strike (1918)?","back":"Cotton mill workers demanded fair wages. Gandhi supported them with satyagraha. Workers won their demands.","sectionId":"s1","tags":["key-date","key-concept"]},{"id":"ch2-fc-005","front":"What was the Kheda Satyagraha (1918)?","back":"Crops failed in Gujarat. Peasants could not pay revenue. Gandhi demanded tax relief from the British. The government agreed.","sectionId":"s1","tags":["key-date","key-concept"]},{"id":"ch2-fc-006","front":"What was the common pattern in Gandhi''s three early satyagrahas (Champaran, Ahmedabad, Kheda)?","back":"All three were about economic exploitation, all were regional (one district at a time), and all were short-lived. They proved satyagraha worked but were not yet a national movement.","sectionId":"s1","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-007","front":"How did World War I affect India?","back":"Taxes doubled, prices doubled, forced recruitment from villages, crop failures (1918-21), and the influenza epidemic killed 12-13 million people. Indians hoped peace would bring relief but were disappointed.","sectionId":"s1","tags":["key-concept"]},{"id":"ch2-fc-008","front":"What was the Rowlatt Act (1919)?","back":"Passed in February 1919, it gave the British government the power to arrest anyone, detain without trial for two years, with no evidence needed. Even Indian members of the Imperial Legislative Council opposed it unanimously, but the British ignored them.","sectionId":"s1","tags":["key-concept","vocabulary","exam-critical"]},{"id":"ch2-fc-009","front":"How did Gandhi respond to the Rowlatt Act?","back":"He called a nationwide hartal (strike) on 6 April 1919. Rallies, strikes, and shop closures spread across India.","sectionId":"s1","tags":["key-date","key-concept"]},{"id":"ch2-fc-010","front":"What happened at Jallianwala Bagh on 13 April 1919?","back":"A large crowd gathered in the enclosed ground of Jallianwala Bagh, Amritsar. Many were villagers attending the Baisakhi fair, unaware of martial law. General Dyer blocked the exits, gave no warning, and ordered troops to fire for ten minutes on unarmed men, women, and children. Hundreds died.","sectionId":"s1","tags":["key-date","key-person","exam-critical"]},{"id":"ch2-fc-011","front":"Who was General Dyer?","back":"The British military officer who ordered the Jallianwala Bagh massacre. He later stated his goal was \"to produce a moral effect\" on the Indians.","sectionId":"s1","tags":["key-person","exam-critical"]},{"id":"ch2-fc-012","front":"What were the \"crawling orders\" shown in Fig 3?","back":"After the Jallianwala Bagh massacre, satyagrahis in Amritsar were forced to crawl on the ground and do salaam to British officers as acts of humiliation.","sectionId":"s1","tags":["figure","exam-critical"]},{"id":"ch2-fc-013","front":"What was the aftermath of the Jallianwala Bagh massacre?","back":"North India erupted with strikes, clashes, and attacks on government buildings. British repression was brutal. Seeing the violence spread, Gandhi called off the Rowlatt satyagraha.","sectionId":"s1","tags":["key-concept"]},{"id":"ch2-fc-014","front":"What was the Khilafat issue?","back":"After WWI, rumours spread that the Ottoman Emperor (the Khalifa, spiritual head of Islam) would be stripped of his powers by a harsh peace treaty. Muslims worldwide were outraged. A Khilafat Committee formed in Bombay in March 1919.","sectionId":"s1","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-015","front":"Who were the Ali brothers?","back":"Muhammad Ali and Shaukat Ali — young Muslim leaders of the Khilafat movement who approached Gandhi to join forces against the British.","sectionId":"s1","tags":["key-person"]},{"id":"ch2-fc-016","front":"How did the Khilafat issue help Hindu-Muslim unity?","back":"Gandhi saw the Khilafat issue as an opportunity: by supporting the Muslim cause, he could get Muslim support for the Congress. At the Calcutta Congress (September 1920), he convinced leaders to launch Non-Cooperation in support of BOTH Khilafat and Swaraj.","sectionId":"s1","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-017","front":"What did Gandhi argue in Hind Swaraj (1909)?","back":"British rule survives only because Indians cooperate with it. If Indians refuse to cooperate, the empire would collapse within a year and swaraj would come.","sectionId":"s1","tags":["key-concept","source"]},{"id":"ch2-fc-018","front":"What is Swaraj?","back":"Swa (self) + Raj (rule) = self-rule. Different groups interpreted it differently: middle class wanted constitutions, peasants wanted no rent, tribals wanted forests, workers wanted fair wages, Dalits wanted dignity.","sectionId":"s1","tags":["vocabulary","key-concept","exam-critical"]},{"id":"ch2-fc-019","front":"What were the stages of the Non-Cooperation programme?","back":"(1) Surrender government titles (2) Boycott civil services, army, police, courts, legislative councils, schools (3) Boycott foreign goods (4) If government uses repression, launch full civil disobedience.","sectionId":"s1","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-020","front":"What happened at the Nagpur Congress (December 1920)?","back":"After intense debate, Congress formally adopted the Non-Cooperation programme. The movement would begin in January 1921. Gandhi promised the British would leave within a year.","sectionId":"s1","tags":["key-date","key-concept"]},{"id":"ch2-fc-021","front":"What was historically significant about the Non-Cooperation-Khilafat Movement?","back":"(1) First truly national movement, not regional (2) Multiple social groups united (3) Hindu-Muslim alliance achieved for the first time (4) Non-violent method used as a principle, not just a tactic.","sectionId":"s1","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-022","front":"What is a hartal?","back":"A mass strike where shops are closed, work is stopped, and rallies are held as a form of protest. Gandhi called a nationwide hartal on 6 April 1919 against the Rowlatt Act.","sectionId":"s1","tags":["vocabulary"]},{"id":"ch2-fc-023","front":"What is \"forced recruitment\"?","back":"The colonial state forced villagers to join the army against their will. They were not volunteers but conscripts. This was a major grievance during WWI.","sectionId":"s1","tags":["vocabulary"]},{"id":"ch2-fc-024","front":"What did Gandhi mean by saying satyagraha was NOT passive resistance?","back":"Gandhi said satyagraha was a weapon of the strong, not the weak. It required active courage to face violence without retaliating — it was not about passively accepting injustice.","sectionId":"s1","tags":["key-concept","source"]},{"id":"ch2-fc-025","front":"Why did the Non-Cooperation Movement slow down in the towns?","back":"Three reasons: (1) Khadi was expensive — poor people could not afford it (2) Alternative Indian institutions (schools, courts) were slow to set up (3) Students and lawyers drifted back to government institutions without alternatives.","sectionId":"s2","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-026","front":"By how much did foreign cloth imports fall during Non-Cooperation?","back":"Imports of foreign cloth halved — from Rs 102 crore to Rs 57 crore.","sectionId":"s2","tags":["key-concept"]},{"id":"ch2-fc-027","front":"What is a boycott?","back":"The refusal to deal with, participate in, or buy something. Named after Captain Charles Boycott, an Irish land agent who was ostracised by his community in 1880.","sectionId":"s2","tags":["vocabulary","exam-critical"]},{"id":"ch2-fc-028","front":"Who was Baba Ramchandra and what did he do?","back":"A sanyasi who had been an indentured labourer in Fiji. He led the peasant movement in Awadh (UP) against talukdars who imposed exorbitant rents, begar (forced unpaid labour), and gave no security of tenure.","sectionId":"s2","tags":["key-person","exam-critical"]},{"id":"ch2-fc-029","front":"What is begar?","back":"Labour that villagers were forced to contribute without any payment. A form of exploitation by landlords, especially prevalent in Awadh.","sectionId":"s2","tags":["vocabulary","exam-critical"]},{"id":"ch2-fc-030","front":"What was the Oudh Kisan Sabha?","back":"A peasant organisation set up in October 1920 by Jawaharlal Nehru, Baba Ramchandra, and others. It established over 300 branches within a month. The peasant movement was ready BEFORE Non-Cooperation formally began.","sectionId":"s2","tags":["key-concept"]},{"id":"ch2-fc-031","front":"How did peasants in Awadh go beyond the Congress programme?","back":"They attacked houses of talukdars, looted bazaars, and took over grain hoards. Local leaders told peasants that Gandhi had declared no more taxes and that land would be redistributed — actions Gandhi never authorised.","sectionId":"s2","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-032","front":"What did Swaraj mean to the peasants of Awadh?","back":"An end to exorbitant rents, begar (forced unpaid labour), and oppression by talukdars. For them, Swaraj meant freedom from landlord exploitation, not constitutions or councils.","sectionId":"s2","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-033","front":"Who was Alluri Sitaram Raju?","back":"Leader of the tribal revolt in the Gudem Hills (Andhra Pradesh). He claimed healing powers, wore khadi, invoked Gandhi, and supported Non-Cooperation — but used guerrilla warfare. He attacked police stations and killed British officials. Captured and executed in 1924. He became a folk hero.","sectionId":"s2","tags":["key-person","exam-critical"]},{"id":"ch2-fc-034","front":"Why did tribals in the Gudem Hills revolt?","back":"The colonial government closed forests — no grazing, no firewood. Then demanded begar for road building. The hill people revolted against these restrictions on their traditional livelihood.","sectionId":"s2","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-035","front":"What did Swaraj mean to tribals?","back":"Freedom to access forests for grazing and firewood, and freedom from forced labour (begar). Their idea of Swaraj was tied to their forest-based livelihood.","sectionId":"s2","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-036","front":"What was the contradiction in Alluri Sitaram Raju''s approach?","back":"He invoked Gandhi and wore khadi (symbols of non-violence) but used guerrilla warfare and violence. He believed India could only be freed through force, not non-violence.","sectionId":"s2","tags":["key-concept"]},{"id":"ch2-fc-037","front":"What was the Inland Emigration Act of 1859?","back":"A law that prohibited plantation workers in Assam from leaving tea gardens without permission. They were essentially trapped — unable to move freely.","sectionId":"s2","tags":["key-concept"]},{"id":"ch2-fc-038","front":"What did Swaraj mean to Assam plantation workers?","back":"The basic right to move freely — to leave the plantations and go home. They believed \"Gandhi Raj\" was coming — a time when everyone would get land and all suffering would end.","sectionId":"s2","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-039","front":"What happened to the Assam plantation workers who left during Non-Cooperation?","back":"Thousands left the plantations and headed home, but they never reached their destinations. Stranded by a railway and steamer strike, they were caught by police and brutally beaten.","sectionId":"s2","tags":["key-concept"]},{"id":"ch2-fc-040","front":"What is a picket?","back":"A form of demonstration where people block the entrance to a shop, factory, or office as a form of protest. Used heavily during the boycott of foreign goods and liquor.","sectionId":"s2","tags":["vocabulary"]},{"id":"ch2-fc-041","front":"What happened at Chauri Chaura on 4 February 1922?","back":"A peaceful demonstration turned into a clash with police. The crowd set fire to the police station. 22 policemen were killed.","sectionId":"s2","tags":["key-date","key-concept","exam-critical"]},{"id":"ch2-fc-042","front":"Why did Gandhi call off the Non-Cooperation Movement after Chauri Chaura?","back":"Gandhi believed a movement that kills is no different from the empire it fights. Non-violence was not just a tactic for him — it was the soul of the struggle. He called off the entire movement despite it being at its peak.","sectionId":"s2","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-043","front":"Why were other Congress leaders furious when Gandhi called off Non-Cooperation?","back":"The movement was at its peak, the British were rattled, and they felt pulling the plug was a mistake. But Gandhi was firm on the principle of non-violence.","sectionId":"s2","tags":["key-concept"]},{"id":"ch2-fc-044","front":"What was the significance of Non-Cooperation despite its failure?","back":"(1) First truly national movement (2) British economy hit — foreign cloth imports halved (3) Working class awakened — peasants, tribals, workers participated for the first time (4) Hindu-Muslim unity achieved briefly (5) Inspired the next generation: Bhagat Singh, Bose, Nehru.","sectionId":"s2","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-045","front":"What did Swaraj mean to the middle class in towns?","back":"Constitutions, representative government, legislative councils, and an end to British bureaucratic control. They participated by boycotting schools, courts, and councils.","sectionId":"s2","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-046","front":"What pattern did all groups (towns, countryside, plantations) show during Non-Cooperation?","back":"Each group interpreted the movement through their own needs: middle class → institutions, peasants → land/rent, tribals → forests, workers → freedom to move. The movement grew but also grew out of control as each group exceeded Congress''s intended programme.","sectionId":"s2","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-047","front":"What did Swaraj mean to industrial workers?","back":"Fair wages, better working conditions, and shorter hours. Workers participated in strikes and boycotts but their specific demands were often not addressed by Congress.","sectionId":"s2","tags":["key-concept"]},{"id":"ch2-fc-048","front":"How did Nehru describe the peasants at Rae Bareli (Source B)?","back":"\"They behaved as brave men, calm and unruffled in the face of danger... For a moment my blood was up, non-violence was almost forgotten — but for a moment only.\"","sectionId":"s2","tags":["source"]},{"id":"ch2-fc-049","front":"What actions did the middle class take during Non-Cooperation?","back":"Thousands of students left government schools, teachers resigned, lawyers gave up practice, council elections were boycotted in most provinces, foreign goods were boycotted, and foreign cloth was burnt in bonfires.","sectionId":"s2","tags":["key-concept"]},{"id":"ch2-fc-050","front":"When did Jawaharlal Nehru visit the villages of Awadh?","back":"June 1920 — his visits helped connect the peasant movement with Congress and led to the formation of the Oudh Kisan Sabha.","sectionId":"s2","tags":["key-date","key-person"]},{"id":"ch2-fc-051","front":"What was the Swaraj Party?","back":"Formed by C.R. Das and Motilal Nehru after Non-Cooperation was called off. They wanted to enter provincial councils and argue for reform from within the system.","sectionId":"s3","tags":["key-concept","key-person"]},{"id":"ch2-fc-052","front":"Who founded the Hindustan Socialist Republican Army (HSRA) and when?","back":"Founded in 1928. Key leaders: Bhagat Singh, Jatin Das, and Ajoy Ghosh. They targeted symbols of British power.","sectionId":"s3","tags":["key-person","key-date","exam-critical"]},{"id":"ch2-fc-053","front":"What did Bhagat Singh do in April 1929?","back":"Bhagat Singh and Batukeswar Dutta threw a bomb in the Central Legislative Assembly. During his trial, Bhagat Singh said he did not wish to glorify \"the cult of the bomb and pistol\" but wanted a revolution in society. His slogan: \"Inquilab Zindabad!\"","sectionId":"s3","tags":["key-person","key-date","exam-critical"]},{"id":"ch2-fc-054","front":"How old was Bhagat Singh when he was executed?","back":"23 years old","sectionId":"s3","tags":["key-person","exam-critical"]},{"id":"ch2-fc-055","front":"What was the Simon Commission (1928)?","back":"A commission sent by Britain to review India''s constitutional system. It had NO Indian members — all British. Indians were outraged, and \"Go Back Simon!\" united Congress and Muslim League in protest.","sectionId":"s3","tags":["key-date","key-concept","exam-critical"]},{"id":"ch2-fc-056","front":"What happened to Lala Lajpat Rai during the Simon Commission protests?","back":"He was beaten by police during a protest against the Simon Commission. He later died from the injuries sustained.","sectionId":"s3","tags":["key-person"]},{"id":"ch2-fc-057","front":"What was decided at the Lahore Congress (December 1929)?","back":"Under Jawaharlal Nehru''s presidency, Congress made the historic declaration of Purna Swaraj (complete independence). 26 January 1930 was declared Independence Day.","sectionId":"s3","tags":["key-date","key-concept","exam-critical"]},{"id":"ch2-fc-058","front":"What is Purna Swaraj?","back":"Complete independence — not just \"dominion status\" within the British Empire. Declared at the Lahore Congress in December 1929. It meant a complete severing of the British connection.","sectionId":"s3","tags":["vocabulary","key-concept","exam-critical"]},{"id":"ch2-fc-059","front":"Why did Gandhi choose salt as the symbol for Civil Disobedience?","back":"Salt was consumed by the rich AND the poor, by Hindu and Muslim, Brahmin and Dalit, man and woman — everyone. And the British taxed it. By choosing salt, Gandhi turned every kitchen in India into a site of resistance.","sectionId":"s3","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-060","front":"What did Gandhi''s letter to Viceroy Irwin (31 January 1930) demand?","back":"Eleven demands including: abolish salt tax, reduce military spending, release political prisoners. It was an ultimatum: if not met by 11 March, Congress would launch civil disobedience. Irwin ignored the letter.","sectionId":"s3","tags":["key-date","key-concept"]},{"id":"ch2-fc-061","front":"Describe the Salt March (Dandi March) — date, route, and details.","back":"12 March 1930: Gandhi left Sabarmati Ashram with 78 volunteers. Destination: Dandi, Gujarat. Distance: 240 miles. They walked about 10 miles a day. At every village, Gandhi spoke about swaraj. Thousands joined along the way.","sectionId":"s3","tags":["key-date","key-concept","exam-critical"]},{"id":"ch2-fc-062","front":"What happened on 6 April 1930 at Dandi?","back":"Gandhi reached Dandi, walked to the shore, and picked up a handful of natural salt — breaking the law. The Civil Disobedience Movement officially began.","sectionId":"s3","tags":["key-date","exam-critical"]},{"id":"ch2-fc-063","front":"How was Civil Disobedience DIFFERENT from Non-Cooperation?","back":"In Non-Cooperation (1921), people refused to cooperate — they boycotted institutions. In Civil Disobedience (1930), people actively BROKE THE LAW — manufacturing salt, refusing to pay revenue, violating forest laws. It was a direct defiance of British authority.","sectionId":"s3","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-064","front":"How did Civil Disobedience spread across India?","back":"People manufactured salt, boycotted foreign cloth, refused to pay revenue, and violated forest laws. About 100,000 people were arrested. Abdul Ghaffar Khan was arrested in Peshawar; Gandhi himself was arrested in May 1930.","sectionId":"s3","tags":["key-concept"]},{"id":"ch2-fc-065","front":"Who was Abdul Ghaffar Khan?","back":"A leader from the North-West Frontier Province (Peshawar) who was arrested during the Civil Disobedience Movement. His arrest triggered angry protests in the region.","sectionId":"s3","tags":["key-person"]},{"id":"ch2-fc-066","front":"What was the Gandhi-Irwin Pact (March 1931)?","back":"Gandhi agreed to call off Civil Disobedience and attend the Round Table Conference in London. In return, the British released political prisoners.","sectionId":"s3","tags":["key-date","key-concept","exam-critical"]},{"id":"ch2-fc-067","front":"What happened at the Round Table Conference?","back":"Gandhi went to London in December 1931, but negotiations broke down. Back in India, leaders like Ghaffar Khan and Nehru were in jail, Congress was declared illegal. Gandhi relaunched CDM, but it was weaker and fizzled out by 1934.","sectionId":"s3","tags":["key-concept"]},{"id":"ch2-fc-068","front":"How did rich peasants (Patidars, Jats) participate in CDM?","back":"Hit hard by the Depression — commercial crops became worthless and they could not pay revenue. They enthusiastically joined CDM. But they were deeply disappointed when Gandhi called it off in 1931 WITHOUT reducing revenue. Many refused to rejoin in 1932.","sectionId":"s3","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-069","front":"Why did poor peasants not get Congress support?","back":"Poor peasants (small tenants, sharecroppers) wanted rent relief from LANDLORDS, not just lower government revenue. Congress would not support \"no rent\" campaigns because it feared alienating rich peasants and zamindars. Many poor peasants turned to Socialists and Communists instead.","sectionId":"s3","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-070","front":"How did the Indian business class participate in CDM?","back":"Industrialists like Birla and Thakurdas (and FICCI) wanted protection from foreign imports and favourable exchange rates. They funded CDM and refused to buy/sell imported goods. But after the Round Table Conference failure, they feared prolonged disruption and turned cautious.","sectionId":"s3","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-071","front":"Why did industrial workers have an uneasy relationship with Congress?","back":"Workers joined boycotts and rallies, but Congress would not include worker demands (fair wages, better conditions) in its programme because it feared alienating industrialists who funded the movement.","sectionId":"s3","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-072","front":"How did women participate in the Civil Disobedience Movement?","back":"Thousands of women joined salt marches, picketed liquor and foreign cloth shops, manufactured salt, and went to jail. For many, it was the first time they had left home for a public cause.","sectionId":"s3","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-073","front":"What was Gandhi''s view on women''s role in the movement?","back":"Gandhi saw women''s role as largely symbolic — \"good mothers and good wives.\" Congress was reluctant to give women real positions of authority despite their massive participation.","sectionId":"s3","tags":["key-concept"]},{"id":"ch2-fc-074","front":"What was the Independence Day Pledge (Source C)?","back":"\"We believe that it is the inalienable right of the Indian people... to have freedom and to enjoy the fruits of their toil... India must sever the British connection and attain Purna Swaraj or Complete Independence.\" (26 January 1930)","sectionId":"s3","tags":["source","exam-critical"]},{"id":"ch2-fc-075","front":"What effect did the worldwide Great Depression have on India?","back":"Agricultural prices crashed from 1926 and collapsed after 1930. Peasants could not sell crops or pay revenue. The countryside was desperate — creating conditions ripe for another mass movement.","sectionId":"s3","tags":["key-concept"]},{"id":"ch2-fc-076","front":"How many volunteers started the Salt March with Gandhi?","back":"78 trusted volunteers left Sabarmati Ashram on 12 March 1930. Thousands more joined along the 240-mile route to Dandi.","sectionId":"s3","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-077","front":"Who was Dr. B.R. Ambedkar and what did he demand?","back":"Leader of the Dalit movement. He organised Dalits into the Depressed Classes Association (1930). He demanded separate electorates for Dalits at the Second Round Table Conference, arguing they needed independent political representation.","sectionId":"s4","tags":["key-person","exam-critical"]},{"id":"ch2-fc-078","front":"Why did Dalits feel excluded from the national movement?","back":"Congress had long ignored Dalit concerns to avoid offending upper-caste Hindus. The abstract concept of \"swaraj\" did not address their specific demands: reserved seats in education, separate electorates, and an end to untouchability.","sectionId":"s4","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-079","front":"What was the Poona Pact (September 1932)?","back":"When Britain accepted Ambedkar''s demand for separate electorates for Dalits, Gandhi began a fast unto death. Ambedkar agreed to the Poona Pact: Dalits got reserved seats but within joint electorates (not separate ones).","sectionId":"s4","tags":["key-date","key-concept","exam-critical"]},{"id":"ch2-fc-080","front":"Why did Gandhi oppose separate electorates for Dalits?","back":"He believed separate electorates would permanently divide Hindu society and slow the integration of Dalits into the mainstream. He felt untouchability should be fought through social reform, not political separation.","sectionId":"s4","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-081","front":"Why did many Muslims stay away from the Civil Disobedience Movement?","back":"After the Khilafat movement collapsed, Muslims felt alienated from Congress. Congress became associated with Hindu groups like the Hindu Mahasabha. Communal riots deepened the divide. Jinnah''s demand for reserved Muslim seats was rejected at the 1928 All Parties Conference.","sectionId":"s4","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-082","front":"What did Muhammad Ali Jinnah demand at the 1928 All Parties Conference?","back":"Reserved seats for Muslims in the Central Legislature. His demand was rejected, which deepened Muslim distrust of Congress.","sectionId":"s4","tags":["key-person","key-concept"]},{"id":"ch2-fc-083","front":"What did Muhammad Iqbal say in 1930 (Source D)?","back":"\"I have no hesitation in declaring that if the principle that the Indian Muslim is entitled to full and free development... is recognised as the basis of a permanent communal settlement, he will be ready to stake his all for the freedom of India.\"","sectionId":"s4","tags":["source","key-person","exam-critical"]},{"id":"ch2-fc-084","front":"Who wrote Vande Mataram and in which novel?","back":"Bankim Chandra Chattopadhyay wrote Vande Mataram in the 1870s. It was included in his novel Anandamath. During the Swadeshi movement in Bengal, it became an anthem of resistance.","sectionId":"s4","tags":["key-concept","key-person"]},{"id":"ch2-fc-085","front":"Describe Abanindranath Tagore''s painting of Bharat Mata (1905).","back":"She is portrayed as an ascetic, calm, composed, spiritual figure. She holds symbols of learning, food, and clothing. The mala (prayer beads) emphasises her spiritual quality. It is a serene, divine image.","sectionId":"s4","tags":["figure","exam-critical"]},{"id":"ch2-fc-086","front":"How was the later image of Bharat Mata different from Tagore''s version?","back":"The later image shows Bharat Mata with a trishul (trident), standing beside a lion and an elephant — symbols of POWER and AUTHORITY. Very different from Tagore''s calm, spiritual figure. It was more militant and aggressive.","sectionId":"s4","tags":["figure","exam-critical"]},{"id":"ch2-fc-087","front":"Why was the image of Bharat Mata problematic for national unity?","back":"Bharat Mata draws from Hindu iconography. Vande Mataram is from a Hindu novel. The lion, trident, and prayer beads are Hindu symbols. If the idea of the nation is wrapped in one religion''s imagery, Muslims, Christians, and Dalits may not see themselves in that vision.","sectionId":"s4","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-088","front":"How did Indian nationalists use folklore, similar to the Grimm Brothers in Europe?","back":"In Bengal, Rabindranath Tagore collected ballads, nursery rhymes, and myths. In Madras, Natesa Sastri published a 4-volume collection of Tamil folk tales, calling folklore \"the most trustworthy manifestation of people''s real thoughts.\"","sectionId":"s4","tags":["key-concept"]},{"id":"ch2-fc-089","front":"Describe the evolution of the Indian national flag.","back":"During the Swadeshi movement (Bengal): tricolour of red, green, yellow with 8 lotuses (8 provinces) and a crescent moon (Hindus + Muslims). By 1921: Gandhi designs the Swaraj flag — red, green, white with a spinning wheel (charkha) representing self-reliance.","sectionId":"s4","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-090","front":"How did nationalists rewrite Indian history?","back":"Indians wrote about India''s \"golden age\" — great achievements in art, architecture, science, mathematics, and philosophy before colonisation. The message: Indians were never inferior; the British claim of \"civilising\" India was a lie.","sectionId":"s4","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-091","front":"What was the limitation of rewriting Indian history?","back":"The \"glorious past\" being celebrated was largely Hindu past — temples, Sanskrit, Vedic science. Muslims, Christians, and Dalits could not see themselves in that story. The tools meant to unite were inadvertently dividing.","sectionId":"s4","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-092","front":"What did Tarinicharan Chattopadhyay write (Source E)?","back":"\"In earlier times, foreign travellers in India marvelled at the courage, truthfulness and modesty of the people... now a few soldiers from a tiny island far away are lording it over the land of India.\" (1858)","sectionId":"s4","tags":["source"]},{"id":"ch2-fc-093","front":"What was the Quit India Movement (1942)?","back":"Launched by Gandhi with the slogan \"Do or Die\" after the failure of the Cripps Mission. Congress Working Committee passed the Quit India resolution on 8 August 1942 in Bombay. Mass participation by students, workers, and peasants. British took over a year to suppress it.","sectionId":"s4","tags":["key-date","key-concept"]},{"id":"ch2-fc-094","front":"Compare Bharat Mata with Germania (Chapter 1).","back":"Both are female allegories personifying the nation — same technique. But Germania''s symbols (oak, sword, eagle) are secular/political, while Bharat Mata''s symbols (trishul, mala, lion) draw from Hindu religious iconography, which excluded non-Hindu communities.","sectionId":"s4","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-095","front":"How did Gandhi''s promise from Hind Swaraj ultimately play out?","back":"Gandhi promised that if Indians refused to cooperate, British rule would collapse within a year. It did not come in 1921 or 1930. Independence came in 1947 — 27 years later — and it came with Partition, breaking the unity Gandhi had fought for.","sectionId":"s4","tags":["key-concept"]},{"id":"ch2-fc-096","front":"What was the significance of Civil Disobedience?","back":"(1) Salt March made India''s freedom struggle global news (2) British authority was directly challenged, not just boycotted (3) Women entered the public sphere in unprecedented numbers (4) But limits were real: Dalits and Muslims remained wary of Congress, foreshadowing Partition.","sectionId":"s4","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-097","front":"Timeline: List the key dates from 1915 to 1932.","back":"1915: Gandhi returns to India. 1917: Champaran. 1918: Ahmedabad & Kheda. 1919: Rowlatt Act, Jallianwala Bagh. 1920: Khilafat-NCM launched. 1921: NCM begins. 1922: Chauri Chaura, NCM called off. 1928: Simon Commission, HSRA founded. 1929: Lahore Congress, Purna Swaraj. 1930: Salt March & CDM. 1931: Gandhi-Irwin Pact. 1932: Poona Pact.","sectionId":"s1","tags":["key-date","exam-critical"]},{"id":"ch2-fc-098","front":"Compare Non-Cooperation Movement and Civil Disobedience Movement.","back":"NCM (1921-22): People REFUSED to cooperate — boycotted institutions. CDM (1930-34): People actively BROKE THE LAW — made salt, violated forest laws, refused revenue. NCM included Khilafat (Hindu-Muslim unity). CDM had weaker Muslim participation. Both called off by Gandhi before achieving swaraj.","sectionId":"s3","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-099","front":"How was Indian nationalism different from European nationalism (Chapter 1)?","back":"European nationalism was about BUILDING new nation-states from kingdoms and empires. Indian nationalism was about LIBERATING an existing nation from colonial rule. Europe eventually chose military force (Bismarck). India chose non-violence (Gandhi). European nationalism became aggressive/imperialist. Indian nationalism was born resisting imperialism.","sectionId":"s4","tags":["key-concept","exam-critical"]},{"id":"ch2-fc-100","front":"What was the Depressed Classes Association?","back":"Founded by Dr. B.R. Ambedkar in 1930 to organise Dalits and fight for their political rights, including reserved seats in education and separate electorates.","sectionId":"s4","tags":["key-concept","key-person"]}],"figures":[{"id":"ch2-fig-1","number":"1","title":"6 April 1919 — Mass Processions","year":"1919","type":"photograph","imagePath":"/images/ch2/fig-01-mass-processions.png","sectionId":"s1","examRelevance":"medium","hotspots":[{"id":"h1","label":"Dense crowd","description":"Thousands of people filling the entire street — showing the massive scale of the hartal","x":50,"y":60},{"id":"h2","label":"Signs in the local script","description":"Shop-signs and banners in the local Hindi/Devanagari script (on the buildings) — a sign the movement was reaching ordinary people, not just English-speaking elites","x":18,"y":25},{"id":"h3","label":"White clothing","description":"Most participants wearing white — many would later adopt khadi as a symbol of the national movement","x":62,"y":62}],"analysis":{"whatYouSee":["A massive crowd filling an entire urban street — thousands of people","Banners and placards in Hindi/local language","People in white clothing packed shoulder to shoulder","Buildings on both sides suggest a major city thoroughfare"],"whatItMeans":["Mass processions became a defining feature of the national movement — showing collective strength through numbers","The hartal of 6 April 1919 was the first truly nationwide protest — cities across India shut down simultaneously","The use of local language on banners shows the movement was reaching beyond the English-speaking educated elite","This was the beginning of mass politics in India — ordinary people, not just leaders, were now part of the struggle"],"examTip":"This image shows the SCALE of the anti-Rowlatt Act protests. When writing about the hartal of 6 April 1919, mention: nationwide strikes, shops closed, workers in railway workshops on strike, rallies in every major city."}},{"id":"ch2-fig-2","number":"2","title":"Indian Workers in South Africa March through Volksrust","year":"1913","type":"photograph","imagePath":"/images/ch2/fig-02-south-africa-march.png","sectionId":"s1","examRelevance":"medium","hotspots":[{"id":"h1","label":"The marching column","description":"The long column of Indian workers marching from Newcastle towards Transvaal (Nov 1913), defying racist laws that denied rights to non-whites","x":55,"y":60},{"id":"h2","label":"Head of the march","description":"Gandhi led this march from the front — the individual figures are too indistinct to pick out, but this is where the procession was headed. His South African struggle shaped satyagraha before he brought it to India.","x":20,"y":55}],"analysis":{"whatYouSee":["A long procession of Indian workers marching along a road in South Africa","Gandhi was leading these workers from Newcastle to Transvaal in November 1913","When the marchers were stopped and Gandhi arrested, thousands more workers joined"],"whatItMeans":["This is where satyagraha was born — in the struggle against racist laws in South Africa","Gandhi developed his method of non-violent resistance here before bringing it to India","The workers defied racist laws that denied basic rights to non-whites","Key point: satyagraha was tested and proven in South Africa BEFORE it was used in India"],"examTip":"When asked about Gandhi''s idea of satyagraha, always mention his South African experience. He returned to India in 1915 with a PROVEN method of non-violent resistance."}},{"id":"ch2-fig-3","number":"3","title":"General Dyer''s \"Crawling Orders\" — Amritsar, 1919","year":"1919","type":"photograph","imagePath":"/images/ch2/fig-03-crawling-orders.png","sectionId":"s1","examRelevance":"high","hotspots":[{"id":"h1","label":"Narrow street","description":"The narrow lane in Amritsar where Indians were forced to crawl on the ground under Dyer''s orders","x":48,"y":42},{"id":"h2","label":"British soldier","description":"Armed British soldier enforcing the crawling order — a deliberate act of humiliation","x":35,"y":78}],"analysis":{"whatYouSee":["A narrow street in Amritsar, Punjab","A British soldier standing guard while Indians were forced to crawl","This was one of General Dyer''s orders after the Jallianwala Bagh massacre"],"whatItMeans":["After the massacre, Dyer imposed humiliating measures — Indians had to crawl on the ground, do salaam to all British officers","People were publicly flogged, villages around Gujranwala were bombed","These measures were designed to humiliate and terrorise — to break the spirit of resistance","Instead, they deepened Indian anger and strengthened the demand for swaraj"],"examTip":"CBSE asks about the aftermath of Jallianwala Bagh. Mention: crawling orders, forced salaam, public flogging, village bombings. Then explain how this INCREASED Indian resistance instead of crushing it."}},{"id":"ch2-fig-4","number":"4","title":"The Boycott of Foreign Cloth, July 1922","year":"1922","type":"photograph","imagePath":"/images/ch2/fig-04-boycott-cloth.png","sectionId":"s2","examRelevance":"high","hotspots":[{"id":"h1","label":"Bonfire of cloth","description":"Foreign cloth being burnt in huge bonfires — a powerful visual act of resistance","x":52,"y":58},{"id":"h2","label":"Participants","description":"People gathering to participate in the boycott — this was a public, communal act of defiance","x":28,"y":45}],"analysis":{"whatYouSee":["People gathered around a bonfire of foreign cloth","Foreign cloth was seen as a symbol of Western economic and cultural domination","This was part of the Non-Cooperation Movement''s boycott programme"],"whatItMeans":["Foreign cloth represented British economic exploitation — Indian raw materials exported cheap, finished goods imported at high prices","The boycott had real economic impact: import of foreign cloth halved from Rs 102 crore to Rs 57 crore between 1921-22","Bonfires were dramatic public acts — making resistance visible and communal","BUT: khadi (Indian handspun cloth) was more expensive than mill cloth, making sustained boycott difficult for the poor"],"examTip":"Key exam fact: Import of foreign cloth dropped from Rs 102 crore to Rs 57 crore during Non-Cooperation. But also explain WHY the boycott slowed down — khadi was expensive, poor people couldn''t afford it."}},{"id":"ch2-fig-5","number":"5","title":"Chauri Chaura, 1922","year":"1922","type":"photograph","imagePath":"/images/ch2/fig-05-chauri-chaura.png","sectionId":"s2","examRelevance":"high","hotspots":[{"id":"h1","label":"Burnt ruins","description":"The ruins of the police station that was set on fire by an angry mob on 4 February 1922","x":50,"y":52}],"analysis":{"whatYouSee":["The aftermath of the Chauri Chaura incident — the burnt police station","At Chauri Chaura in Gorakhpur (UP), a peaceful demonstration turned into a violent clash","The crowd set fire to the police station, killing 22 policemen"],"whatItMeans":["This single incident caused Gandhi to call off the ENTIRE Non-Cooperation Movement","Gandhi believed that if the movement turned violent, it betrayed its fundamental principle — satyagraha","Other leaders (Nehru, Patel) were furious — the movement was at its peak when Gandhi withdrew","The incident showed that Gandhi could not control the movement completely — different groups interpreted his message differently"],"examTip":"CBSE''s MOST asked question about Non-Cooperation: \"Why did Gandhi call off the movement?\" Answer: Chauri Chaura violence (Feb 1922, 22 policemen killed) + Gandhi''s belief that non-violence was a moral principle, not just a strategy."}},{"id":"ch2-fig-6","number":"6","title":"Meeting of Congress Leaders at Allahabad, 1931","year":"1931","type":"photograph","imagePath":"/images/ch2/fig-06-congress-leaders.png","sectionId":"s3","examRelevance":"medium","hotspots":[{"id":"h1","label":"Congress leaders in discussion","description":"Senior Congress leaders seated together at Allahabad in 1931 — a moment of the leadership working side by side between the Salt March (1930) and the Round Table Conference (1931).","x":40,"y":52}],"analysis":{"whatYouSee":["Congress leaders gathered for a meeting at Allahabad in 1931","A group of the period''s senior leaders — figures such as Gandhi, Patel, Nehru and Bose were part of this circle (the grainy photo makes pinning each face uncertain)","The leaders are seated together — informal but purposeful"],"whatItMeans":["This photograph captures the Congress leadership during a critical period — between the Salt March (1930) and the Round Table Conference (1931)","The different leaders represent different approaches: Gandhi (non-violence), Nehru (socialism), Bose (radical mass agitation)","Despite internal differences, they are working together — unity within diversity"],"examTip":"Know the key Congress leaders of this period and their different approaches: Gandhi (non-violence), Nehru (socialism, full independence), Patel (organisation, the Bardoli Satyagraha), Bose (radical mass agitation). The exam tests who they were and what they stood for — not spotting each face in this photo."}},{"id":"ch2-fig-7","number":"7","title":"The Dandi March","year":"1930","type":"photograph","imagePath":"/images/ch2/fig-07-dandi-march.png","sectionId":"s3","examRelevance":"high","hotspots":[{"id":"h1","label":"Gandhi leading","description":"Gandhi (the bald figure walking with his staff) leading the march — 78 volunteers set out on the 240-mile walk from Sabarmati to Dandi","x":38,"y":31},{"id":"h2","label":"The marchers","description":"The volunteers walking with Gandhi — by the time they reached Dandi, thousands more had joined the column","x":66,"y":34}],"analysis":{"whatYouSee":["Gandhi walking with volunteers during the Salt March","He is accompanied by 78 trusted volunteers — they walked about 10 miles a day for 24 days","The march covered 240 miles from Sabarmati Ashram to the coastal town of Dandi in Gujarat"],"whatItMeans":["The Salt March is the most iconic moment of the Indian freedom struggle","Gandhi chose salt because it united ALL Indians — rich and poor, Hindu and Muslim, everyone needs salt","The British monopoly on salt production and the salt tax affected every Indian household","The march demonstrated that civil disobedience could be dramatic, disciplined, and deeply symbolic","On 6 April 1930, Gandhi picked up a handful of salt at Dandi — breaking British law and launching the Civil Disobedience Movement"],"examTip":"The Salt March is asked EVERY year. Key facts: 12 March - 6 April 1930, Sabarmati to Dandi, 240 miles, 78 volunteers, 24 days. And ALWAYS explain WHY salt — it was consumed by all classes, the tax affected everyone, making it a universal symbol of resistance."}},{"id":"ch2-fig-8","number":"8","title":"Police Cracked Down on Satyagrahis, 1930","year":"1930","type":"photograph","imagePath":"/images/ch2/fig-08-police-crackdown.png","sectionId":"s3","examRelevance":"medium","hotspots":[{"id":"h1","label":"Satyagrahis","description":"Peaceful protestors being confronted by British police — maintaining non-violence under violent repression","x":50,"y":58}],"analysis":{"whatYouSee":["British police cracking down on satyagrahis during the Civil Disobedience Movement","Peaceful protestors being physically confronted by armed police"],"whatItMeans":["The British government responded to the Civil Disobedience Movement with brutal repression","Peaceful satyagrahis were attacked, women and children beaten, about 100,000 people arrested","Despite the repression, the movement continued — showing the strength of satyagraha as a method","The contrast between peaceful protestors and violent police created international sympathy for India''s cause"],"examTip":"When writing about British repression during CDM, mention: ~100,000 arrested, peaceful satyagrahis beaten, women and children attacked. This repression ultimately strengthened the movement''s moral authority."}},{"id":"ch2-fig-9","number":"9","title":"Women Join Nationalist Processions","type":"photograph","imagePath":"/images/ch2/fig-09-women-processions.png","sectionId":"s3","examRelevance":"high","hotspots":[{"id":"h1","label":"Women marchers","description":"The procession of women — many left their homes for the first time to join the movement","x":50,"y":60},{"id":"h2","label":"Women of all ages","description":"Women of all ages joined — including older women and mothers with children — a revolutionary change in Indian public life","x":25,"y":61}],"analysis":{"whatYouSee":["Women participating in a nationalist procession during the Civil Disobedience Movement","Women of all ages — including old women and mothers with children in their arms","Many of these women were leaving their homes for a public cause for the first time in their lives"],"whatItMeans":["The Civil Disobedience Movement saw unprecedented participation by women","Thousands of women came out of their homes to participate in protest marches, manufacture salt, and picket foreign cloth and liquor shops","In urban areas, women were from high-caste families; in rural areas, from rich peasant households","However, Gandhi saw women''s role primarily as SYMBOLIC — \"good mothers and good wives\" serving the nation","Congress was reluctant to give women positions of authority within the organisation — they were valued for their presence, not their leadership"],"examTip":"CBSE asks about women''s participation in CDM. Important points: thousands joined salt marches + picketed shops + went to jail. BUT also note the limitation: Gandhi saw their role as symbolic, Congress wouldn''t give women real leadership positions."}},{"id":"ch2-fig-10","number":"10","title":"Mahatma Gandhi, Jawaharlal Nehru and Maulana Azad at Sevagram Ashram, Wardha","year":"1935","type":"photograph","imagePath":"/images/ch2/fig-10-gandhi-nehru-azad.png","sectionId":"s3","examRelevance":"low","hotspots":[{"id":"h1","label":"Gandhi","description":"Mahatma Gandhi (left, bald with round glasses) at his ashram — the spiritual centre of the national movement","x":18,"y":17},{"id":"h2","label":"Nehru","description":"Jawaharlal Nehru (centre, in the white Gandhi cap) — by 1935, one of the most prominent Congress leaders","x":46,"y":18},{"id":"h3","label":"Maulana Azad","description":"Maulana Abul Kalam Azad (right, with cap and beard) — a Muslim leader who remained committed to Hindu-Muslim unity and the Congress","x":78,"y":17}],"analysis":{"whatYouSee":["Three key Congress leaders at Gandhi''s Sevagram Ashram in Wardha, 1935","Gandhi, Nehru, and Maulana Azad — representing different generations and communities"],"whatItMeans":["The presence of Maulana Azad (a Muslim leader) alongside Gandhi and Nehru shows that the Congress still maintained Hindu-Muslim leadership at the top level","By 1935, however, communal tensions were growing — many Muslims felt alienated from Congress","This photograph captures a moment of unity that was becoming increasingly difficult to maintain"],"examTip":"Identify the three leaders. Maulana Azad''s presence is significant — he represents the Muslim leaders who stayed with Congress despite growing communal tensions."}},{"id":"ch2-fig-11","number":"11","title":"Bal Gangadhar Tilak — An Early-Twentieth-Century Print","type":"print","imagePath":"/images/ch2/fig-11-tilak-print.png","sectionId":"s4","examRelevance":"medium","hotspots":[{"id":"h1","label":"Tilak","description":"Bal Gangadhar Tilak — an early nationalist leader who popularised the idea of swaraj (\"Swaraj is my birthright\")","x":45,"y":27},{"id":"h2","label":"Symbols of unity","description":"The four corners frame the figure with a temple (top-left), masjid (top-right), church (bottom-left) and agyari/fire-temple (bottom-right) — symbols of different faiths united around the national leader","x":11,"y":8}],"analysis":{"whatYouSee":["A popular print showing Bal Gangadhar Tilak as a central, revered figure","Sacred institutions of different faiths — temple, church, masjid — frame the central figure","The print glorifies Tilak as a unifying national leader"],"whatItMeans":["Popular prints like this helped create a visual culture of nationalism","The inclusion of temple, church, and masjid was deliberate — showing national unity across religions","Such prints were widely circulated and helped spread nationalist ideas to people who couldn''t read","They turned political leaders into almost religious figures — deepening emotional connection to the movement"],"examTip":"Note the symbols of unity in this print — temple, church, masjid. This was an attempt to show the national movement as inclusive of ALL communities. But compare this with the Bharat Mata images — were they equally inclusive?"}},{"id":"ch2-fig-12","number":"12","title":"Bharat Mata — Abanindranath Tagore, 1905","artist":"Abanindranath Tagore","year":"1905","type":"painting","imagePath":"/images/ch2/fig-12-bharat-mata-tagore.png","sectionId":"s4","examRelevance":"high","hotspots":[{"id":"h1","label":"Ascetic, spiritual face","description":"Bharat Mata is calm, composed and ascetic — a spiritual mother, not a warrior queen. Her four arms, like a Hindu goddess, dispense a mother''s gifts.","x":48,"y":11},{"id":"h2","label":"White cloth — clothing","description":"An upper hand holds a piece of white cloth — clothing, one of the gifts the motherland provides her children.","x":15,"y":21},{"id":"h3","label":"Book — learning","description":"An upper hand holds a book (manuscript) — representing knowledge and learning.","x":82,"y":22},{"id":"h4","label":"Mala — spirituality","description":"A lower hand holds a mala (prayer beads) — emphasising her spiritual, ascetic quality, connected to dharma rather than power.","x":12,"y":40},{"id":"h5","label":"Sheaves of paddy — food","description":"A lower hand holds sheaves of paddy — food and nourishment for her children.","x":82,"y":41}],"analysis":{"whatYouSee":["A female figure representing India as a mother — Bharat Mata","She is calm, composed, and divine — an ascetic, spiritual figure","She holds items representing a mother''s gifts: learning, food, clothing","The mala (prayer beads) emphasises her spiritual quality","Painted by Abanindranath Tagore in 1905 during the Swadeshi movement"],"whatItMeans":["Tagore tried to create an image that was distinctly Indian — rejecting Western artistic styles","Bharat Mata as an ascetic mother represents India as nurturing, spiritual, and self-sufficient","This image was widely circulated during the Swadeshi movement and became a symbol of national identity","KEY EXAM QUESTION: Compare this with the later Bharat Mata (Fig 14a) — Tagore''s version is spiritual; the later one is about POWER","Also compare with Germania (Chapter 1) — both are female allegories of the nation, but with very different qualities"],"examTip":"This is one of the most asked figures in CBSE. Know: (1) Painted by Abanindranath Tagore, 1905 (2) Ascetic, calm, spiritual (3) Holds learning, food, clothing (4) Compare with Fig 14a (power version) AND with Germania from Chapter 1."}},{"id":"ch2-fig-13","number":"13","title":"Jawaharlal Nehru — A Popular Print","type":"print","imagePath":"/images/ch2/fig-13-nehru-print.png","sectionId":"s4","examRelevance":"medium","hotspots":[{"id":"h1","label":"Nehru with Bharat Mata","description":"Nehru is shown holding an image of Bharat Mata (the red figure on the map of India, titled \"भारत माता\") close to his heart","x":55,"y":62}],"analysis":{"whatYouSee":["A popular print showing Jawaharlal Nehru holding an image of Bharat Mata and the map of India close to his heart","In many popular prints, nationalist leaders were shown offering their heads to Bharat Mata — the idea of sacrifice for the mother was powerful"],"whatItMeans":["Popular prints turned political leaders into devotees of the motherland","The image of sacrifice — leaders offering themselves to Bharat Mata — made nationalism feel like a religious duty","Such prints were powerful tools of communication in a largely illiterate society"],"examTip":"These prints show how nationalism was communicated visually to people who couldn''t read. The idea of sacrificing for Bharat Mata made the political struggle feel deeply personal and sacred."}},{"id":"ch2-fig-14a","number":"14a","title":"Bharat Mata — With Trishul, Lion and Elephant","type":"painting","imagePath":"/images/ch2/fig-14a-bharat-mata-trishul.png","sectionId":"s4","examRelevance":"high","hotspots":[{"id":"h1","label":"Trishul","description":"The trident (trishul) at the top of the staff — a weapon associated with the Hindu deity Shiva. Unlike Tagore''s version, this Bharat Mata is about POWER, not spirituality.","x":30,"y":15},{"id":"h2","label":"Lion","description":"Symbol of power and authority — a departure from Tagore''s calm, ascetic mother figure","x":27,"y":78},{"id":"h3","label":"Elephant","description":"Another symbol of power, strength, and royalty — reinforcing the martial, powerful image","x":62,"y":60}],"analysis":{"whatYouSee":["A very different Bharat Mata from Tagore''s version","This Bharat Mata holds a trishul (trident), stands beside a lion and an elephant","Both the lion and elephant are symbols of power and authority","The figure is more assertive, martial — a queen, not an ascetic"],"whatItMeans":["This version shows how the image of Bharat Mata CHANGED over time — from spiritual to powerful","Like Germania in Chapter 1 (which evolved from hope to militarism), Bharat Mata also evolved","The trishul, lion, and elephant are all drawn from HINDU iconography","KEY QUESTION: Would this image appeal to ALL communities? Muslims, Christians, Dalits might not see themselves in it","This is the central tension of cultural nationalism: symbols meant to unite can end up excluding"],"examTip":"CBSE loves asking: \"Compare the two images of Bharat Mata (Tagore vs trishul version). How are they different? Would they appeal to all communities?\" Answer: Tagore = spiritual, inclusive; this version = powerful but Hindu-centric, potentially exclusionary."}},{"id":"ch2-fig-14b","number":"14b","title":"Women''s Procession in Bombay during the Quit India Movement","year":"1942","type":"photograph","imagePath":"/images/ch2/fig-14b-women-quit-india.png","sectionId":"s4","examRelevance":"medium","hotspots":[{"id":"h1","label":"Women marchers","description":"Women marching in large numbers during the Quit India Movement — the final mass struggle against British rule","x":50,"y":52}],"analysis":{"whatYouSee":["A large procession of women in Bombay during the Quit India Movement (1942)","The women are marching in organised formation — showing discipline and determination"],"whatItMeans":["The Quit India Movement (1942) was the last great mass struggle against British rule","Women''s participation had grown from the Salt March (1930) to Quit India (1942) — becoming a significant force","Key women leaders included Aruna Asaf Ali, Matangini Hazra (Bengal), Kanaklata Barua (Assam)","The movement showed that by 1942, the demand for freedom had become truly mass-based"],"examTip":"Know the key facts about Quit India: 8 August 1942, \"Do or Die\" speech, Congress Working Committee resolution at Wardha (14 July 1942), key leaders (Jayaprakash Narayan, Aruna Asaf Ali, Ram Manohar Lohia). British took over a year to suppress it."}},{"id":"ch2-fig-15","number":"15","title":"Jallianwala Bagh in 1919, Months After the Massacre","year":"1919","type":"photograph","imagePath":"/images/ch2/fig-15-jallianwala-bagh-1919.png","sectionId":"s1","examRelevance":"high","hotspots":[{"id":"h1","label":"The enclosed ground","description":"The open ground where thousands had gathered on 13 April 1919 for the Baisakhi fair and to protest the Rowlatt Act.","x":50,"y":55},{"id":"h2","label":"Walls & houses on every side","description":"The Bagh was hemmed in by high walls and the backs of houses on all sides — there was no easy way out once the firing began.","x":78,"y":38},{"id":"h3","label":"Few narrow exits","description":"Only a few narrow lanes led out of the ground. General Dyer blocked the main exit with his troops before ordering them to fire.","x":20,"y":45}],"analysis":{"whatYouSee":["A large, open, dusty ground photographed in 1919, soon after the massacre","High walls and the backs of houses enclosing the ground on every side","Only a few narrow lanes leading in and out","A few people standing in the vast empty space"],"whatItMeans":["The photograph shows exactly why the massacre was so deadly — the crowd was trapped in an enclosed space with very few exits","On 13 April 1919, General Dyer blocked the main exit and ordered troops to fire on the unarmed crowd for about ten minutes","Hundreds were killed; many jumped into the well inside the compound while trying to escape the bullets","Dyer later said his aim was \"to produce a moral effect\" — to create terror in the minds of satyagrahis"],"examTip":"Use this image to explain WHY Jallianwala Bagh was so deadly: an enclosed ground, walls on all sides, only narrow exits which Dyer blocked. Date to remember: 13 April 1919 (Baisakhi day). It became the tipping point that turned national anger into the demand for swaraj."}},{"id":"ch2-fig-16","number":"16","title":"General Reginald Dyer","year":"1920","type":"photograph","imagePath":"/images/ch2/fig-16-general-dyer.png","sectionId":"s1","examRelevance":"medium","hotspots":[],"analysis":{"whatYouSee":["A contemporary press photograph of General Reginald Dyer in military uniform","The British officer who commanded the troops at Jallianwala Bagh"],"whatItMeans":["General Dyer ordered his troops to open fire on the unarmed crowd at Jallianwala Bagh on 13 April 1919","He gave no warning to the crowd and deliberately blocked the exits before firing","He admitted his object was \"to produce a moral effect\" — to terrorise Indians into submission","The brutality, and the support Dyer received from many in Britain, shocked Indians and deepened the demand for self-rule"],"examTip":"Remember the name: General Dyer commanded the firing at Jallianwala Bagh. His \"crawling orders\" and other humiliations in Amritsar (under martial law) further inflamed the country."}}],"mapDefinitions":[{"id":"india-national-movement","title":"Centres of the Indian National Movement","subtitle":"Satyagrahas, Congress sessions and the Civil Disobedience Movement","imagePath":"/images/ch2/india-national-movement-map.png","sectionId":"s3","sectionColor":"#C2893E","examTip":"CBSE Map Question (2 marks): be ready to LOCATE and LABEL on the political map of India — Congress sessions (Calcutta 1920, Nagpur 1920, Lahore 1929) and movement centres (Champaran, Kheda, Ahmedabad, Amritsar, Chauri Chaura, Dandi).","regions":[{"id":"amritsar","label":"Amritsar","x":28.6,"y":16.6,"width":6,"height":4,"description":"Amritsar, Punjab — site of the Jallianwala Bagh massacre (13 April 1919), when General Dyer''s troops fired on a peaceful gathering, killing hundreds."},{"id":"lahore","label":"Lahore","x":26.5,"y":16.9,"width":6,"height":4,"description":"Lahore — Congress session of December 1929 where \"Purna Swaraj\" (complete independence) was declared; 26 January 1930 was fixed as the first Independence Day."},{"id":"champaran","label":"Champaran","x":66.5,"y":32.4,"width":6,"height":4,"description":"Champaran, Bihar (1917) — Gandhi''s first satyagraha in India, supporting peasants forced to grow indigo under the oppressive tinkathia system."},{"id":"chauri-chaura","label":"Chauri Chaura","x":61.9,"y":32.4,"width":6,"height":4,"description":"Chauri Chaura, United Provinces (Feb 1922) — a crowd set fire to a police station; in response Gandhi called off the Non-Cooperation Movement."},{"id":"ahmedabad","label":"Ahmedabad","x":19.9,"y":43.9,"width":6,"height":4,"description":"Ahmedabad, Gujarat (1918) — Gandhi led a satyagraha of cotton mill workers demanding higher wages."},{"id":"kheda","label":"Kheda","x":20.3,"y":44.8,"width":6,"height":4,"description":"Kheda, Gujarat (1918) — peasant satyagraha; Gandhi supported farmers who could not pay revenue after their crops failed."},{"id":"nagpur","label":"Nagpur","x":44.5,"y":49.9,"width":6,"height":4,"description":"Nagpur — Congress session of December 1920 that adopted the Non-Cooperation Movement."},{"id":"dandi","label":"Dandi","x":20.5,"y":50.6,"width":6,"height":4,"description":"Dandi, Gujarat (1930) — end-point of Gandhi''s Salt March; he broke the salt law here, launching the Civil Disobedience Movement."},{"id":"calcutta","label":"Calcutta","x":79.5,"y":45.4,"width":6,"height":4,"description":"Calcutta — special Congress session of September 1920 that adopted the Non-Cooperation programme."}]}],"activities":{"mcq":[{"id":"ch2-mcq-001","type":"mcq","sectionId":"s1","difficulty":"easy","examRelevance":"high","tags":["satyagraha","gandhi"],"question":"What does the term \"Satyagraha\" literally mean?","options":["Insistence on truth","Passive resistance","Soul of India","Non-violent protest"],"correctIndex":0,"explanation":"Satyagraha = Satya (truth) + Agraha (insistence). Gandhi was clear that it was NOT passive resistance — it was an active force that \"can be used only by the strong.\"","hints":["Break the word into its two Sanskrit roots"]},{"id":"ch2-mcq-002","type":"mcq","sectionId":"s1","difficulty":"easy","examRelevance":"high","tags":["champaran","gandhi"],"question":"Gandhi''s first satyagraha in India (1917) was on behalf of:","options":["Cotton mill workers in Ahmedabad","Peasants hit by crop failure in Kheda","Indigo planters in Champaran","Tea plantation workers in Assam"],"correctIndex":2,"explanation":"In 1917, Gandhi organised his first Indian satyagraha in Champaran, Bihar, where indigo farmers were forced to grow indigo under conditions that destroyed soil fertility.","hints":["It happened in Bihar and involved a crop used for blue dye"]},{"id":"ch2-mcq-003","type":"mcq","sectionId":"s1","difficulty":"medium","examRelevance":"high","tags":["rowlatt-act"],"question":"Why was the Rowlatt Act (1919) considered a threat to civil liberties?","options":["It imposed heavy taxes on Indian traders","It allowed detention without trial and arrest without evidence","It banned the Indian National Congress","It forced Indians to serve in the British army"],"correctIndex":1,"explanation":"The Rowlatt Act gave the British government power to arrest anyone and detain them for up to two years without trial or evidence. Even Indian members of the Imperial Legislative Council unanimously opposed it.","hints":["Think about what rights it took away from Indians"]},{"id":"ch2-mcq-004","type":"mcq","sectionId":"s1","difficulty":"medium","examRelevance":"high","tags":["jallianwala-bagh"],"question":"Many people at Jallianwala Bagh on 13 April 1919 were unaware of martial law because they:","options":["Were villagers who had come for the annual Baisakhi fair","Were from a neighbouring city and had just arrived","Had deliberately come to defy the British orders","Were soldiers on leave from the war"],"correctIndex":0,"explanation":"Many in the crowd were villagers who had come to Amritsar for the annual Baisakhi fair and were unaware of the martial law that had been imposed. General Dyer opened fire without warning.","hints":["April is a significant time for a Punjabi festival"]},{"id":"ch2-mcq-005","type":"mcq","sectionId":"s1","difficulty":"hard","examRelevance":"high","tags":["khilafat","hindu-muslim-unity"],"question":"Why did Gandhi support the Khilafat cause even though it was a Muslim religious issue?","options":["He personally believed in the spiritual authority of the Khalifa","He saw it as an opportunity to unite Hindus and Muslims against the British","The British ordered him to support it","The Khilafat leaders threatened to oppose Congress"],"correctIndex":1,"explanation":"Gandhi''s support for Khilafat was a strategic calculation: if he supported a Muslim cause, Muslims would support Congress. For the first time, Hindus and Muslims would fight together against the British in a united national movement.","hints":["Think about what Gandhi needed most for a national movement"]},{"id":"ch2-mcq-006","type":"mcq","sectionId":"s1","difficulty":"easy","examRelevance":"high","tags":["non-cooperation"],"question":"Which of the following was NOT part of the Non-Cooperation programme?","options":["Boycott of foreign goods","Surrender of government titles","Boycott of legislative councils and courts","Armed revolt against British officials"],"correctIndex":3,"explanation":"The Non-Cooperation programme was strictly non-violent: surrender titles, boycott institutions (schools, courts, councils), boycott foreign goods. Armed revolt was never part of Gandhi''s programme.","hints":["Gandhi''s method was always based on non-violence"]},{"id":"ch2-mcq-007","type":"mcq","sectionId":"s2","difficulty":"medium","examRelevance":"high","tags":["non-cooperation","towns"],"question":"Why did the Non-Cooperation Movement gradually slow down in the cities?","options":["The British made too many concessions","Gandhi personally asked city people to stop participating","Khadi was expensive and alternative Indian institutions were slow to develop","The Muslim League opposed the movement in cities"],"correctIndex":2,"explanation":"The movement lost steam in towns because khadi was more expensive than mill cloth (poor people couldn''t afford it) and alternative Indian schools and courts took time to set up. Without replacements for British institutions, the boycott couldn''t sustain.","hints":["Think about the practical problems of boycotting without alternatives"]},{"id":"ch2-mcq-008","type":"mcq","sectionId":"s2","difficulty":"medium","examRelevance":"high","tags":["awadh","peasants"],"question":"What did \"Swaraj\" mean for the peasants of Awadh?","options":["A constitution based on British parliamentary democracy","Reserved seats in legislative councils","An end to exorbitant rents, begar, and exploitation by talukdars","Freedom to trade directly with Britain"],"correctIndex":2,"explanation":"For Awadh peasants, Swaraj had nothing to do with constitutions — it meant freedom from talukdars who charged exorbitant rents, demanded begar (unpaid forced labour), and offered no security of tenure.","hints":["Peasants cared about their daily survival, not political structures"]},{"id":"ch2-mcq-009","type":"mcq","sectionId":"s2","difficulty":"easy","examRelevance":"high","tags":["baba-ramchandra","awadh"],"question":"Baba Ramchandra, who led the peasant movement in Awadh, had earlier been:","options":["An indentured labourer in Fiji","A wealthy landlord in Bengal","A British-trained lawyer","A professor at Aligarh University"],"correctIndex":0,"explanation":"Baba Ramchandra was a sanyasi who had earlier been an indentured labourer in Fiji. He understood the exploitation of labourers firsthand, which gave him credibility among the Awadh peasants.","hints":["He had personal experience of forced labour in a faraway country"]},{"id":"ch2-mcq-010","type":"mcq","sectionId":"s2","difficulty":"hard","examRelevance":"high","tags":["alluri-sitaram-raju","tribals"],"question":"What was the fundamental contradiction in Alluri Sitaram Raju''s approach?","options":["He opposed both Gandhi and the British equally","He invoked Gandhi and wore khadi but used guerrilla violence","He supported the British while pretending to oppose them","He rejected Indian nationalism in favour of tribal autonomy"],"correctIndex":1,"explanation":"Raju is a paradox: he wore khadi, invoked Gandhi, supported Non-Cooperation — but he used guerrilla warfare, attacked police stations, and killed British officials. He believed India could only be freed through force, not non-violence.","hints":["He combined two seemingly opposite methods"]},{"id":"ch2-mcq-011","type":"mcq","sectionId":"s2","difficulty":"medium","examRelevance":"high","tags":["plantation-workers","assam"],"question":"For Assam plantation workers, \"Swaraj\" essentially meant:","options":["Higher wages and shorter working hours","The right to vote in provincial elections","Ownership of the tea gardens","The right to move freely — to leave the plantations"],"correctIndex":3,"explanation":"Under the Inland Emigration Act of 1859, plantation workers were not allowed to leave tea gardens without permission. For them, swaraj was the simplest dream — just the freedom to go home.","hints":["Think about what basic right was denied to them by law"]},{"id":"ch2-mcq-012","type":"mcq","sectionId":"s2","difficulty":"easy","examRelevance":"high","tags":["chauri-chaura"],"question":"Gandhi called off the entire Non-Cooperation Movement in February 1922 because:","options":["A violent mob at Chauri Chaura killed 22 policemen","The British agreed to grant Swaraj","Hindu-Muslim unity had completely broken down","He was arrested and could not lead the movement"],"correctIndex":0,"explanation":"At Chauri Chaura, Gorakhpur, a peaceful demonstration turned violent and a mob set fire to the police station, killing 22 policemen. Gandhi was devastated and called off the entire movement — non-violence was not a tactic but the soul of the struggle.","hints":["It involved a violent incident in a small town in UP"]},{"id":"ch2-mcq-013","type":"mcq","sectionId":"s2","difficulty":"hard","examRelevance":"high","tags":["non-cooperation","different-groups"],"question":"Why did different social groups interpret Gandhi''s message in their own ways during Non-Cooperation?","options":["Gandhi deliberately gave different messages to different groups","Each group filtered the idea of Swaraj through their own experiences and needs","The British spread misinformation about Gandhi''s goals","Congress leaders in each region changed the message"],"correctIndex":1,"explanation":"Peasants thought Gandhi had declared no more taxes, workers believed \"Gandhi Raj\" meant land for all, tribals used his name for armed resistance. Each group understood Swaraj through the lens of their own suffering and aspirations — the movement grew, but grew out of Gandhi''s control.","hints":["Think about how the same word can mean different things to people in different situations"]},{"id":"ch2-mcq-014","type":"mcq","sectionId":"s3","difficulty":"easy","examRelevance":"high","tags":["simon-commission"],"question":"Indians opposed the Simon Commission (1928) primarily because:","options":["It recommended Partition of India","It proposed abolishing the Congress party","It wanted to extend the Rowlatt Act","It had no Indian members — all members were British"],"correctIndex":3,"explanation":"The Simon Commission was set up to review India''s constitutional progress but had no Indian member — all its members were British. This united Congress and the Muslim League in the \"Go Back Simon!\" protests.","hints":["The issue was about representation"]},{"id":"ch2-mcq-015","type":"mcq","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["lahore-congress","purna-swaraj"],"question":"The historic declaration of \"Purna Swaraj\" was made at the:","options":["Nagpur Congress (1920)","Calcutta Congress (1920)","Lahore Congress (1929)","Karachi Congress (1931)"],"correctIndex":2,"explanation":"At the December 1929 Lahore Congress, under Jawaharlal Nehru''s presidency, Congress formally demanded Purna Swaraj — complete independence. 26 January 1930 was declared Independence Day.","hints":["It was the Congress session just before the Salt March"]},{"id":"ch2-mcq-016","type":"mcq","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["salt-march","dandi"],"question":"Why did Gandhi choose salt as the symbol for the Civil Disobedience Movement?","options":["Salt was India''s largest export to Britain","The salt tax was the highest tax imposed by the British","Salt was consumed by rich and poor alike — it united all Indians regardless of caste or religion","Salt production was controlled by Indian industrialists"],"correctIndex":2,"explanation":"Salt was the perfect unifying symbol: rich and poor, Hindu and Muslim, Brahmin and Dalit — everyone needed salt daily. By taxing it, the British had turned every kitchen in India into a site of potential resistance.","hints":["Think about what makes salt different from other goods — who uses it?"]},{"id":"ch2-mcq-017","type":"mcq","sectionId":"s3","difficulty":"easy","examRelevance":"high","tags":["salt-march","dandi"],"question":"The Dandi March began on 12 March 1930 from:","options":["Porbandar","Sabarmati Ashram","Dandi beach","Champaran"],"correctIndex":1,"explanation":"Gandhi started the march from his Sabarmati Ashram with 78 trusted volunteers, walking 240 miles to the coastal town of Dandi in Gujarat, where he broke the salt law on 6 April 1930.","hints":["It was Gandhi''s own ashram in Gujarat"]},{"id":"ch2-mcq-018","type":"mcq","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["cdm","non-cooperation"],"question":"How was Civil Disobedience fundamentally different from Non-Cooperation?","options":["CDM was led by Nehru, not Gandhi","CDM demanded dominion status while Non-Cooperation demanded full independence","CDM was limited to cities while Non-Cooperation was rural","In Non-Cooperation, people refused to cooperate; in CDM, people actively broke the law"],"correctIndex":3,"explanation":"The key distinction: Non-Cooperation meant refusing to participate (boycotting institutions). Civil Disobedience meant actively BREAKING the law — manufacturing salt illegally, refusing to pay revenue, violating forest laws. It was a direct challenge to British authority.","hints":["The clue is in the name — \"disobedience\" means something different from \"non-cooperation\""]},{"id":"ch2-mcq-019","type":"mcq","sectionId":"s3","difficulty":"hard","examRelevance":"high","tags":["cdm","rich-peasants"],"question":"Why were rich peasants (Patidars, Jats) disappointed when Gandhi called off CDM in 1931?","options":["The Gandhi-Irwin Pact did not guarantee any reduction in revenue rates","Gandhi had promised them reserved seats in councils","The British had already agreed to lower land taxes","Gandhi refused to acknowledge their contribution to the movement"],"correctIndex":0,"explanation":"Rich peasants like Patidars of Gujarat and Jats of UP had enthusiastically joined CDM because the Depression made it impossible to pay high revenue. When Gandhi signed the Gandhi-Irwin Pact without securing a reduction in revenue, many refused to rejoin the movement in 1932.","hints":["Think about their main economic demand and whether it was met"]},{"id":"ch2-mcq-020","type":"mcq","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["ambedkar","dalits","poona-pact"],"question":"The Poona Pact (1932) between Gandhi and Ambedkar resulted in:","options":["Separate electorates for Dalits as Ambedkar originally demanded","Dalits joining the Congress party unconditionally","Complete abolition of the caste system","Reserved seats for Dalits within joint electorates"],"correctIndex":3,"explanation":"Ambedkar originally demanded separate electorates, but Gandhi opposed this and went on a fast unto death. The compromise — the Poona Pact — gave Dalits reserved seats but within joint electorates, not separate ones.","hints":["It was a compromise — neither fully got what they wanted"]},{"id":"ch2-mcq-021","type":"mcq","sectionId":"s3","difficulty":"hard","examRelevance":"high","tags":["muslims","cdm"],"question":"Why were many Muslim organisations lukewarm towards the Civil Disobedience Movement?","options":["Muslims had already gained independence through the Khilafat movement","The British promised Muslims a separate nation if they stayed out","After the decline of Khilafat, Congress became associated with Hindu groups and communal riots deepened distrust","Gandhi explicitly asked Muslims not to participate"],"correctIndex":2,"explanation":"After the Khilafat movement collapsed, Muslims felt alienated from Congress, which became increasingly associated with Hindu groups like the Hindu Mahasabha. Communal riots further deepened the divide, and Jinnah''s demand for reserved Muslim seats was rejected at the 1928 All Parties Conference.","hints":["Think about what happened AFTER the brief Hindu-Muslim unity of Khilafat"]},{"id":"ch2-mcq-022","type":"mcq","sectionId":"s4","difficulty":"easy","examRelevance":"high","tags":["bharat-mata","allegory"],"question":"The image of \"Bharat Mata\" was first created by:","options":["Abanindranath Tagore","Rabindranath Tagore","Bankim Chandra Chattopadhyay","Mahatma Gandhi"],"correctIndex":0,"explanation":"Abanindranath Tagore painted the famous image of Bharat Mata in 1905, portraying her as a calm, ascetic, divine figure holding learning, food, and clothing — a spiritual mother of the nation.","hints":["He was a famous painter, not a writer or leader"]},{"id":"ch2-mcq-023","type":"mcq","sectionId":"s4","difficulty":"medium","examRelevance":"high","tags":["bharat-mata","limits"],"question":"Why was the image of Bharat Mata problematic for building truly inclusive nationalism?","options":["The image was too modern and westernised","It drew from Hindu iconography, which could alienate Muslims, Christians, and Dalits","The British banned all images of Bharat Mata","It depicted a man, not a woman"],"correctIndex":1,"explanation":"Bharat Mata drew from Hindu iconography — Vande Mataram came from a Hindu novel, later images used trishul and lion (Hindu symbols). When the idea of the nation is wrapped in one religion''s imagery, other communities may not see themselves in it.","hints":["Think about whose cultural symbols were used in the image"]},{"id":"ch2-mcq-024","type":"mcq","sectionId":"s4","difficulty":"easy","examRelevance":"high","tags":["flag","symbols"],"question":"The spinning wheel (charkha) on Gandhi''s Swaraj flag represented:","options":["Self-reliance","India''s industrial power","Hindu religious tradition","British textile trade"],"correctIndex":0,"explanation":"The charkha on the Swaraj flag (designed by Gandhiji in 1921 — red, green, white stripes) symbolised self-reliance. Spinning your own cloth meant rejecting dependence on British mill-made goods.","hints":["Think about what the act of spinning cloth at home represents"]},{"id":"ch2-mcq-025","type":"mcq","sectionId":"s4","difficulty":"medium","examRelevance":"high","tags":["folklore","nationalism"],"question":"Nationalists collected folk tales and songs to build national identity — similar to the role played in Europe by:","options":["Napoleon Bonaparte and the French army","Giuseppe Mazzini and Young Europe","Duke Metternich and the Congress of Vienna","The Grimm Brothers in Germany"],"correctIndex":3,"explanation":"Just as the Grimm Brothers collected German folk tales to promote German cultural nationalism, Indian nationalists like Rabindranath Tagore in Bengal and Natesa Sastri in Madras collected folk stories to build a sense of shared Indian identity.","hints":["Think about Chapter 1 — who collected folk tales in Germany?"]}],"fillBlank":[{"id":"ch2-fb-001","type":"fill-blank","sectionId":"s1","difficulty":"easy","examRelevance":"high","tags":["satyagraha","gandhi"],"sentence":"Satyagraha = Satya (truth) + Agraha (insistence) = insistence on _____.","blanks":[{"position":0,"answer":"truth","alternatives":["Truth"]}],"hints":["The first part of the word gives you the answer"]},{"id":"ch2-fb-002","type":"fill-blank","sectionId":"s1","difficulty":"easy","examRelevance":"high","tags":["rowlatt-act"],"sentence":"The _____ Act of 1919 allowed the British to arrest and detain Indians without trial.","blanks":[{"position":0,"answer":"Rowlatt","alternatives":["rowlatt","Rowlett"]}],"hints":["Named after the judge who headed the committee that recommended it"]},{"id":"ch2-fb-003","type":"fill-blank","sectionId":"s1","difficulty":"medium","examRelevance":"high","tags":["khilafat"],"sentence":"The Khilafat Committee was formed in Bombay in March 1919, led by brothers _____ Ali and _____ Ali.","blanks":[{"position":0,"answer":"Muhammad","alternatives":["Mohammed","mohammad","muhammad"]},{"position":1,"answer":"Shaukat","alternatives":["shaukat","Shoukat"]}],"hints":["They were brothers who led the Khilafat movement in India"]},{"id":"ch2-fb-004","type":"fill-blank","sectionId":"s1","difficulty":"medium","examRelevance":"high","tags":["non-cooperation"],"sentence":"In his book _____, Gandhi declared that British rule in India could collapse within a year if Indians refused to cooperate.","blanks":[{"position":0,"answer":"Hind Swaraj","alternatives":["hind swaraj","Hind swaraj"]}],"hints":["The title means \"Indian Self-Rule\" — written in 1909"]},{"id":"ch2-fb-005","type":"fill-blank","sectionId":"s2","difficulty":"easy","examRelevance":"high","tags":["boycott"],"sentence":"The word \"boycott\" originates from Captain Charles _____, an Irish land agent who was ostracised by his community.","blanks":[{"position":0,"answer":"Boycott","alternatives":["boycott","BOYCOTT"]}],"hints":["The word itself is this person''s surname"]},{"id":"ch2-fb-006","type":"fill-blank","sectionId":"s2","difficulty":"medium","examRelevance":"high","tags":["begar","awadh"],"sentence":"_____ was forced unpaid labour that villagers were compelled to contribute to landlords.","blanks":[{"position":0,"answer":"Begar","alternatives":["begar","BEGAR"]}],"hints":["A Hindi/Urdu term for a specific type of exploitation by talukdars"]},{"id":"ch2-fb-007","type":"fill-blank","sectionId":"s2","difficulty":"medium","examRelevance":"high","tags":["plantation-workers","assam"],"sentence":"Under the Inland Emigration Act of _____, plantation workers in Assam were not allowed to leave tea gardens without permission.","blanks":[{"position":0,"answer":"1859","alternatives":[]}],"hints":["It was passed just after the revolt of 1857"]},{"id":"ch2-fb-008","type":"fill-blank","sectionId":"s2","difficulty":"easy","examRelevance":"high","tags":["chauri-chaura"],"sentence":"Gandhi called off the Non-Cooperation Movement in February 1922 after the violent incident at _____ in Gorakhpur.","blanks":[{"position":0,"answer":"Chauri Chaura","alternatives":["chauri chaura","Chauri chaura"]}],"hints":["A small town in UP where 22 policemen were killed"]},{"id":"ch2-fb-009","type":"fill-blank","sectionId":"s3","difficulty":"easy","examRelevance":"high","tags":["purna-swaraj"],"sentence":"At the Lahore Congress of December 1929, under Jawaharlal Nehru''s presidency, the demand for _____ (complete independence) was formally adopted.","blanks":[{"position":0,"answer":"Purna Swaraj","alternatives":["purna swaraj","Purna swaraj","complete independence"]}],"hints":["It literally means \"complete self-rule\" in Hindi"]},{"id":"ch2-fb-010","type":"fill-blank","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["ambedkar","dalits"],"sentence":"Dr. B.R. Ambedkar organised Dalits into the _____ Association in 1930.","blanks":[{"position":0,"answer":"Depressed Classes","alternatives":["depressed classes","Depressed classes"]}],"hints":["The name reflected how Dalits referred to themselves — as \"oppressed\" or \"depressed\""]},{"id":"ch2-fb-011","type":"fill-blank","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["gandhi-irwin-pact"],"sentence":"In March 1931, Gandhi signed the _____-_____ Pact and agreed to attend the Round Table Conference in London.","blanks":[{"position":0,"answer":"Gandhi","alternatives":["gandhi"]},{"position":1,"answer":"Irwin","alternatives":["irwin"]}],"hints":["Named after the two people who negotiated it — one Indian leader and one British Viceroy"]},{"id":"ch2-fb-012","type":"fill-blank","sectionId":"s4","difficulty":"easy","examRelevance":"high","tags":["vande-mataram"],"sentence":"The hymn _____ was written by Bankim Chandra Chattopadhyay and was included in his novel Anandamath.","blanks":[{"position":0,"answer":"Vande Mataram","alternatives":["vande mataram","Vande mataram","Vandemataram"]}],"hints":["It means \"I bow to thee, Mother\" — it became a national anthem of resistance"]}],"trueFalse":[{"id":"ch2-tf-001","type":"true-false","sectionId":"s1","difficulty":"easy","examRelevance":"high","tags":["satyagraha"],"statement":"Satyagraha means passive resistance — the weapon of the weak.","isTrue":false,"explanation":"Gandhi explicitly rejected the term \"passive resistance.\" He said satyagraha was the weapon of the STRONG, not the weak. It was an active force based on truth, not mere passivity."},{"id":"ch2-tf-002","type":"true-false","sectionId":"s1","difficulty":"easy","examRelevance":"high","tags":["jallianwala-bagh"],"statement":"General Dyer ordered firing at Jallianwala Bagh to produce what he called \"a moral effect\" on Indians.","isTrue":true,"explanation":"General Dyer later stated that his purpose in ordering the firing on an unarmed crowd — without warning, with exits blocked — was to \"produce a moral effect\" and intimidate Indians into submission."},{"id":"ch2-tf-003","type":"true-false","sectionId":"s1","difficulty":"medium","examRelevance":"high","tags":["non-cooperation"],"statement":"The Non-Cooperation programme was adopted at the Lahore Congress session in December 1920.","isTrue":false,"explanation":"The Non-Cooperation programme was adopted at the Nagpur Congress in December 1920, not Lahore. The Lahore Congress (December 1929) was where Purna Swaraj was declared — a common mix-up."},{"id":"ch2-tf-004","type":"true-false","sectionId":"s1","difficulty":"medium","examRelevance":"high","tags":["non-cooperation","impact"],"statement":"During Non-Cooperation, the import of foreign cloth halved — from Rs 102 crore to Rs 57 crore.","isTrue":true,"explanation":"The boycott of foreign goods had a real economic impact: foreign cloth imports dropped from Rs 102 crore to Rs 57 crore as Indians burnt foreign cloth in bonfires and switched to Indian-made products."},{"id":"ch2-tf-005","type":"true-false","sectionId":"s2","difficulty":"medium","examRelevance":"high","tags":["awadh","peasants"],"statement":"Peasants in Awadh strictly followed Congress guidelines and limited their protests to non-violent methods approved by Gandhi.","isTrue":false,"explanation":"Peasants went BEYOND what Congress intended — they attacked talukdars'' houses, looted bazaars, and took over grain hoards. Local leaders told peasants that Gandhi had declared no more taxes and land would be redistributed, though Gandhi had never authorised such actions."},{"id":"ch2-tf-006","type":"true-false","sectionId":"s2","difficulty":"easy","examRelevance":"high","tags":["alluri-sitaram-raju"],"statement":"Alluri Sitaram Raju led tribal resistance in the Gudem Hills of Andhra Pradesh using guerrilla methods.","isTrue":true,"explanation":"Alluri Sitaram Raju led the tribal rebellion in the Gudem Hills against the colonial government''s forest restrictions and begar demands. Despite invoking Gandhi, he used guerrilla warfare — attacking police stations and killing British officials."},{"id":"ch2-tf-007","type":"true-false","sectionId":"s2","difficulty":"hard","examRelevance":"high","tags":["chauri-chaura","gandhi"],"statement":"Gandhi called off Non-Cooperation at Chauri Chaura because the movement was failing and losing support.","isTrue":false,"explanation":"This is a common misconception. The movement was actually at its PEAK when Gandhi called it off. He withdrew it specifically because of the violence — 22 policemen were killed. Gandhi believed a movement that kills is no different from the empire it fights. Non-violence was the soul of the struggle, not just a tactic."},{"id":"ch2-tf-008","type":"true-false","sectionId":"s3","difficulty":"easy","examRelevance":"high","tags":["simon-commission"],"statement":"The Simon Commission was opposed because it had only one Indian member.","isTrue":false,"explanation":"The Simon Commission had NO Indian members at all — not even one. All members were British. This is why it was opposed so strongly, uniting even Congress and the Muslim League in the \"Go Back Simon!\" protests."},{"id":"ch2-tf-009","type":"true-false","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["salt-march"],"statement":"Gandhi marched to Dandi with thousands of followers from the very beginning of the Salt March.","isTrue":false,"explanation":"Gandhi started the Dandi March with only 78 trusted volunteers from Sabarmati Ashram. Thousands joined along the way as he walked through villages over 24 days, but the starting group was deliberately small and disciplined."},{"id":"ch2-tf-010","type":"true-false","sectionId":"s3","difficulty":"easy","examRelevance":"high","tags":["cdm"],"statement":"In the Civil Disobedience Movement, people actively broke British laws — manufacturing salt, refusing to pay taxes, and violating forest laws.","isTrue":true,"explanation":"CDM was fundamentally about actively BREAKING the law, not just refusing to cooperate. Indians manufactured salt illegally, refused to pay revenue, violated forest laws, and boycotted foreign cloth as direct acts of defiance."},{"id":"ch2-tf-011","type":"true-false","sectionId":"s3","difficulty":"hard","examRelevance":"high","tags":["congress","poor-peasants"],"statement":"Congress supported \"no rent\" campaigns for poor peasants and sharecroppers during the Civil Disobedience Movement.","isTrue":false,"explanation":"Congress deliberately did NOT support \"no rent\" campaigns. They feared alienating rich peasants and zamindars who were important Congress supporters. As a result, poor peasants and sharecroppers turned to Socialist and Communist movements instead."},{"id":"ch2-tf-012","type":"true-false","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["women","cdm"],"statement":"Women participated extensively in Civil Disobedience and were given important positions of authority within Congress.","isTrue":false,"explanation":"While thousands of women participated — in salt marches, picketing, manufacturing salt, going to jail — Gandhi saw their role as largely SYMBOLIC. Congress was reluctant to give women real positions of authority. Their role was celebrated but limited."},{"id":"ch2-tf-013","type":"true-false","sectionId":"s4","difficulty":"easy","examRelevance":"high","tags":["bharat-mata"],"statement":"Bankim Chandra Chattopadhyay wrote \"Vande Mataram,\" which became an anthem of resistance during the Swadeshi movement.","isTrue":true,"explanation":"Bankim Chandra Chattopadhyay wrote Vande Mataram in the 1870s and included it in his novel Anandamath. It gained massive popularity as a song of resistance during the Swadeshi movement in Bengal."},{"id":"ch2-tf-014","type":"true-false","sectionId":"s4","difficulty":"medium","examRelevance":"high","tags":["folklore","nationalism"],"statement":"The nationalist rewriting of Indian history celebrated a past that was equally representative of all Indian communities — Hindu, Muslim, and Dalit.","isTrue":false,"explanation":"The \"glorious past\" that nationalists celebrated was largely HINDU past — temples, Sanskrit, Vedic achievements. Muslims, Christians, and Dalits did not see themselves in this version of history. The very tools meant to unite were inadvertently dividing."},{"id":"ch2-tf-015","type":"true-false","sectionId":"s4","difficulty":"medium","examRelevance":"high","tags":["flag","symbols"],"statement":"The tricolour flag used during the Swadeshi movement in Bengal included a crescent moon to represent Hindu-Muslim unity.","isTrue":true,"explanation":"The Swadeshi-era tricolour (red, green, yellow) included 8 lotuses for 8 provinces AND a crescent moon — the crescent was specifically included to symbolise Hindu-Muslim unity within the national movement."}],"match":[{"id":"ch2-match-001","type":"match-following","sectionId":"s1","difficulty":"medium","examRelevance":"high","tags":["movements","characteristics"],"title":"Match the movement/campaign with its key characteristic","leftColumn":[{"id":"l1","text":"Rowlatt Satyagraha (1919)"},{"id":"l2","text":"Khilafat Movement"},{"id":"l3","text":"Non-Cooperation Movement"},{"id":"l4","text":"Civil Disobedience Movement"}],"rightColumn":[{"id":"r1","text":"Refusal to obey unjust laws, not just non-participation"},{"id":"r2","text":"First mass movement led by Gandhi against unjust laws"},{"id":"r3","text":"Hindu-Muslim unity to restore Ottoman Caliph''s powers"},{"id":"r4","text":"Boycott of British institutions, surrender of titles and councils"}],"correctPairs":[["l1","r2"],["l2","r3"],["l3","r4"],["l4","r1"]]},{"id":"ch2-match-002","type":"match-following","sectionId":"s2","difficulty":"medium","examRelevance":"high","tags":["events","dates"],"title":"Match the event with its date","leftColumn":[{"id":"l1","text":"Jallianwala Bagh massacre"},{"id":"l2","text":"Rowlatt Act passed"},{"id":"l3","text":"Chauri Chaura incident"},{"id":"l4","text":"Gandhi''s Dandi March begins"},{"id":"l5","text":"Simon Commission arrives in India"}],"rightColumn":[{"id":"r1","text":"1928"},{"id":"r2","text":"13 April 1919"},{"id":"r3","text":"February 1922"},{"id":"r4","text":"12 March 1930"},{"id":"r5","text":"1919"}],"correctPairs":[["l1","r2"],["l2","r5"],["l3","r3"],["l4","r4"],["l5","r1"]]},{"id":"ch2-match-003","type":"match-following","sectionId":"s1","difficulty":"easy","examRelevance":"high","tags":["people","roles"],"title":"Match the leader with their role in the national movement","leftColumn":[{"id":"l1","text":"Mahatma Gandhi"},{"id":"l2","text":"Alluri Sitarama Raju"},{"id":"l3","text":"Baba Ramchandra"},{"id":"l4","text":"Muhammad Ali & Shaukat Ali"}],"rightColumn":[{"id":"r1","text":"Led peasant movement in Awadh against talukdars"},{"id":"r2","text":"Led tribal uprising in Andhra Pradesh (Gudem Hills)"},{"id":"r3","text":"Leaders of the Khilafat Movement"},{"id":"r4","text":"Developed philosophy of satyagraha in South Africa"}],"correctPairs":[["l1","r4"],["l2","r2"],["l3","r1"],["l4","r3"]]},{"id":"ch2-match-004","type":"match-following","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["groups","demands"],"title":"Match the social group with their demands during Non-Cooperation","leftColumn":[{"id":"l1","text":"Peasants in Awadh"},{"id":"l2","text":"Plantation workers in Assam"},{"id":"l3","text":"Tribal people in Gudem Hills"},{"id":"l4","text":"Urban middle class"}],"rightColumn":[{"id":"r1","text":"Boycotted British institutions, returned titles, left government jobs"},{"id":"r2","text":"Opposed forced labour (begar), demanded reduction of revenue"},{"id":"r3","text":"Defied the Inland Emigration Act, left plantations for their villages"},{"id":"r4","text":"Attacked police stations and traders, demanded forest access"}],"correctPairs":[["l1","r2"],["l2","r3"],["l3","r4"],["l4","r1"]]},{"id":"ch2-match-005","type":"match-following","sectionId":"s2","difficulty":"easy","examRelevance":"high","tags":["vocabulary"],"title":"Match the key term with its meaning","leftColumn":[{"id":"l1","text":"Satyagraha"},{"id":"l2","text":"Boycott"},{"id":"l3","text":"Swadeshi"},{"id":"l4","text":"Begar"}],"rightColumn":[{"id":"r1","text":"Refusal to deal with or buy goods from a person, organisation or country"},{"id":"r2","text":"Labour that villagers were forced to do without payment"},{"id":"r3","text":"Truth-force: non-violent resistance appealing to oppressor''s conscience"},{"id":"r4","text":"Of one''s own country; using goods made in India"}],"correctPairs":[["l1","r3"],["l2","r1"],["l3","r4"],["l4","r2"]]},{"id":"ch2-match-006","type":"match-following","sectionId":"s4","difficulty":"medium","examRelevance":"high","tags":["events","dates"],"title":"Match the round table conference / pact with its year","leftColumn":[{"id":"l1","text":"First Round Table Conference"},{"id":"l2","text":"Gandhi-Irwin Pact"},{"id":"l3","text":"Second Round Table Conference"},{"id":"l4","text":"Poona Pact"}],"rightColumn":[{"id":"r1","text":"1932"},{"id":"r2","text":"1930"},{"id":"r3","text":"March 1931"},{"id":"r4","text":"December 1931"}],"correctPairs":[["l1","r2"],["l2","r3"],["l3","r4"],["l4","r1"]]},{"id":"ch2-match-007","type":"match-following","sectionId":"s3","difficulty":"hard","examRelevance":"high","tags":["people","roles"],"title":"Match the leader with their specific contribution","leftColumn":[{"id":"l1","text":"Jawaharlal Nehru"},{"id":"l2","text":"Dr B.R. Ambedkar"},{"id":"l3","text":"Abdul Ghaffar Khan"},{"id":"l4","text":"Subhas Chandra Bose"}],"rightColumn":[{"id":"r1","text":"Led Khudai Khidmatgar movement in NWFP"},{"id":"r2","text":"Organised oppressed castes, clashed with Gandhi on separate electorates"},{"id":"r3","text":"Presided over Congress session that declared Purna Swaraj (1929)"},{"id":"r4","text":"Radical nationalist who believed in militant action for freedom"}],"correctPairs":[["l1","r3"],["l2","r2"],["l3","r1"],["l4","r4"]]},{"id":"ch2-match-008","type":"match-following","sectionId":"s4","difficulty":"medium","examRelevance":"high","tags":["movements","characteristics"],"title":"Match the satyagraha with the issue it opposed","leftColumn":[{"id":"l1","text":"Champaran Satyagraha (1917)"},{"id":"l2","text":"Kheda Satyagraha (1917)"},{"id":"l3","text":"Ahmedabad Mill Strike (1918)"},{"id":"l4","text":"Salt March (1930)"}],"rightColumn":[{"id":"r1","text":"British monopoly on salt — taxing a basic necessity"},{"id":"r2","text":"Indigo planters'' oppressive tinkathia system in Bihar"},{"id":"r3","text":"Mill workers demanded fair wages during plague and famine"},{"id":"r4","text":"Crop failure and plague — peasants demanded revenue relaxation"}],"correctPairs":[["l1","r2"],["l2","r4"],["l3","r3"],["l4","r1"]]},{"id":"ch2-match-009","type":"match-following","sectionId":"s5","difficulty":"medium","examRelevance":"high","tags":["groups","demands"],"title":"Match the community/group with their stance during the national movement","leftColumn":[{"id":"l1","text":"Muslim League"},{"id":"l2","text":"Hindu Mahasabha"},{"id":"l3","text":"Depressed Classes Association"},{"id":"l4","text":"Indian merchants and industrialists"}],"rightColumn":[{"id":"r1","text":"Feared dominance of Hindus in a democratic setup — demanded separate electorates"},{"id":"r2","text":"Supported CDM — wanted protection against imports and a rupee-sterling exchange ratio"},{"id":"r3","text":"Hostile to non-Hindus, opposed unity moves — wanted Hindu consolidation"},{"id":"r4","text":"Led by Ambedkar, demanded reserved seats and separate electorates for Dalits"}],"correctPairs":[["l1","r1"],["l2","r3"],["l3","r4"],["l4","r2"]]},{"id":"ch2-match-010","type":"match-following","sectionId":"s5","difficulty":"medium","examRelevance":"high","tags":["symbols","nationalism"],"title":"Match the image/symbol of Indian nationalism with its significance","leftColumn":[{"id":"l1","text":"Bharat Mata by Abanindranath Tagore"},{"id":"l2","text":"Tricolour flag (Swaraj flag)"},{"id":"l3","text":"Charkha (spinning wheel)"},{"id":"l4","text":"Vande Mataram (Bankim Chandra)"}],"rightColumn":[{"id":"r1","text":"Self-reliance — symbol of Swadeshi and rejection of foreign cloth"},{"id":"r2","text":"Song that became anthem of the national movement (from Anandamath)"},{"id":"r3","text":"Depicted as an ascetic figure — calm, composed, divine, bestowing learning"},{"id":"r4","text":"Red, green and white with spinning wheel — unity of all communities"}],"correctPairs":[["l1","r3"],["l2","r4"],["l3","r1"],["l4","r2"]]}],"timeline":[],"ncert":[{"id":"ch2-ncert-wib-1","type":"write-in-brief","number":1,"question":"Explain the following:","subParts":["a) Why growth of nationalism in the colonies is linked to an anti-colonial movement","b) How the First World War helped in the growth of the National Movement in India","c) Why Indians were outraged by the Rowlatt Act","d) Why Gandhiji decided to withdraw the Non-Cooperation Movement"],"keyPoints":["(a) Colonial peoples discovered shared oppression under foreign rule, which became the basis for unity — people with diverse communities, regions and languages were forged into a single nation through collective struggle against the colonial power","(b) WWI created new economic and political problems: war expenditure led to increased taxes and custom duties, forced recruitment in rural areas, crop failure + influenza epidemic (12-13 million deaths) — anger and hardship fuelled the national movement","(c) Rowlatt Act (1919) gave government power to repress political activities — trial without jury, detention without trial for 2 years — Indians saw it as unjust, autocratic and against basic civil liberties; passed despite united Indian opposition in Imperial Legislative Council","(d) Chauri Chaura (Feb 1922): a violent mob set fire to a police station killing 22 policemen — Gandhi felt the movement was turning violent and the masses were not yet ready for disciplined non-violent resistance; feared it would become a tool for violence"],"sampleAnswer":"(a) The growth of nationalism in the colonies was linked to an anti-colonial movement because people who were exploited and oppressed under colonial rule began to see that their problems had a common cause: foreign domination. Under colonialism, people belonging to different communities, regions, classes and languages discovered a shared bond of oppression. This collective sense of suffering under an alien power brought diverse groups together, and nationalist sentiment became inseparable from the demand to end colonial rule.\n\n(b) The First World War created a new economic and political situation in India. It led to a huge increase in defence expenditure, which was financed by war loans and increased taxes. Custom duties were raised and income tax was introduced. Through the war years, prices increased — doubling between 1913 and 1918 — leading to extreme hardship for the common people. Forced recruitment in rural areas caused widespread anger. Then in 1918-19, crops failed, resulting in acute food shortage. On top of this, the influenza epidemic killed 12-13 million people. All this fuelled discontent and created a situation ripe for mass mobilisation by nationalist leaders.\n\n(c) The Rowlatt Act of 1919 outraged Indians because it gave the government enormous, unjust powers to repress political activities. Under this Act, political prisoners could be detained for two years without trial, and cases could be tried without juries. It was passed through the Imperial Legislative Council despite unanimous opposition from Indian members. Indians saw it as a symbol of autocracy and a direct attack on their basic civil liberties — Gandhi called it a \"Black Act\" that no self-respecting Indian could submit to.\n\n(d) Gandhiji decided to withdraw the Non-Cooperation Movement after the Chauri Chaura incident of February 1922. At Chauri Chaura in the Gorakhpur district of United Provinces, a peaceful demonstration turned violent when the police fired upon the crowd. In retaliation, the angry mob set fire to the police station, killing 22 policemen. Gandhi felt deeply disturbed. He believed that the movement was turning violent because the people had not yet been properly trained in non-violence. He saw that satyagraha had to be withdrawn if it was becoming a tool of violence rather than moral persuasion.","marks":5},{"id":"ch2-ncert-wib-2","type":"write-in-brief","number":2,"question":"What is meant by the idea of satyagraha?","keyPoints":["Coined by Mahatma Gandhi — literally means \"insistence on truth\" (satya = truth, agraha = firmness)","Not passive resistance — it is an active, non-violent method of protest","Appeals to the conscience of the oppressor, not through physical force but through moral strength","The idea is that if the cause is just and the struggle is against injustice, physical force is not needed — the oppressor can be persuaded to see the truth through suffering and moral appeal","Developed by Gandhi during his time in South Africa (1893-1914)","Used successfully in Champaran (1917), Kheda (1917), and Ahmedabad mill workers'' strike (1918) before the national movements"],"sampleAnswer":"The idea of satyagraha was unique to Mahatma Gandhi. The term literally means \"insistence on truth\" — satya (truth) and agraha (firmness or insistence). It emphasised the power of truth and the need to search for truth. Satyagraha was not passive resistance — it was an active, non-violent method of mass agitation against the oppressor. Gandhi believed that if the cause was true and the struggle was against injustice, then physical force was not necessary to fight the oppressor. A satyagrahi could win the battle through non-violence by appealing to the conscience of the oppressor. People, including the oppressor, would be persuaded to see the truth instead of being forced to accept it through the use of violence. The dharma of non-violence could unite all Indians. Gandhi had successfully practised satyagraha in South Africa (1893-1914) and in India at Champaran (1917) against the indigo plantation system, at Kheda (1917) for revenue relaxation, and in the Ahmedabad mill workers'' strike (1918) for fair wages.","marks":3},{"id":"ch2-ncert-wib-3","type":"write-in-brief","number":3,"question":"Write a newspaper report on:","subParts":["a) The Jallianwala Bagh massacre","b) The Simon Commission"],"keyPoints":["(a) 13 April 1919, Amritsar, Punjab — General Dyer ordered troops to fire on a peaceful gathering in Jallianwala Bagh (enclosed ground with narrow entrances), hundreds killed, people had gathered for a Baisakhi fair, martial law imposed in Punjab, satyagrahis humiliated — forced to crawl, rub noses on ground, do salaam","(b) 1928 — Simon Commission sent from Britain to look into Indian constitutional matters — all members British, no Indian representation — greeted with slogan \"Simon Go Back\" across India, police lathi-charged demonstrators"],"sampleAnswer":"(a) MASSACRE AT JALLIANWALA BAGH — HUNDREDS KILLED IN AMRITSAR\nAmritsar, 14 April 1919: In a horrifying act of brutality, General Dyer yesterday ordered his troops to open fire on a large but peaceful crowd gathered at Jallianwala Bagh in Amritsar. Thousands of people, including women and children, had assembled at the enclosed ground to attend the annual Baisakhi fair, many unaware of the martial law that had been imposed. Without any warning, General Dyer blocked the only exit and ordered his troops to fire directly into the dense crowd. The firing continued until the ammunition was exhausted. Hundreds are reported killed and over a thousand wounded. Panicked people tried desperately to escape, many jumping into a well inside the compound. Martial law has been imposed across Punjab, and reports are emerging of humiliating punishments — Indians being forced to crawl on the streets and do salaam to every British officer. This act has sent a wave of shock and anger across the nation.\n\n(b) \"SIMON GO BACK\" — INDIA REJECTS ALL-WHITE COMMISSION\nNew Delhi, 1928: The Simon Commission, appointed by the British government to review India''s constitutional progress, has been met with fierce opposition across the country. The Commission, headed by Sir John Simon, consists entirely of British members — not a single Indian has been included. The Indian National Congress, the Muslim League and virtually all Indian political parties have united in their condemnation of this exclusion, calling it an insult to Indian self-respect. As the Commission arrived in Indian cities, it was greeted with black flags, hartals and the powerful slogan \"Simon Go Back\". In several cities, peaceful demonstrators were subjected to brutal lathi-charges by the police. The government''s decision to deny Indians any representation on a body deciding India''s future has only deepened the resolve for self-rule.","marks":5},{"id":"ch2-ncert-wib-4","type":"write-in-brief","number":4,"question":"Compare the images of Bharat Mata in this chapter with the image of Germania in Chapter 1.","keyPoints":["Bharat Mata by Abanindranath Tagore: ascetic, spiritual figure — wears saffron, holds books (learning), sheaf of grain (prosperity), white cloth (sanctity) — calm, composed, otherworldly","Other Bharat Mata images showed her with trishul, lion — more aggressive, militant, associated with power","Germania: crown of oak leaves (heroism), sword (readiness to fight), breastplate with eagle (German empire), olive branch — martial and political","Difference: Bharat Mata is more spiritual and civilisational, emphasising learning and nourishment; Germania is more political and military, emphasising power and war-readiness","Both are female allegories personifying the nation — turning abstract national identity into a recognisable image for the masses","Bharat Mata images varied — showing how different groups visualised India differently (spiritual vs militant)"],"sampleAnswer":"Both Bharat Mata and Germania are female allegories — symbolic female figures used to personify the nation and turn an abstract idea into a recognisable image that could inspire people.\n\nThe image of Bharat Mata painted by Abanindranath Tagore depicts her as an ascetic, spiritual figure. She is shown in a saffron sari, calm and composed, holding books and sheaves of grain in her four hands — symbolising learning, food and spiritual sanctity. The emphasis is on civilisational values: knowledge, nourishment and purity. She resembles a Hindu goddess, giving the national identity a distinctly spiritual quality. However, other images of Bharat Mata showed her with a trishul (trident) and standing beside a lion — a far more militant, powerful image. This shows that different groups had different visions of the nation.\n\nGermania, by contrast, is depicted in a much more political and martial manner. She wears a crown of oak leaves (symbolising heroism), holds a sword (readiness to fight) with an olive branch around it (willingness to make peace), and wears a breastplate with the eagle of the German empire (strength). Her imagery centres on military power and political authority.\n\nThe key difference is that the Indian national imagination drew on spiritual and civilisational imagery to represent the nation, while the European imagination relied more on military and political symbolism. Both, however, served the same purpose: making the nation tangible, visual and emotionally powerful for ordinary people.","marks":3},{"id":"ch2-ncert-disc-1","type":"discuss","number":1,"question":"List all the different social groups which joined the Non-Cooperation Movement of 1921. Then choose any three and write about their hopes and struggles to show why the Non-Cooperation Movement was a broad-based movement.","keyPoints":["Social groups: middle-class (teachers, lawyers, students), merchants and traders, peasants (Awadh), tribal people (Gudem Hills, Andhra), plantation workers (Assam)","Middle class: boycotted schools, courts, councils; returned titles; but economic hardship made some return when no alternative Indian institutions emerged","Peasants in Awadh (led by Baba Ramchandra): against talukdars/landlords, demanded reduction of revenue, abolition of begar, boycott of landlords — Oudh Kisan Sabha formed; sometimes went beyond Congress — looted bazaars, attacked landlord houses","Tribal people in Gudem Hills (Alluri Sitarama Raju): colonial government closed forests for shifting cultivation, forced begar — they attacked police stations, inspired by Gandhi but used guerrilla methods, not strict non-violence","Plantation workers in Assam: defied Inland Emigration Act (which prevented them from leaving), left plantations — they interpreted swaraj as freedom to move freely and return to their villages","Each group interpreted swaraj in their own way and joined with their own local grievances"],"sampleAnswer":"The Non-Cooperation Movement of 1921 drew in a wide range of social groups: the urban middle class (lawyers, teachers, students, headmasters), merchants and traders, peasants in the countryside (especially in Awadh and elsewhere), tribal people (Gudem Hills in Andhra Pradesh), and plantation workers in Assam. This remarkable breadth is what made it a truly mass movement.\n\nThree groups and their hopes and struggles:\n\n1. Peasants in Awadh: The peasant movement in Awadh was led by Baba Ramchandra, a sanyasi who had earlier been an indentured labourer in Fiji. The peasants were suffering at the hands of talukdars and landlords who demanded excessively high rents and a range of cesses. They demanded reduction of revenue, abolition of begar (forced labour), and social boycott of oppressive landlords. The Oudh Kisan Sabha was set up, and Jawaharlal Nehru, Baba Ramchandra and a few others went around the villages, understanding their grievances. However, peasant movements sometimes went beyond the Congress programme — they attacked merchants'' shops and looted bazaars, and in some places landlord houses were attacked. The peasants interpreted swaraj in their own way: freedom from exploitation by talukdars.\n\n2. Tribal People in the Gudem Hills (Andhra Pradesh): Tribal people depended on the forest for their livelihood — shifting cultivation, collecting forest produce, grazing cattle. When the colonial government began restricting their access to forests and demanding begar for road building, they revolted. Led by Alluri Sitarama Raju, who claimed he had special powers (making astrological predictions, could heal), the rebels attacked police stations and attempted to kill British officials. Raju was inspired by the Non-Cooperation Movement and the ideas of Gandhi, but his movement was far from non-violent — it used guerrilla tactics. For the tribals, swaraj meant the right to use the forests freely, as they always had.\n\n3. Plantation Workers in Assam: For plantation workers, the Non-Cooperation Movement was about freedom of movement. Under the Inland Emigration Act of 1859, plantation workers were not permitted to leave the tea gardens without permission. When they heard of the Non-Cooperation Movement, thousands defied this hated Act and left the plantations, heading home. They believed that Gandhi Raj was coming and that everyone would be given land in their own villages. Their interpretation of swaraj was the right to move freely and not be confined to the plantations like bonded labourers.\n\nThese examples show that the Non-Cooperation Movement succeeded in becoming a broad-based movement because each group could connect their own local grievances to the larger national struggle — but each also interpreted the meaning of \"swaraj\" in their own specific way.","marks":5},{"id":"ch2-ncert-disc-2","type":"discuss","number":2,"question":"Discuss the Salt March to make clear why it was an effective symbol of resistance against colonialism.","keyPoints":["Gandhi chose salt because it was consumed by the rich and poor alike — universal grievance, not a class issue","Salt tax was seen as deeply unjust — taxing a basic necessity of life, especially in a hot country","March from Sabarmati to Dandi (240 miles, 24 days, starting 12 March 1930) — theatrical, covered by press, built anticipation day by day","Thousands joined along the route — it grew from 78 marchers to a mass of supporters","Simple symbolic act: picking up sea salt = defying an unjust law without violence","Sparked parallel movements: Tamil Nadu, Kerala, Malabar — people broke salt law everywhere","Brought international attention to India''s cause — showed moral superiority of non-violent resistance","Demonstrated Gandhi''s genius for choosing symbols that connected with every Indian"],"sampleAnswer":"The Salt March (Dandi March) was one of the most effective symbols of resistance against colonialism, and Gandhi''s choice of salt as the basis of his campaign showed his remarkable political instinct.\n\nFirst, salt was a powerful symbol because it was used by every Indian — rich and poor, Hindu and Muslim, man and woman. The British salt tax, which made it illegal for anyone to manufacture or collect salt, was seen as deeply unjust because it taxed a basic necessity of life, essential for survival in India''s hot climate. Unlike issues around land or labour, which affected specific classes, the salt tax was a universal grievance that could unite the entire nation.\n\nSecond, the march itself was a masterpiece of political theatre. On 12 March 1930, Gandhi set out from his ashram at Sabarmati with 78 followers on a 240-mile march to the coastal town of Dandi. The march took 24 days, and with each day it attracted growing attention from the Indian and international press. Thousands of people joined along the route, and the march grew into a moving river of protest. The slow pace built anticipation and gave time for the entire country to focus on what was happening.\n\nThird, the act of defiance was brilliantly simple: on 6 April, Gandhi picked up a handful of sea salt, symbolically breaking the law. This simple act showed that unjust laws could be broken without violence, purely through moral courage. It was easy to understand and easy to replicate — and people did exactly that. Salt was manufactured illegally along the coasts of India, from Tamil Nadu to Malabar to Gujarat. The salt law was broken in massive numbers across the country.\n\nFinally, the Salt March brought international attention to India''s freedom struggle. Images of peaceful Indians being beaten by British police while making salt created global sympathy. The moral power of non-violent resistance was demonstrated to the world, undermining Britain''s claim to be a fair and just ruler.\n\nThe Salt March succeeded as a symbol because Gandhi connected the abstract demand for independence to a concrete, everyday injustice that every Indian could feel and understand.","marks":5},{"id":"ch2-ncert-disc-3","type":"discuss","number":3,"question":"Imagine you are a woman participating in the Civil Disobedience Movement. Explain what the experience meant to your life.","keyPoints":["Women participated in large numbers — a significant departure from earlier movements","Participated in protest marches, manufactured salt, picketed foreign cloth and liquor shops","Many were from high-caste families — came out of their homes for the first time into public life","In urban areas: educated women; in rural areas: peasant women joined in large numbers","Gandhi''s call gave them a sense of national duty and purpose beyond domestic roles","However, Gandhi saw women''s role mainly as symbolic — as nurturers, not as leaders or decision-makers","Congress was reluctant to give women positions of authority within the organisation","The movement gave women a taste of public participation, but true political equality remained elusive"],"sampleAnswer":"My name is Kamala, and I want to share what the Civil Disobedience Movement meant to a woman like me.\n\nWhen Gandhiji gave the call for Civil Disobedience, something stirred in me that I had never felt before. For the first time, I felt that the nation needed me — not as a mother or a wife, but as a citizen. I, along with thousands of women, came out of the confines of our homes to participate in protest marches, to manufacture salt, and to picket shops selling foreign cloth and liquor. In my city, we would stand outside the cloth merchants'' shops all day, urging people not to buy foreign goods. Many of us were arrested and sent to jail. There was fear, yes — but there was also an extraordinary sense of pride and purpose.\n\nThe movement changed the way I saw myself. Before this, my world had been limited to the household. But marching alongside other women, raising slogans, and being willing to go to jail for my country gave me a new identity. I was no longer just someone''s daughter or wife — I was a freedom fighter. The experience of public participation, of being part of a cause larger than oneself, was deeply liberating.\n\nBut I must also be honest about the limits. Gandhiji believed that women were suited to roles that were extensions of our domestic nature — he saw us as patient, enduring, selfless. He valued our participation, but mostly as a symbol of the nation''s moral strength. Within the Congress, we were rarely given positions of real authority or included in decision-making. When it came to negotiating with the British or determining the future of the nation, it was still the men who sat at the table.\n\nStill, what the movement gave us cannot be taken back. We proved — to the British, to our men, and most importantly to ourselves — that women could be brave, disciplined and committed to a public cause. The Civil Disobedience Movement was the first time many Indian women stepped into public life, and for many of us, there was no going back.","marks":5},{"id":"ch2-ncert-disc-4","type":"discuss","number":4,"question":"Why did political leaders differ sharply over the question of separate electorates?","keyPoints":["Separate electorates: only members of a particular community could vote for candidates of that community — introduced by British (Morley-Minto reforms, Lucknow Pact)","Muslim League & Muhammad Ali Jinnah: feared that in a Hindu-majority country, Muslims would always be outvoted — separate electorates guaranteed representation","B.R. Ambedkar: demanded separate electorates for Dalits (depressed classes) — argued that only Dalits could truly represent Dalits, mainstream parties would ignore their concerns","Gandhi opposed: believed separate electorates would permanently divide society along caste/religious lines, slow down integration, create vote banks that deepened divisions","Poona Pact (1932): Gandhi fasted unto death against separate electorates for Dalits; Ambedkar agreed to reserved seats within general electorate instead — compromise, but Ambedkar was bitter","The debate reflected deep tensions: was national unity possible without addressing the genuine fears of minorities and oppressed castes?"],"sampleAnswer":"The question of separate electorates became one of the most divisive issues in Indian politics because it touched on the fundamental tension between national unity and the genuine fears of minorities and oppressed communities.\n\nSeparate electorates meant that only members of a particular community (Muslim, Sikh, or Dalit) could vote for candidates from that same community. The British had introduced this system through the Morley-Minto reforms (1909) and it was continued through the Lucknow Pact (1916). The logic was that in a Hindu-majority country, minorities would always be outvoted in a general electorate, so they needed protected political space.\n\nMuslim leaders, particularly Muhammad Ali Jinnah and the Muslim League, supported separate electorates. They feared that in a democratic system with a Hindu majority, Muslim interests would be consistently ignored. Without guaranteed representation, they believed Muslims would become a permanent political minority, regardless of the promises of the Congress.\n\nDr B.R. Ambedkar demanded separate electorates for the Dalits (depressed classes) as well. He argued that the caste system had oppressed Dalits for centuries, and mainstream political parties — dominated by upper castes — would never genuinely represent Dalit interests. In his view, only Dalit representatives elected by Dalit voters could speak for the community. When the British government announced separate electorates for Dalits through the Communal Award (1932), Ambedkar accepted it.\n\nGandhi, however, was vehemently opposed to separate electorates for Dalits. He believed that this would permanently divide Hindu society by separating the \"depressed classes\" from the broader Hindu fold. He feared it would slow the process of social integration and create rigid political divisions along caste lines. He went on a fast unto death in Yeravda Jail, forcing Ambedkar into a compromise — the Poona Pact (1932) — which replaced separate electorates with reserved seats within the general electorate.\n\nThe debate was sharp because both sides had legitimate concerns. Gandhi wanted national unity and the end of untouchability through social reform from within. Ambedkar believed that without political power, Dalits would remain at the mercy of upper-caste goodwill. Similarly, Muslim leaders feared that grand promises of unity would not translate into real political representation. This unresolved tension over separate electorates continued to shape Indian politics and contributed to the eventual demand for Pakistan.","marks":5}],"mapIdentify":[{"id":"ch2-map-id-001","type":"map-identify","sectionId":"s1","difficulty":"easy","examRelevance":"high","tags":["jallianwala"],"mapId":"india-national-movement","question":"Identify the city where the Jallianwala Bagh massacre took place on 13 April 1919.","correctRegionId":"amritsar","hints":["It is in Punjab, in the north-west","General Dyer ordered the firing here"]},{"id":"ch2-map-id-002","type":"map-identify","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["salt-march"],"mapId":"india-national-movement","question":"Identify the coastal town where Gandhi broke the salt law in 1930, launching the Civil Disobedience Movement.","correctRegionId":"dandi","hints":["On the Gujarat coast","End-point of the 240-mile Salt March from Sabarmati"]},{"id":"ch2-map-id-003","type":"map-identify","sectionId":"s1","difficulty":"medium","examRelevance":"high","tags":["champaran"],"mapId":"india-national-movement","question":"Identify the place in Bihar where Gandhi led his first satyagraha in India (1917).","correctRegionId":"champaran","hints":["In Bihar, in the north","Indigo planters'' movement"]},{"id":"ch2-map-id-004","type":"map-identify","sectionId":"s1","difficulty":"medium","examRelevance":"high","tags":["non-cooperation"],"mapId":"india-national-movement","question":"Identify the city where a violent clash in February 1922 led Gandhi to call off the Non-Cooperation Movement.","correctRegionId":"chauri-chaura","hints":["In the United Provinces (Uttar Pradesh)","A police station was set on fire"]},{"id":"ch2-map-id-005","type":"map-identify","sectionId":"s1","difficulty":"easy","examRelevance":"medium","tags":["congress-session"],"mapId":"india-national-movement","question":"Identify the eastern city where the special Congress session of September 1920 adopted Non-Cooperation.","correctRegionId":"calcutta","hints":["Capital of Bengal","On the eastern side of the map"]}],"mapLabel":[{"id":"ch2-map-lb-001","type":"map-label","sectionId":"s1","difficulty":"medium","examRelevance":"high","tags":["congress-session"],"mapId":"india-national-movement","instruction":"Label the three Indian National Congress sessions on the map.","labels":[{"id":"lb1","text":"Calcutta (Sept 1920)","correctRegionId":"calcutta"},{"id":"lb2","text":"Nagpur (Dec 1920)","correctRegionId":"nagpur"},{"id":"lb3","text":"Lahore (Dec 1929)","correctRegionId":"lahore"}]},{"id":"ch2-map-lb-002","type":"map-label","sectionId":"s3","difficulty":"hard","examRelevance":"high","tags":["satyagraha"],"mapId":"india-national-movement","instruction":"Label the early satyagraha centres led by Gandhi.","labels":[{"id":"lb1","text":"Champaran (indigo planters)","correctRegionId":"champaran"},{"id":"lb2","text":"Kheda (peasants)","correctRegionId":"kheda"},{"id":"lb3","text":"Ahmedabad (mill workers)","correctRegionId":"ahmedabad"}]},{"id":"ch2-map-lb-003","type":"map-label","sectionId":"s3","difficulty":"medium","examRelevance":"high","tags":["civil-disobedience"],"mapId":"india-national-movement","instruction":"Label the key sites of mass protest.","labels":[{"id":"lb1","text":"Amritsar (Jallianwala Bagh)","correctRegionId":"amritsar"},{"id":"lb2","text":"Chauri Chaura","correctRegionId":"chauri-chaura"},{"id":"lb3","text":"Dandi (Salt March)","correctRegionId":"dandi"}]}]}}'::jsonb, now())
